INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86118, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：听到的是“层”（céng），指覆盖在表面的一层。"}, {"text": "成", "is_correct": false, "explanation": "chéng 与 céng 声母不同（ch/c），意思是完成、成为。"}, {"text": "从", "is_correct": false, "explanation": "cóng 与 céng 韵母不同（ong/eng），意思是从、跟随。"}, {"text": "藏", "is_correct": false, "explanation": "cáng 与 céng 韵母不同（ang/eng），意思是隐藏。"}], "explanations": {"层": "正确：听到的是“层”（céng），指覆盖在表面的一层。", "成": "chéng 与 céng 声母不同（ch/c），意思是完成、成为。", "从": "cóng 与 céng 韵母不同（ong/eng），意思是从、跟随。", "藏": "cáng 与 céng 韵母不同（ang/eng），意思是隐藏。"}, "sentence_index": null, "correct_answer": "层"}, "level_3": {"options": [{"text": "层", "is_correct": true, "explanation": "正确：“层”用于平铺在地上的一层，地上结了一层薄冰。"}, {"text": "颗", "is_correct": false, "explanation": "搭配：“颗”用于小而圆的东西，地上结的冰不能说“颗”。"}, {"text": "堆", "is_correct": false, "explanation": "语义：“堆”指堆积成堆的东西，与平铺结成的冰不符。"}, {"text": "串", "is_correct": false, "explanation": "搭配：“串”用于成串的东西，薄冰不能说“串”。"}], "explanations": {"层": "正确：“层”用于平铺在地上的一层，地上结了一层薄冰。", "颗": "搭配：“颗”用于小而圆的东西，地上结的冰不能说“颗”。", "堆": "语义：“堆”指堆积成堆的东西，与平铺结成的冰不符。", "串": "搭配：“串”用于成串的东西，薄冰不能说“串”。"}, "sentence_index": 6, "correct_answer": "层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在河边看见了一层船。", "explanation": "这里应该用〈艘〉或〈只〉。船可用“艘”或“只”计量；“层”只用于覆盖或叠放的东西，船不能铺成一层。"}, {"text": "我们在教室里做了一层练习。", "explanation": "这里应该用〈套〉。练习常用“套”计量；“层”只用于覆盖或叠放的东西，不能用来数练习。"}, {"text": "我们去动物园看了一层熊猫。", "explanation": "这里应该用〈只〉。熊猫用“只”计量；“层”不能用来数动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天看了一层电影。", "corrected_sentence": "我昨天看了一部电影。", "error_description": "量词“层”只用于覆盖、叠放或积累的东西，电影不是这样的东西，应该用“部”。错误是“一层电影”，正确应说“一部电影”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我们唱了一层歌。", "corrected_sentence": "他给我们唱了一首歌。", "error_description": "量词“层”只用于覆盖、叠放或积累的东西，歌不能这样计量，应该用“首”。错误是“一层歌”，正确应说“一首歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
