INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "县是比村子大、比城市小的一块地方。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "我家在一个小县里，不在大城市。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县比村子大，比城市小。", "target_word": "县", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个县不大，只有十几个村子。", "target_word": "县", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爷爷一直住在县里，没去过大城市。", "target_word": "县", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我们村到县里要坐一个小时的车。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小县的东西很便宜，大城市的东西很贵。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县有一座山和一条河，风景很好。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们开车去了一个很安静的小县。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大城市工作，可是家在县里。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县的孩子要去市里上高中。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "县城", "label": "复合词"}, {"form": "縣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "县：比村子大、比城市小的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86119, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县 xiàn（第四声）指比村子大、比城市小的地方。"}, {"text": "咸", "is_correct": false, "explanation": "咸 xián（第二声）与 xiàn 声调不同，意思是咸淡的咸。"}, {"text": "显", "is_correct": false, "explanation": "显 xiǎn（第三声）与 xiàn 声调不同，意思是明显。"}, {"text": "先", "is_correct": false, "explanation": "先 xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的先。"}, {"text": "向", "is_correct": false, "explanation": "向 xiàng 与 xiàn 韵母不同（ang 与 an），意思是方向。"}], "explanations": {"县": "正确：县 xiàn（第四声）指比村子大、比城市小的地方。", "咸": "咸 xián（第二声）与 xiàn 声调不同，意思是咸淡的咸。", "显": "显 xiǎn（第三声）与 xiàn 声调不同，意思是明显。", "先": "先 xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的先。", "向": "向 xiàng 与 xiàn 韵母不同（ang 与 an），意思是方向。"}, "sentence_index": null, "correct_answer": "县"}, "level_3": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县是比村子大、比城市小的地方，可以作为居住地，与句中的“小县”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“我家在……里”说的是住处，学校不能作为家的所在地。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司不是住处，“我家在一个小公司里”无法成立。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“我家在……里”说的是住处，医院不是家所在的地方。"}], "explanations": {"县": "正确：县是比村子大、比城市小的地方，可以作为居住地，与句中的“小县”相符。", "学校": "语义：“我家在……里”说的是住处，学校不能作为家的所在地。", "公司": "语义：公司不是住处，“我家在一个小公司里”无法成立。", "医院": "语义：“我家在……里”说的是住处，医院不是家所在的地方。"}, "sentence_index": 0, "correct_answer": "县"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把县放进书包里，带去了学校。", "explanation": "县是一块很大的地方，不是能放进书包的东西。"}, {"text": "我们县只有几十户人家，大家都认识。", "explanation": "这里应该用〈村子〉。县管辖的范围远大于村子，几十户人家的规模只能说村子。"}, {"text": "这个县的省委每周都开会。", "explanation": "这里应该用〈省〉。省委是省级机构，县一级没有省委，不能说“县的省委”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86119, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县 xiàn（第四声）指比村子大、比城市小的地方。"}, {"text": "闲", "is_correct": false, "explanation": "闲 xián（第二声）与 xiàn 声调不同，意思是空闲。"}, {"text": "鲜", "is_correct": false, "explanation": "鲜 xiān（第一声）与 xiàn 声调不同，意思是新鲜。"}, {"text": "显", "is_correct": false, "explanation": "显 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。"}, {"text": "像", "is_correct": false, "explanation": "像 xiàng 与 xiàn 韵母不同（ang 与 an），意思是像一样。"}], "explanations": {"县": "正确：县 xiàn（第四声）指比村子大、比城市小的地方。", "闲": "闲 xián（第二声）与 xiàn 声调不同，意思是空闲。", "鲜": "鲜 xiān（第一声）与 xiàn 声调不同，意思是新鲜。", "显": "显 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。", "像": "像 xiàng 与 xiàn 韵母不同（ang 与 an），意思是像一样。"}, "sentence_index": null, "correct_answer": "县"}, "level_3": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县可以有山有河，风景很好，与句中描述相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会“有一座山和一条河”，句中描述的是地方风景。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不能有“一座山和一条河”，与“风景很好”的说法冲突。"}, {"text": "人", "is_correct": false, "explanation": "搭配：“风景很好”描述的是地方，不说人的风景。"}], "explanations": {"县": "正确：县可以有山有河，风景很好，与句中描述相符。", "房子": "语义：房子不会“有一座山和一条河”，句中描述的是地方风景。", "房间": "语义：房间不能有“一座山和一条河”，与“风景很好”的说法冲突。", "人": "搭配：“风景很好”描述的是地方，不说人的风景。"}, "sentence_index": 6, "correct_answer": "县"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的县是一个独立国家，有自己的首都。", "explanation": "这里把县说成了主权国家。县是地方行政区划，隶属于市或地区，不是独立国家，没有自己的首都。"}, {"text": "这位县是我的老同学，我们每天一起走路上学。", "explanation": "这里应该用〈他〉。县指行政区划，不指人；“这位”只能用于人。"}, {"text": "妈妈做了一大碗县，我们都很爱吃。", "explanation": "这里应该用〈面条〉。县是行政区划，不是食物，不能用来做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的老家在一座小县里，离大城市很远。", "corrected_sentence": "我的老家在一个小县里，离大城市很远。", "error_description": "量词错误：“县”应搭配量词“个”，不能用“座”（“座”多用于山、桥、楼、城市等）。正确：我的老家在一个小县里，离大城市很远。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了一座小县，那里有个很好的博物馆。", "corrected_sentence": "我们去了一个小县，那里有个很好的博物馆。", "error_description": "量词错误：“县”应搭配量词“个”，不能用“座”（“座”多用于山、桥、楼、城市等）。正确：我们去了一个小县，那里有个很好的博物馆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
