INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国地方行政区划单位，隶属于市或地区。", "primary_collocate": null, "pronunciation": "xiàn", "ipa": "ɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这个县属于我们省的一个市。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国有一千多个县。", "target_word": "县", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "县比市小一级，管着很多村子。", "target_word": "县", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县的人口不到五十万。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个市有好几个县。", "target_word": "县", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "县里新建了一条高速公路。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县离省会有两百公里。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府把这个县的路修好了。", "target_word": "县", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们市下面有八个县，这是最小的一个。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月坐车去县里开一次会。", "target_word": "县", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "县城", "label": "复合词"}, {"form": "县长", "label": "复合词"}, {"form": "縣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "县：中国的县级地方行政区划单位，归市或地区管", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86120, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县 xiàn（第四声）指中国的县级地方行政区划，隶属于市或地区。"}, {"text": "先", "is_correct": false, "explanation": "先 xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的先。"}, {"text": "显", "is_correct": false, "explanation": "显 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。"}, {"text": "闲", "is_correct": false, "explanation": "闲 xián（第二声）与 xiàn 声调不同，意思是空闲。"}, {"text": "向", "is_correct": false, "explanation": "向 xiàng 与 xiàn 韵母不同（ang 与 an），意思是方向。"}], "explanations": {"县": "正确：县 xiàn（第四声）指中国的县级地方行政区划，隶属于市或地区。", "先": "先 xiān（第一声）与 xiàn（第四声）声调不同，意思是先后的先。", "显": "显 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。", "闲": "闲 xián（第二声）与 xiàn 声调不同，意思是空闲。", "向": "向 xiàng 与 xiàn 韵母不同（ang 与 an），意思是方向。"}, "sentence_index": null, "correct_answer": "县"}, "level_3": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县是市辖的行政单位，与“属于我们省的一个市”相符。"}, {"text": "国家", "is_correct": false, "explanation": "语义：国家是最高层级的政治实体，不隶属于市，与句中的“属于……的一个市”不符。"}, {"text": "省", "is_correct": false, "explanation": "语义：省比市大，不能隶属于市，句中说的是“属于一个市”。"}, {"text": "洲", "is_correct": false, "explanation": "搭配：“属于……的一个市”搭配的是行政单位，“洲”不能用于这一结构。"}], "explanations": {"县": "正确：县是市辖的行政单位，与“属于我们省的一个市”相符。", "国家": "语义：国家是最高层级的政治实体，不隶属于市，与句中的“属于……的一个市”不符。", "省": "语义：省比市大，不能隶属于市，句中说的是“属于一个市”。", "洲": "搭配：“属于……的一个市”搭配的是行政单位，“洲”不能用于这一结构。"}, "sentence_index": 0, "correct_answer": "县"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个县有很多城市。", "explanation": "这里应该用〈省〉。县是比市小一级的行政单位，管着很多村子，不能像省那样管辖很多城市。"}, {"text": "我们县是这个村子里的一个小地方。", "explanation": "这里把大小说反了。县比村子大，管着很多村子，不能在村子里面。"}, {"text": "这个县的省长每周都下乡。", "explanation": "这里应该用〈省〉。省长管理省级行政区，县一级的负责人是县长，不能说“县的省长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86120, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县 xiàn（第四声）指中国的县级地方行政区划。"}, {"text": "闲", "is_correct": false, "explanation": "闲 xián（第二声）与 xiàn 声调不同，意思是空闲。"}, {"text": "鲜", "is_correct": false, "explanation": "鲜 xiān（第一声）与 xiàn 声调不同，意思是新鲜。"}, {"text": "显", "is_correct": false, "explanation": "显 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。"}, {"text": "像", "is_correct": false, "explanation": "像 xiàng 与 xiàn 韵母不同（ang 与 an），意思是像一样。"}], "explanations": {"县": "正确：县 xiàn（第四声）指中国的县级地方行政区划。", "闲": "闲 xián（第二声）与 xiàn 声调不同，意思是空闲。", "鲜": "鲜 xiān（第一声）与 xiàn 声调不同，意思是新鲜。", "显": "显 xiǎn（第三声）与 xiàn（第四声）声调不同，意思是明显。", "像": "像 xiàng 与 xiàn 韵母不同（ang 与 an），意思是像一样。"}, "sentence_index": null, "correct_answer": "县"}, "level_3": {"options": [{"text": "县", "is_correct": true, "explanation": "正确：县是具体的行政地域，可以离省会有一段距离，与句中描述相符。"}, {"text": "大洲", "is_correct": false, "explanation": "语义：大洲的范围远超省，不能与省会只相隔两百公里相提并论。"}, {"text": "大陆", "is_correct": false, "explanation": "语义：大陆的范围远大于省，“离省会有两百公里”不能用来描述它。"}, {"text": "宇宙", "is_correct": false, "explanation": "搭配：“离……有两百公里”只用于具体地点，不能用于“宇宙”。"}], "explanations": {"县": "正确：县是具体的行政地域，可以离省会有一段距离，与句中描述相符。", "大洲": "语义：大洲的范围远超省，不能与省会只相隔两百公里相提并论。", "大陆": "语义：大陆的范围远大于省，“离省会有两百公里”不能用来描述它。", "宇宙": "搭配：“离……有两百公里”只用于具体地点，不能用于“宇宙”。"}, "sentence_index": 6, "correct_answer": "县"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们县有自己的货币，是一个独立的国家。", "explanation": "这里把县说成了主权国家。县是地方行政区划，隶属于市或地区，不是独立国家，不会有自己的货币。"}, {"text": "这位县是我最好的朋友，我们从小一起长大。", "explanation": "这里应该用〈他〉。县指行政区划，不能指人；“这位”只能用于人。"}, {"text": "我在饭馆点了一个县，味道很好。", "explanation": "这里应该用〈菜〉。县是行政区划，不是食物，不能用来点菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座县离省会很远。", "corrected_sentence": "这个县离省会很远。", "error_description": "量词错误：“县”是行政单位，应用量词“个”，不用“座”（“座”多用于山、桥、楼、城市等）。正确：这个县离省会很远。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的城县很小，只有一条街。", "corrected_sentence": "我们的县城很小，只有一条街。", "error_description": "语素顺序错误：“县城”是由“县”和“城”组成的复合词，顺序不能颠倒。正确：我们的县城很小，只有一条街。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
