INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不确定的若干年。", "primary_collocate": null, "pronunciation": "jǐ nián", "ipa": "tɕi˨˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他去国外工作了，过了几年才回来。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前几年这里还是一片农田。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再过几年，我就要退休了。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几年前，他在这家公司上班。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道他会在这里住几年。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她离开家乡几年后，变了很多。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了几年，这个小镇变得很热闹。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说过，再等几年，孩子就能自己做饭了。", "target_word": "几年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前几年天气没有这么热，现在夏天太难熬了。", "target_word": "几年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没过几年，他们就搬到了大城市。", "target_word": "几年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "前几年", "label": "复合"}, {"form": "好几年", "label": "复合"}], "register": "通用", "sense_fingerprint": "不确定的若干年，泛指过去或将来的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adca781d-1525-4feb-b95c-ac2c37686162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几年", "is_correct": true, "explanation": "“几年”指不确定的若干年，与“过了……才回来”这种长时段相合。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：“半夜”指深夜的一段时间，与“去国外工作”的长时段不符。"}, {"text": "半个钟头", "is_correct": false, "explanation": "语义：“半个钟头”太短，与“去国外工作”的长时段不符。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“过了”后接的时段要与“去国外工作了”相称，“清晨”只指一天的早晨，不能这样搭配。"}], "explanations": {"几年": "“几年”指不确定的若干年，与“过了……才回来”这种长时段相合。", "半夜": "语义：“半夜”指深夜的一段时间，与“去国外工作”的长时段不符。", "半个钟头": "语义：“半个钟头”太短，与“去国外工作”的长时段不符。", "清晨": "搭配：“过了”后接的时段要与“去国外工作了”相称，“清晨”只指一天的早晨，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "几年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生日是几年，我忘了。", "explanation": "这里应该用〈某月某日〉。“几年”指不确定的年数，不能指一个具体的日期。"}, {"text": "我昨天下班，花了几年才到家。", "explanation": "这里应该用〈一个小时〉。“几年”指较长的时段，不能用来说一次很短的行程。"}, {"text": "我们明天见面，几年后再说吧。", "explanation": "这里应该用〈过几天〉。“几年后”指很远的将来，与“明天见面”相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几年", "is_correct": true, "explanation": "“几年”指不确定的若干年，与“过了……这个小镇变得很热闹”的渐进变化相合。"}, {"text": "一本书", "is_correct": false, "explanation": "语义：“一本书”是物量，不能作“过了”的时段，句意不通。"}, {"text": "几块钱", "is_correct": false, "explanation": "语义：“几块钱”是金额，不能作“过了”的时段，句意不通。"}, {"text": "一张纸", "is_correct": false, "explanation": "语义：“一张纸”是物量，不能作“过了”的时段，句意不通。"}], "explanations": {"几年": "“几年”指不确定的若干年，与“过了……这个小镇变得很热闹”的渐进变化相合。", "一本书": "语义：“一本书”是物量，不能作“过了”的时段，句意不通。", "几块钱": "语义：“几块钱”是金额，不能作“过了”的时段，句意不通。", "一张纸": "语义：“一张纸”是物量，不能作“过了”的时段，句意不通。"}, "sentence_index": 6, "correct_answer": "几年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小学到大学，正好读了几年。", "explanation": "这里应该用〈十六年〉。“几年”是不确定的年数，而“正好”要求精确的数字，两者不能同用。"}, {"text": "他的年龄是几年，已经二十岁了。", "explanation": "这里应该用〈几岁〉。“几年”指年数，不能用来说年龄。"}, {"text": "这件事我想了几年，三分钟就想好了。", "explanation": "这里应该用〈几分钟〉。“几年”指长时段，与“三分钟就想好”相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在北京读书，过着几年才毕业。", "corrected_sentence": "他在北京读书，过了几年才毕业。", "error_description": "错误：“过着几年”。正确：“过了几年”。“过了”表示时段已经过去；“着”表示持续状态，不能与“几年”这样已完成的时段搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在上海工作了很几年，现在才回家。", "corrected_sentence": "她在上海工作了好几年，现在才回家。", "error_description": "错误：“很几年”。正确：“好几年”。“好几”是固定说法，表示数量多，不能用“很”修饰“几”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
