INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86123, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收是把东西拿回来放好。", "primary_collocate": null, "pronunciation": "shōu", "ipa": "ʂoʊ˥", "syllable_count": 1, "sentences": [{"text": "请把桌上的书收好。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把玩具收到箱子里。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱收在抽屉里。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，把东西收起来。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，快把衣服收进来。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，妈妈把碗收好了。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山了，奶奶去收被子。", "target_word": "收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "衣服干了，你去阳台收一下吧。", "target_word": "收", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们玩完以后，要把玩具收好。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房太乱了，快把锅和碗收一收。", "target_word": "收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收了", "label": "体标"}, {"form": "收着", "label": "体标"}, {"form": "收过", "label": "体标"}, {"form": "收一收", "label": "重叠"}], "register": "中性", "sense_fingerprint": "收：把东西拿回来放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86123, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收", "is_correct": true, "explanation": "收（shōu）是本词，指把东西拿回来放好。"}, {"text": "手", "is_correct": false, "explanation": "手（shǒu）与收（shōu）声调不同（第三声与第一声），意思是手。"}, {"text": "瘦", "is_correct": false, "explanation": "瘦（shòu）与收（shōu）声调不同（第四声与第一声），意思是瘦。"}, {"text": "搜", "is_correct": false, "explanation": "搜（sōu）与收（shōu）声母不同（s/sh），意思是搜索。"}], "explanations": {"收": "收（shōu）是本词，指把东西拿回来放好。", "手": "手（shǒu）与收（shōu）声调不同（第三声与第一声），意思是手。", "瘦": "瘦（shòu）与收（shōu）声调不同（第四声与第一声），意思是瘦。", "搜": "搜（sōu）与收（shōu）声母不同（s/sh），意思是搜索。"}, "sentence_index": null, "correct_answer": "收"}, "level_3": {"options": [{"text": "收", "is_correct": true, "explanation": "“收好”指把书放好，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于“书”，“吃好书”句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”不能用于“书”，“煮好书”句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只和衣物等搭配，不能搭配“书”。"}], "explanations": {"收": "“收好”指把书放好，符合句意。", "吃": "语义：“吃”不能用于“书”，“吃好书”句意不通。", "煮": "语义：“煮”不能用于“书”，“煮好书”句意不通。", "穿": "搭配：“穿”只和衣物等搭配，不能搭配“书”。"}, "sentence_index": 0, "correct_answer": "收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把面包收进肚子里。", "explanation": "这里应该用〈吃〉。吃东西要说“吃”，“收”指把东西拿回来放好，不能指把食物吃进肚子。"}, {"text": "他每天收西装上班。", "explanation": "这里应该用〈穿〉。穿衣服上班要说“穿”，“收”指把东西拿回来放好，不用于穿戴。"}, {"text": "我把画收在墙上。", "explanation": "这里应该用〈挂〉。把画挂在墙上要说“挂”，“收”指把东西拿回来放好，不能说收在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86123, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "收", "is_correct": true, "explanation": "收（shōu）是本词，指把东西拿回来放好。"}, {"text": "首", "is_correct": false, "explanation": "首（shǒu）与收（shōu）声调不同（第三声与第一声），意思是首先、头。"}, {"text": "寿", "is_correct": false, "explanation": "寿（shòu）与收（shōu）声调不同（第四声与第一声），意思是寿命。"}, {"text": "州", "is_correct": false, "explanation": "州（zhōu）与收（shōu）声母不同（zh/sh），声调相同，意思是州、地区。"}], "explanations": {"收": "收（shōu）是本词，指把东西拿回来放好。", "首": "首（shǒu）与收（shōu）声调不同（第三声与第一声），意思是首先、头。", "寿": "寿（shòu）与收（shōu）声调不同（第四声与第一声），意思是寿命。", "州": "州（zhōu）与收（shōu）声母不同（zh/sh），声调相同，意思是州、地区。"}, "sentence_index": null, "correct_answer": "收"}, "level_3": {"options": [{"text": "收", "is_correct": true, "explanation": "“收被子”指把晾着的被子收回来，符合句意。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”用于喂养动物或人，不能用于“被子”。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”用于烹饪食物，不能用于“被子”。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不能搭配“被子”。"}], "explanations": {"收": "“收被子”指把晾着的被子收回来，符合句意。", "喂": "语义：“喂”用于喂养动物或人，不能用于“被子”。", "煎": "语义：“煎”用于烹饪食物，不能用于“被子”。", "戴": "搭配：“戴”用于帽子、眼镜等，不能搭配“被子”。"}, "sentence_index": 6, "correct_answer": "收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用抹布收桌子。", "explanation": "这里应该用〈擦〉。擦桌子要说“擦”，“收”指把东西拿回来放好，不用于擦拭。"}, {"text": "他每天早上收自行车去上学。", "explanation": "这里应该用〈骑〉。骑自行车上学要说“骑”，“收”指把东西拿回来放好，不用于骑车。"}, {"text": "他每天晚上收一杯咖啡。", "explanation": "这里应该用〈喝〉。喝咖啡要说“喝”，“收”指拿回或接受，不能说收咖啡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把书收了完。", "corrected_sentence": "我已经把书收完了。", "error_description": "补语“完”应紧跟动词，说“收完了”；“收了完”错误，“了”应放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你把伞收来起吧。", "corrected_sentence": "你把伞收起来吧。", "error_description": "补语“起来”应紧跟动词且不能拆开或颠倒，应说“收起来”，不说“收来起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
