INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“之间”是说在两个东西的中间。", "primary_collocate": null, "pronunciation": "zhī jiān", "ipa": "ʈ͡ʂɨ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "小猫夹在两把椅子之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河在两座山之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我坐在爸爸和妈妈之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书放在电脑和杯子之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校在公园和商店之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一棵树长在房子和路之间。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的座位夹在第三排和第四排之间。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师站在两个学生之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "墙和桌子之间有一只小狗。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行在花店和饭馆之间，你一看就知道。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "位于两个事物中间的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 花店 (Zipf 3.01), 饭馆 (Zipf 3.21), 一看 (Zipf 3.76)']::text[], '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86125, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之间", "is_correct": true, "explanation": "正确。「之间」表示位于两把椅子的中间，与句意相符。"}, {"text": "之上", "is_correct": false, "explanation": "搭配：「之上」指在某物的上方，「夹在两把椅子之上」说不通，与“两把椅子”的中间位置不符。"}, {"text": "之外", "is_correct": false, "explanation": "语义：「之外」表示在范围以外，“夹在两把椅子之外”指在两者之外，而不是中间。"}, {"text": "之下", "is_correct": false, "explanation": "语义：「之下」表示在下方，“夹在两把椅子之下”描述的是在椅子底下，而不是中间。"}], "explanations": {"之间": "正确。「之间」表示位于两把椅子的中间，与句意相符。", "之上": "搭配：「之上」指在某物的上方，「夹在两把椅子之上」说不通，与“两把椅子”的中间位置不符。", "之外": "语义：「之外」表示在范围以外，“夹在两把椅子之外”指在两者之外，而不是中间。", "之下": "语义：「之下」表示在下方，“夹在两把椅子之下”描述的是在椅子底下，而不是中间。"}, "sentence_index": 0, "correct_answer": "之间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书放在那只盒子之间。", "explanation": "这里应该用〈之中〉。「之间」要两个或以上的对象，这里只有“那只盒子”一个，“盒子之中”才表示放在里面。"}, {"text": "他站在那棵树之间。", "explanation": "「之间」要求两个或以上的对象，这里只有“那棵树”一个，不能用「之间」。"}, {"text": "灯挂在天花板之间。", "explanation": "这里应该用〈之上〉。灯挂在天花板的上方，「之间」指两者的中间位置，“天花板之间”不符合句意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之间", "is_correct": true, "explanation": "正确。「之间」表示位于第三排和第四排的中间，与句意相符。"}, {"text": "之后", "is_correct": false, "explanation": "语义：「之后」表示在后面，“夹在第三排和第四排之后”说不通，位置不在两排中间。"}, {"text": "之东", "is_correct": false, "explanation": "语义：「之东」是方位词，两排座位是前后排的关系，不能说“之东”。"}, {"text": "之北", "is_correct": false, "explanation": "搭配：「之北」需要明确的方位参照，排与排之间的位置不用方位词，“之北”搭配不当。"}], "explanations": {"之间": "正确。「之间」表示位于第三排和第四排的中间，与句意相符。", "之后": "语义：「之后」表示在后面，“夹在第三排和第四排之后”说不通，位置不在两排中间。", "之东": "语义：「之东」是方位词，两排座位是前后排的关系，不能说“之东”。", "之北": "搭配：「之北」需要明确的方位参照，排与排之间的位置不用方位词，“之北”搭配不当。"}, "sentence_index": 6, "correct_answer": "之间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书都在箱子之间，只有一个箱子。", "explanation": "这里应该用〈之内〉。「箱子之间」需要两个以上的箱子，只有一个箱子时要说「箱子之内」。"}, {"text": "猫在一张桌子之间睡觉。", "explanation": "这里应该用〈之下〉。「之间」要两个或以上的对象，这里只有一张桌子，猫应该睡在桌子下面。"}, {"text": "市场在这座城市之间。", "explanation": "这里应该用〈之内〉。「之间」要两个或以上的对象，这里只说“这座城市”，应说「这座城市之内」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书放在两个抽屉之间里。", "corrected_sentence": "书放在两个抽屉之间。", "error_description": "「之间」本身已是方位词，后面不能再加「里」，应说「两个抽屉之间」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子在两张桌子的之间。", "corrected_sentence": "椅子在两张桌子之间。", "error_description": "「之间」前面不能加「的」，应说「两张桌子之间」，不能说「两张桌子的之间」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
