INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，表示在两者的中间或一定范围内。", "primary_collocate": null, "pronunciation": "zhī jiān", "ipa": "ʈ͡ʂɨ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "学生之间应该互相尊重。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家在学校和医院之间。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友之间要互相帮助。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的年纪在二十到三十岁之间。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和妹妹之间没有秘密。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京和上海之间有高铁。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两个孩子之间只差一岁。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在八点到九点之间给我打电话。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国之间的关系越来越好了。", "target_word": "之间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们之间的感情很深。", "target_word": "之间", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两者的中间，或某个范围、关系之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之间", "is_correct": true, "explanation": "正确。「之间」表示学生彼此之间的关系，与“应该互相尊重”的句意相符。"}, {"text": "之外", "is_correct": false, "explanation": "语义：「之外」表示在某个范围以外，“学生之外应该互相尊重”说的不是学生彼此之间。"}, {"text": "之前", "is_correct": false, "explanation": "语义：「之前」指时间或位置在前，“学生之前应该互相尊重”语义不通。"}, {"text": "之上", "is_correct": false, "explanation": "搭配：「之上」多用于高处或抽象的范围，不能用“学生之上”表示彼此之间的关系。"}], "explanations": {"之间": "正确。「之间」表示学生彼此之间的关系，与“应该互相尊重”的句意相符。", "之外": "语义：「之外」表示在某个范围以外，“学生之外应该互相尊重”说的不是学生彼此之间。", "之前": "语义：「之前」指时间或位置在前，“学生之前应该互相尊重”语义不通。", "之上": "搭配：「之上」多用于高处或抽象的范围，不能用“学生之上”表示彼此之间的关系。"}, "sentence_index": 0, "correct_answer": "之间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家在那座山之间。", "explanation": "「之间」要求两个或以上的对象，这里只提到一座山，不能说“那座山之间”。"}, {"text": "书都在这张桌子之间。", "explanation": "这里应该用〈之上〉。「之间」要两个或以上的对象，这里只有“这张桌子”一个，书是放在桌子上面，应说「之上」。"}, {"text": "他的年纪在二十岁之间。", "explanation": "这里应该用〈以上〉。「之间」需要两个端点，这里只有“二十岁”一个数，应说“二十岁以上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之间", "is_correct": true, "explanation": "正确。「之间」表示两个孩子之间的差距，“只差一岁”指的就是两人之间的年龄差。"}, {"text": "之后", "is_correct": false, "explanation": "语义：「之后」表示在后面，“这两个孩子之后只差一岁”说的不是两人之间的差距。"}, {"text": "之下", "is_correct": false, "explanation": "搭配：「之下」多指位置在下方，不用于表示两人的年龄差距。"}, {"text": "之东", "is_correct": false, "explanation": "语义：「之东」是方位词，“这两个孩子之东”指位置，与年龄差无关。"}], "explanations": {"之间": "正确。「之间」表示两个孩子之间的差距，“只差一岁”指的就是两人之间的年龄差。", "之后": "语义：「之后」表示在后面，“这两个孩子之后只差一岁”说的不是两人之间的差距。", "之下": "搭配：「之下」多指位置在下方，不用于表示两人的年龄差距。", "之东": "语义：「之东」是方位词，“这两个孩子之东”指位置，与年龄差无关。"}, "sentence_index": 6, "correct_answer": "之间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的钥匙在抽屉之间。", "explanation": "这里应该用〈之内〉。「之间」要求两个或以上的对象，这里只有“抽屉”一个，应说「抽屉之内」。"}, {"text": "他在那位同学之间最聪明。", "explanation": "这里应该用〈之中〉。「之间」要求两个或以上的对象，这里只指“那位同学”一人，应说「同学之中」。"}, {"text": "这个问题在我的能力之间。", "explanation": "这里应该用〈之外〉。「能力之外」表示超出某个范围，“能力之间”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和弟弟的之间有很多秘密。", "corrected_sentence": "我和弟弟之间有很多秘密。", "error_description": "「之间」前面不能加「的」，应说「我和弟弟之间」，不能说「我和弟弟的之间」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两条路之间中间的距离很远。", "corrected_sentence": "两条路之间的距离很远。", "error_description": "「之间」本身已经表示中间，后面不能再加「中间」，应说「两条路之间的距离」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夜里", "is_correct": true, "explanation": "正确：夜里指夜间，与白天（日里）相反。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天指季节，与日里表示的时段不构成反义关系。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间指空间，与日里表示的时间不构成反义关系。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是物品，与日里表示的时间无反义关系。"}], "correct_answer": "夜里", "explanations": {"夜里": "正确：夜里指夜间，与白天（日里）相反。", "春天": "语义：春天指季节，与日里表示的时段不构成反义关系。", "房间": "语义：房间指空间，与日里表示的时间不构成反义关系。", "电脑": "语义：电脑是物品，与日里表示的时间无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夜里", "is_correct": true, "explanation": "正确：夜里指夜间，与白天（日里）相反。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天指季节，与日里表示的时段不构成反义关系。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，与日里表示的时间无反义关系。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园指地点，与日里表示的时间无反义关系。"}], "correct_answer": "夜里", "explanations": {"夜里": "正确：夜里指夜间，与白天（日里）相反。", "冬天": "语义：冬天指季节，与日里表示的时段不构成反义关系。", "书桌": "语义：书桌是家具，与日里表示的时间无反义关系。", "公园": "语义：公园指地点，与日里表示的时间无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "白天；日间。", "primary_collocate": null, "pronunciation": "rì lǐ", "ipa": "ʐɨ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "日里他在外面工作，晚上才回家。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的日里很热，晚上才凉快。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里街上人多，晚上很安静。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她日里在学校教书，夜里写文章。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里天气很好，我们去公园玩儿。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里有太阳，夜里能看见星星。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他日里睡觉，晚上出去上班。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里村里的人都在田里干活。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日里我很少在家，常常去图书馆。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店日里不开门，夜里才做生意。", "target_word": "日里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "白天，日间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d125fbf-5287-4485-9a68-7d0834fbb130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日里", "is_correct": true, "explanation": "正确：日里指白天，“日里他在外面工作，晚上才回家”成立。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：夜里指夜间，与后半句的“晚上”时间重叠，句意矛盾。"}, {"text": "半夜", "is_correct": false, "explanation": "语义：半夜指深夜，与“在外面工作”的时段冲突，句子不通。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：午夜是深夜，与后文“晚上才回家”的安排矛盾，句子不通。"}], "explanations": {"日里": "正确：日里指白天，“日里他在外面工作，晚上才回家”成立。", "夜里": "语义：夜里指夜间，与后半句的“晚上”时间重叠，句意矛盾。", "半夜": "语义：半夜指深夜，与“在外面工作”的时段冲突，句子不通。", "午夜": "语义：午夜是深夜，与后文“晚上才回家”的安排矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "日里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们日里去看星星。", "explanation": "这里应该用〈晚上〉。日里指白天，看星星要在晚上。"}, {"text": "天黑以后，他日里出门散步。", "explanation": "这里应该用〈夜里〉。日里指白天，天黑以后应说夜里。"}, {"text": "她日里凌晨两点还在写文章。", "explanation": "这里应该用〈半夜〉。日里指白天，凌晨两点是夜里，应说半夜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日里", "is_correct": true, "explanation": "正确：日里指白天，“他日里睡觉，晚上出去上班”成立。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：夜里睡觉与后文“晚上出去上班”都在夜间，句意矛盾。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜指夜里，与后文“晚上出去上班”的时段冲突。"}, {"text": "星期", "is_correct": false, "explanation": "语义：星期是一周的单位，不能指睡觉的时段，句子不通。"}], "explanations": {"日里": "正确：日里指白天，“他日里睡觉，晚上出去上班”成立。", "夜里": "语义：夜里睡觉与后文“晚上出去上班”都在夜间，句意矛盾。", "深夜": "语义：深夜指夜里，与后文“晚上出去上班”的时段冲突。", "星期": "语义：星期是一周的单位，不能指睡觉的时段，句子不通。"}, "sentence_index": 6, "correct_answer": "日里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他日里在月光下读书。", "explanation": "这里应该用〈夜里〉。日里指白天，月光下读书应说夜里。"}, {"text": "他日里和朋友一起在夜市吃烧烤。", "explanation": "这里应该用〈晚上〉。日里指白天，夜市要在晚上才开。"}, {"text": "日里的月亮很圆，我们在院子里赏月。", "explanation": "这里应该用〈夜里〉。日里指白天，赏月要在夜里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥日里了在医院上班。", "corrected_sentence": "我哥哥日里在医院上班。", "error_description": "错误：「日里了」，时间词「日里」后不能直接加动态助词「了」。正确说法是「我哥哥日里在医院上班」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家面馆日里的很热闹。", "corrected_sentence": "这家面馆日里很热闹。", "error_description": "错误：「日里的很热闹」，时间词「日里」后多出了结构助词「的」，「的」后面缺少中心语。正确说法是「这家面馆日里很热闹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
