INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86129, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“哪里”是用来问在什么地方的。", "primary_collocate": null, "pronunciation": "nǎ lǐ", "ipa": "na˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "你家在哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，洗手间在哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天去哪里了？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机放在哪里了？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们打算在哪里吃晚饭？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是在哪里买的？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在住在哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去哪里玩？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的图书馆在哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把钥匙放哪里了？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哪儿", "label": "口语变体"}, {"form": "哪裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "哪里：疑问代词，问在什么地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪里", "is_correct": true, "explanation": "正确答案。“你家在哪里”中，“哪里”询问处所，是唯一符合语境的选项。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“在”后要接处所，“谁”指人，“你家在谁”不能表示问住址。"}, {"text": "哪个", "is_correct": false, "explanation": "搭配：“哪个”单用时不指地点，需带名词（如“哪个小区”）才能指处所，句中缺少这一成分。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指代事物，不表示地点，不能用来回答“你家在哪”。"}], "explanations": {"哪里": "正确答案。“你家在哪里”中，“哪里”询问处所，是唯一符合语境的选项。", "谁": "语义：“在”后要接处所，“谁”指人，“你家在谁”不能表示问住址。", "哪个": "搭配：“哪个”单用时不指地点，需带名词（如“哪个小区”）才能指处所，句中缺少这一成分。", "这个": "语义：“这个”指代事物，不表示地点，不能用来回答“你家在哪”。"}, "sentence_index": 0, "correct_answer": "哪里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你的生日是哪里？", "explanation": "这里应该用〈哪天〉。“哪里”只问处所，问日期要用“哪天”，“生日是哪里”不通。"}, {"text": "你的电话号码是哪里？", "explanation": "这里应该用〈多少〉。“哪里”问处所，问号码要用“多少”，“电话号码是哪里”不通。"}, {"text": "你的体重是哪里？", "explanation": "这里应该用〈多少〉。“哪里”问处所，问体重要用“多少”，“体重是哪里”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪里", "is_correct": true, "explanation": "正确答案。“他现在住在哪里”询问居住的处所，是唯一符合语境的选项。"}, {"text": "哪位", "is_correct": false, "explanation": "语义：“哪位”指人，“住在哪位”是问与谁同住，不是问处所。"}, {"text": "那个", "is_correct": false, "explanation": "语义：“那个”指代事物，不指地点，“住在那个”无法回答住的地方。"}, {"text": "哪些", "is_correct": false, "explanation": "搭配：“哪些”表示多个，不能与单一的居住处所搭配，“住在哪些”不成立。"}], "explanations": {"哪里": "正确答案。“他现在住在哪里”询问居住的处所，是唯一符合语境的选项。", "哪位": "语义：“哪位”指人，“住在哪位”是问与谁同住，不是问处所。", "那个": "语义：“那个”指代事物，不指地点，“住在那个”无法回答住的地方。", "哪些": "搭配：“哪些”表示多个，不能与单一的居住处所搭配，“住在哪些”不成立。"}, "sentence_index": 6, "correct_answer": "哪里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哪里来帮忙？", "explanation": "这里应该用〈谁〉。“哪里”问处所，问人要用“谁”，不能用“哪里”问是哪个人来帮忙。"}, {"text": "今天是哪里号？", "explanation": "这里应该用〈几号〉。“哪里”只问处所，问日期要用“几号”，“哪里号”不是正常说法。"}, {"text": "这道题哪里做？", "explanation": "这里应该用〈怎么〉。“哪里”问处所，问做法要用“怎么”，“这道题哪里做”问的是地点，与释义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你哥哥在哪里了工作？", "corrected_sentence": "你哥哥在哪里工作？", "error_description": "“了”放错位置：“了”不能插在“哪里”与动词之间，应去掉。正确形式是“你哥哥在哪里工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
