INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86130, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问处所。", "primary_collocate": null, "pronunciation": "nǎ lǐ", "ipa": "na˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "你的朋友来自哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路通向哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在哪里工作？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李放在哪里了？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天在哪里见面？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是从哪里来的？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站在哪里？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在哪里学中文？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪里有卖水果的商店？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的车停在哪里了？", "target_word": "哪里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哪儿", "label": "口语变体"}, {"form": "哪裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "哪里：疑问代词，询问处所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪里", "is_correct": true, "explanation": "正确答案。“来自哪里”询问朋友的来处，是唯一符合语境的选项。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“来自”需要接地点或来源，“谁”指人，“来自谁”不能问朋友的来处。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：“什么”泛指事物，“来自什么”不指地点，不能用来问人的来处。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”指代事物，不指地点，“来自这个”无法回答问题。"}], "explanations": {"哪里": "正确答案。“来自哪里”询问朋友的来处，是唯一符合语境的选项。", "谁": "语义：“来自”需要接地点或来源，“谁”指人，“来自谁”不能问朋友的来处。", "什么": "搭配：“什么”泛指事物，“来自什么”不指地点，不能用来问人的来处。", "这个": "语义：“这个”指代事物，不指地点，“来自这个”无法回答问题。"}, "sentence_index": 0, "correct_answer": "哪里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生日是哪里？", "explanation": "这里应该用〈哪天〉。“哪里”问处所，问日期要用“哪天”，“生日是哪里”不通。"}, {"text": "她的身高是哪里？", "explanation": "这里应该用〈多高〉。“哪里”问处所，问身高要用“多高”，“身高是哪里”不通。"}, {"text": "你的得分是哪里？", "explanation": "这里应该用〈多少〉。“哪里”问处所，问得分要用“多少”，“得分是哪里”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪里", "is_correct": true, "explanation": "正确答案。“地铁站在哪里”询问地铁站的位置，是唯一符合语境的选项。"}, {"text": "哪位", "is_correct": false, "explanation": "语义：“哪位”指人，“地铁站在哪位”不能询问位置。"}, {"text": "那个", "is_correct": false, "explanation": "语义：“那个”指代事物，不表示地点，“地铁站在那个”无法回答位置问题。"}, {"text": "哪些", "is_correct": false, "explanation": "搭配：“哪些”表示多个，与单个地铁站的位置不搭配，句子不成立。"}], "explanations": {"哪里": "正确答案。“地铁站在哪里”询问地铁站的位置，是唯一符合语境的选项。", "哪位": "语义：“哪位”指人，“地铁站在哪位”不能询问位置。", "那个": "语义：“那个”指代事物，不表示地点，“地铁站在那个”无法回答位置问题。", "哪些": "搭配：“哪些”表示多个，与单个地铁站的位置不搭配，句子不成立。"}, "sentence_index": 6, "correct_answer": "哪里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哪里给你打电话？", "explanation": "这里应该用〈谁〉。“哪里”问处所，问打电话的人要用“谁”，不能说“哪里给你打电话”。"}, {"text": "这个月是哪里月？", "explanation": "这里应该用〈几月〉。“哪里”只问处所，问月份要用“几月”，“哪里月”不是正常说法。"}, {"text": "这个字哪里读？", "explanation": "这里应该用〈怎么〉。“哪里”问处所，问读法要用“怎么”，“这个字哪里读”问的是地点，与释义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在哪里了开会？", "corrected_sentence": "他们在哪里开会？", "error_description": "“了”放错位置：“了”不能插在“哪里”与动词之间，应去掉。正确形式是“他们在哪里开会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天在哪里了吃饭？", "corrected_sentence": "我们明天在哪里吃饭？", "error_description": "“了”放错位置：“了”不能插在“哪里”与动词之间，应去掉。正确形式是“我们明天在哪里吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
