INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86133, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "毕竟是说最后还是这样，不会变。", "primary_collocate": null, "pronunciation": "bì jìng", "ipa": "pi˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老房子再旧，毕竟是我长大的地方。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了很远，毕竟还是回到了家乡。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得再大，春天毕竟还是会来的。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间吵过架，毕竟还是朋友。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子再大，毕竟还是爸妈的孩子。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了很多工作，毕竟还是喜欢教书。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天再冷，毕竟会过去。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机再方便，毕竟代替不了面对面说话。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车再好，毕竟不如老车用着习惯。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再忙的人，毕竟也需要休息。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "畢竟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，强调事物的本质或结果最终不会改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕竟", "is_correct": true, "explanation": "“毕竟”表示最终如此、不会改变，“毕竟是我长大的地方”符合句意。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，与“再旧”引出的让步语气不合，句意说不通。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”一般修饰动作，不能修饰“是……的地方”这样的判断句。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示刚发生，与“是……的地方”这种长久的说明不合。"}], "explanations": {"毕竟": "“毕竟”表示最终如此、不会改变，“毕竟是我长大的地方”符合句意。", "马上": "语义：“马上”表示立即，与“再旧”引出的让步语气不合，句意说不通。", "偶尔": "搭配：“偶尔”一般修饰动作，不能修饰“是……的地方”这样的判断句。", "刚刚": "语义：“刚刚”表示刚发生，与“是……的地方”这种长久的说明不合。"}, "sentence_index": 0, "correct_answer": "毕竟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕毕竟咬了一口。", "explanation": "这里应该用〈只〉表示数量少。“毕竟”表示最终结论，不能用来说明动作的次数。"}, {"text": "你毕竟想去哪里？", "explanation": "这里应该用〈究竟〉表示追问。“毕竟”表示最终结果，不能用于疑问句。"}, {"text": "毕竟请坐！", "explanation": "这里应直接说“请坐”，不加“毕竟”。“毕竟”表示最终结论或理由，不能用于礼貌的请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕竟", "is_correct": true, "explanation": "“毕竟”表示最终会如此，“冬天再冷，毕竟会过去”符合句意。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“会过去”这种长期的变化不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去，与“会”表示的将来不合。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”一般修饰突然发生的动作，不修饰季节的变化过程。"}], "explanations": {"毕竟": "“毕竟”表示最终会如此，“冬天再冷，毕竟会过去”符合句意。", "立刻": "语义：“立刻”表示马上，与“会过去”这种长期的变化不合。", "曾经": "语义：“曾经”表示过去，与“会”表示的将来不合。", "忽然": "搭配：“忽然”一般修饰突然发生的动作，不修饰季节的变化过程。"}, "sentence_index": 6, "correct_answer": "毕竟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天毕竟下起了大雨。", "explanation": "这里应该用〈忽然〉表示突然发生。“毕竟”表示最终结论，不用于描述突发的事件。"}, {"text": "他毕竟在想什么？", "explanation": "这里应该用〈到底〉表示追问。“毕竟”不用于疑问句。"}, {"text": "毕竟请进！", "explanation": "这里应直接说“请进”，不加“毕竟”。“毕竟”表示最终结论，不能用于礼貌的请求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过这么多年，他毕竟还是毕竟回到了老家。", "corrected_sentence": "经过这么多年，他毕竟还是回到了老家。", "error_description": "“毕竟”多写了一次。“毕竟还是”中只用一个“毕竟”，多余的第二个“毕竟”应删去，应说“他毕竟还是回到了老家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场雨下了一整天，毕竟会了停的。", "corrected_sentence": "这场雨下了一整天，毕竟会停的。", "error_description": "在“会”后误加了“了”。“会”是助动词，后面直接接动词，应说“毕竟会停的”，不能说“会了停的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
