INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86134, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示追根究底，强调事实。", "primary_collocate": null, "pronunciation": "bì jìng", "ipa": "pi˥˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "别怪他，他毕竟才六岁。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕竟是新来的，还不太熟悉这里。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事毕竟不容易，你多给他一点时间。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕竟年纪大了，不能搬太重的东西。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕竟是第一次做饭，菜有点咸也正常。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们毕竟是一家人，有话慢慢说。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师毕竟不是万能的，也会有不懂的问题。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕竟路太远，我们还是坐飞机去吧。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕竟是医生，说的话你该听一听。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格毕竟不低，买以前要想清楚。", "target_word": "毕竟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "畢竟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，追根究底，强调某个事实是原因或理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d966616-493e-40f8-b90c-9c883ccf91ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕竟", "is_correct": true, "explanation": "“毕竟”表示理由，“别怪他，他毕竟才六岁”符合句意。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，不能用来说明年龄，“偶尔才六岁”说不通。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”一般与动作搭配，不用来修饰“才六岁”这样的状态。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“才六岁”的年龄状态不合，句意说不通。"}], "explanations": {"毕竟": "“毕竟”表示理由，“别怪他，他毕竟才六岁”符合句意。", "偶尔": "语义：“偶尔”表示不常发生，不能用来说明年龄，“偶尔才六岁”说不通。", "马上": "搭配：“马上”一般与动作搭配，不用来修饰“才六岁”这样的状态。", "立刻": "语义：“立刻”表示马上，与“才六岁”的年龄状态不合，句意说不通。"}, "sentence_index": 0, "correct_answer": "毕竟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毕竟请坐！", "explanation": "这里应直接说“请坐”，不加“毕竟”。“毕竟”用来说明理由，不能用于礼貌的请求。"}, {"text": "你毕竟为什么生气？", "explanation": "这里应该用〈究竟〉表示深究。“毕竟”表示理由或结论，不能用于追问。"}, {"text": "他毕竟每天早上跑步。", "explanation": "这里应该用〈都〉表示总是这样。“毕竟”用来说明理由，单独一句不能表示习惯或频率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕竟", "is_correct": true, "explanation": "“毕竟”表示理由，“老师毕竟不是万能的”符合句意。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“不是万能的”这种常态的判断不合。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”一般修饰突然发生的动作，不修饰“不是万能的”这种状态。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示不久前，与这种常态的判断不合。"}], "explanations": {"毕竟": "“毕竟”表示理由，“老师毕竟不是万能的”符合句意。", "立刻": "语义：“立刻”表示马上，与“不是万能的”这种常态的判断不合。", "忽然": "搭配：“忽然”一般修饰突然发生的动作，不修饰“不是万能的”这种状态。", "刚刚": "语义：“刚刚”表示不久前，与这种常态的判断不合。"}, "sentence_index": 6, "correct_answer": "毕竟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你毕竟在想什么？", "explanation": "这里应该用〈到底〉表示追问。“毕竟”表示理由或结论，不用于疑问句。"}, {"text": "这本书毕竟很厚，我五分钟就读完了。", "explanation": "这里应该用〈却〉表示转折。“毕竟”表示说明理由，不能引出与前文相反的结果。"}, {"text": "毕竟快点吃饭吧！", "explanation": "这里应该用〈赶快〉表示催促。“毕竟”表示最终结论或理由，不能用于命令句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他毕竟还毕竟小，你不要太着急。", "corrected_sentence": "他毕竟还小，你不要太着急。", "error_description": "“毕竟”多写了一次。“毕竟还小”中只用一个“毕竟”，多余的“毕竟”应删去，应说“他毕竟还小”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器毕竟的旧了，需要修理。", "corrected_sentence": "这台机器毕竟很旧了，需要修理。", "error_description": "“的”不能用在形容词前。“旧”前应用程度副词“很”，应说“这台机器毕竟很旧了”；“毕竟的旧了”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '007a532d-ff41-4cb0-8d10-b03b2bf9f83e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
