INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86135, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86135, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“或者”是说在几样东西里选一样。", "primary_collocate": null, "pronunciation": "huò zhě", "ipa": "xuo˥˩ ʈ͡ʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "我想喝茶或者咖啡。", "target_word": "或者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我去看电影或者逛街。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以坐地铁或者坐公共汽车去。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天或者后天，我都有时间。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用笔或者电脑写下你的名字。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早饭我吃面包或者米饭。", "target_word": "或者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你给我打电话或者发短信都可以。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们可以在家看书，或者去公园走走。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星期六或者星期天，我们去爬山吧。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买红色的或者蓝色的都行，我不挑。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接几个选项，表示从中选一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "或者", "is_correct": true, "explanation": "正确。「或者」（huò zhě）表示在几样东西里选一样。"}, {"text": "活着", "is_correct": false, "explanation": "活着（huó zhe）的第一个音节声调与或者不同（huó 与 huò），第二个音节是轻声，意思是“存活”。"}, {"text": "货主", "is_correct": false, "explanation": "货主（huò zhǔ）的第二个音节只有韵母不同（zhǔ 与 zhě），意思是货物的所有人。"}, {"text": "作者", "is_correct": false, "explanation": "作者（zuò zhě）只有第一个音节的声母不同（zuò 与 huò），第二个音节相同，意思是写文章或书的人。"}], "explanations": {"或者": "正确。「或者」（huò zhě）表示在几样东西里选一样。", "活着": "活着（huó zhe）的第一个音节声调与或者不同（huó 与 huò），第二个音节是轻声，意思是“存活”。", "货主": "货主（huò zhǔ）的第二个音节只有韵母不同（zhǔ 与 zhě），意思是货物的所有人。", "作者": "作者（zuò zhě）只有第一个音节的声母不同（zuò 与 huò），第二个音节相同，意思是写文章或书的人。"}, "sentence_index": null, "correct_answer": "或者"}, "level_3": {"options": [{"text": "或者", "is_correct": true, "explanation": "正确。「或者」表示在“茶”和“咖啡”之间选一样，符合“想喝”的句意。"}, {"text": "但是", "is_correct": false, "explanation": "语法：「但是」表示转折，要连接两个分句，“我想喝茶但是咖啡”不成句。"}, {"text": "因为", "is_correct": false, "explanation": "语法：「因为」表示原因，前后需是分句，“我想喝茶因为咖啡”不通。"}, {"text": "乃至", "is_correct": false, "explanation": "语义：「乃至」表示递进（甚至到），“我想喝茶乃至咖啡”语义不通，这里是在两者中选一。"}], "explanations": {"或者": "正确。「或者」表示在“茶”和“咖啡”之间选一样，符合“想喝”的句意。", "但是": "语法：「但是」表示转折，要连接两个分句，“我想喝茶但是咖啡”不成句。", "因为": "语法：「因为」表示原因，前后需是分句，“我想喝茶因为咖啡”不通。", "乃至": "语义：「乃至」表示递进（甚至到），“我想喝茶乃至咖啡”语义不通，这里是在两者中选一。"}, "sentence_index": 0, "correct_answer": "或者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我或者妹妹一起去买菜。", "explanation": "这里应该用〈和〉。「一起」表示两人共同行动，要用「和」连接两人；「或者」表示二选一，与“一起”矛盾。"}, {"text": "他很努力，或者很聪明，这两点他都做到了。", "explanation": "这里应该用〈而且〉。「这两点他都做到了」表示两方面同时成立，要用「而且」递进；「或者」表示二选一，与“都做到了”矛盾。"}, {"text": "他会游泳或者会跑步，两样都会。", "explanation": "这里应该用〈并且〉。「两样都会」表示两者同时具备，要用「并且」连接；「或者」表示二选一，与“都会”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "或者", "is_correct": true, "explanation": "正确。「或者」表示两种做法任选其一，与“都可以”的句意相符。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示先后顺序，“打电话然后发短信”说的是先后，不是任选其一。"}, {"text": "而后", "is_correct": false, "explanation": "语义：「而后」表示先后顺序，“打电话而后发短信”是两件事先后做，与“都可以”（任选其一）不符。"}, {"text": "而", "is_correct": false, "explanation": "语义：「而」不表示选择，“你给我打电话而发短信”不能表示任选其一。"}], "explanations": {"或者": "正确。「或者」表示两种做法任选其一，与“都可以”的句意相符。", "然后": "语义：「然后」表示先后顺序，“打电话然后发短信”说的是先后，不是任选其一。", "而后": "语义：「而后」表示先后顺序，“打电话而后发短信”是两件事先后做，与“都可以”（任选其一）不符。", "而": "语义：「而」不表示选择，“你给我打电话而发短信”不能表示任选其一。"}, "sentence_index": 6, "correct_answer": "或者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈关上门，或者走了出去。", "explanation": "这里应该用〈然后〉。句子说先后发生的两个动作，“走了出去”已经完成；「或者」表示选择，不能表示先后。"}, {"text": "他是老师或者学生，两个身份他都有。", "explanation": "这里应该用〈并且〉。「两个身份他都有」表示同时具备，「或者」表示二选一，前后矛盾。"}, {"text": "这次考试我考得很好，或者妈妈也很高兴。", "explanation": "这里应该用〈还〉。「妈妈也很高兴」是补充前面的情况，要用「还」或「也」；「或者」表示二选一，不能用来补充。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我晚上喝茶或者的牛奶。", "corrected_sentence": "我晚上喝茶或者牛奶。", "error_description": "「或者」后面不能直接加「的」，应说「我晚上喝茶或者牛奶」，「或者」连接两个并列名词，中间不加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你坐车或者走路去学校？", "corrected_sentence": "你坐车还是走路去学校？", "error_description": "疑问句里表示选择要用「还是」，不能用「或者」，应说「你坐车还是走路去学校？」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86136, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
