INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86136, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示选择关系，也表示不确定。", "primary_collocate": null, "pronunciation": "huò zhě", "ipa": "xuo˥˩ ʈ͡ʂɤ˨˩", "syllable_count": 2, "sentences": [{"text": "他没回信，或者是太忙，或者是忘了。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事或者你对，或者我对，没人知道。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她今天没来，或者生病了。", "target_word": "或者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "或者明年，或者后年，他会回国。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想他或者是在路上，或者已经到了。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个声音或者是风，或者是有人在敲门。", "target_word": "或者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这个周末或者下个周末去看你，还没定。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他现在或者在图书馆，或者在宿舍。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑了，或者是因为听到了好消息。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书或者是他的，或者是他朋友的。", "target_word": "或者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "列出几种可能，表示不确定是哪一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60f41c19-c9f1-4287-85b2-aea15cba001d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "或者", "is_correct": true, "explanation": "正确。「或者」（huò zhě）表示列出几种可能，不确定是哪一种。"}, {"text": "活着", "is_correct": false, "explanation": "活着（huó zhe）的第一个音节声调与或者不同（huó 与 huò），第二个音节是轻声，意思是“存活”。"}, {"text": "货主", "is_correct": false, "explanation": "货主（huò zhǔ）的第二个音节只有韵母不同（zhǔ 与 zhě），意思是货物的所有人。"}, {"text": "作者", "is_correct": false, "explanation": "作者（zuò zhě）只有第一个音节的声母不同（zuò 与 huò），第二个音节相同，意思是写文章或书的人。"}], "explanations": {"或者": "正确。「或者」（huò zhě）表示列出几种可能，不确定是哪一种。", "活着": "活着（huó zhe）的第一个音节声调与或者不同（huó 与 huò），第二个音节是轻声，意思是“存活”。", "货主": "货主（huò zhǔ）的第二个音节只有韵母不同（zhǔ 与 zhě），意思是货物的所有人。", "作者": "作者（zuò zhě）只有第一个音节的声母不同（zuò 与 huò），第二个音节相同，意思是写文章或书的人。"}, "sentence_index": null, "correct_answer": "或者"}, "level_3": {"options": [{"text": "或者", "is_correct": true, "explanation": "正确。「或者」列出“太忙”“忘了”等可能，表示不确定是哪一种。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：「而是」通常与前面的「不是」呼应，这里没有「不是」，“没回信，而是太忙”搭配不通。"}, {"text": "否则", "is_correct": false, "explanation": "语义：「否则」表示“要不然”，引出相反的后果，这里是在列举没回信的可能原因。"}, {"text": "且", "is_correct": false, "explanation": "语域：「且」是文言色彩较浓的书面词，口语里不说“他没回信，且是太忙”。"}], "explanations": {"或者": "正确。「或者」列出“太忙”“忘了”等可能，表示不确定是哪一种。", "而是": "搭配：「而是」通常与前面的「不是」呼应，这里没有「不是」，“没回信，而是太忙”搭配不通。", "否则": "语义：「否则」表示“要不然”，引出相反的后果，这里是在列举没回信的可能原因。", "且": "语域：「且」是文言色彩较浓的书面词，口语里不说“他没回信，且是太忙”。"}, "sentence_index": 0, "correct_answer": "或者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他或者明年回国，机票已经买好了。", "explanation": "这里应该用〈一定〉。「机票已经买好了」说明回国已经确定，「或者」表示不确定，前后矛盾。"}, {"text": "我的钥匙已经找到了，或者在抽屉里。", "explanation": "这里应该用〈就〉。「已经找到了」说明位置已确定，「或者」表示不确定，前后矛盾。"}, {"text": "我们明年结婚，或者后年结婚，都已经定好了。", "explanation": "这里应该用〈一定〉。「都已经定好了」表示已经确定，「或者」表示不确定，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "或者", "is_correct": true, "explanation": "正确。「或者」表示在两个时间中任选一个，符合句意。"}, {"text": "也就是", "is_correct": false, "explanation": "语义：「也就是」表示换一种说法指同一件事，而“这个周末”和“下个周末”是两个不同的时间。"}, {"text": "乃至", "is_correct": false, "explanation": "语义：「乃至」表示递进（甚至），这句只是在说去看你的时间，不是递进。"}, {"text": "以及", "is_correct": false, "explanation": "语义：「以及」表示两者都包括，“这个周末以及下个周末去看你”是两次都去，与“还没定”（只选一个）矛盾。"}], "explanations": {"或者": "正确。「或者」表示在两个时间中任选一个，符合句意。", "也就是": "语义：「也就是」表示换一种说法指同一件事，而“这个周末”和“下个周末”是两个不同的时间。", "乃至": "语义：「乃至」表示递进（甚至），这句只是在说去看你的时间，不是递进。", "以及": "语义：「以及」表示两者都包括，“这个周末以及下个周末去看你”是两次都去，与“还没定”（只选一个）矛盾。"}, "sentence_index": 6, "correct_answer": "或者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈先做饭，或者洗了碗，两件事她都做完了。", "explanation": "这里应该用〈然后〉。句子说先后完成的两件事，「或者」表示不确定，与“都做完了”矛盾，不能表示先后。"}, {"text": "这个方法或者省钱，我昨天算过了，确实省了一半。", "explanation": "这里应该用〈一定〉。「确实省了一半」是已经确定的事实，「或者」表示不确定，前后矛盾。"}, {"text": "他很会画画，或者很会弹琴，两样都会。", "explanation": "这里应该用〈并且〉。「两样都会」表示两者同时具备，要用「并且」；「或者」表示不确定或二选一，与“都会”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他或者在家，在学校。", "corrected_sentence": "他或者在家，或者在学校。", "error_description": "「或者」要成对出现，第二个「或者」不能省略，应说「他或者在家，或者在学校」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支笔或者我的，或者是你的。", "corrected_sentence": "这支笔或者是我的，或者是你的。", "error_description": "「或者是」要连用，「是」不能省略，应说「这支笔或者是我的，或者是你的」，不能说「这支笔或者我的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd06ce0-dcd9-4874-b52d-e666db9f14a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
