INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或集团之间用武力进行的斗争。", "primary_collocate": null, "pronunciation": "zhàn zhēng", "ipa": "ʈʂan˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "两国之间的战争持续了三年。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场战争对经济影响很大。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写着这次战争的原因。", "target_word": "战争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争给两个国家带来了很大的损失。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用谈判代替战争。", "target_word": "战争", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场战争结束以后，两国签了和平协议。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争会破坏一个国家的发展。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国希望各国停止战争。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家为了资源发动战争。", "target_word": "战争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写过一本关于战争的书。", "target_word": "战争", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场战争", "label": "量词"}, {"form": "戰爭", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家或集团之间的武力冲突，常谈原因、影响和结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战争", "is_correct": true, "explanation": "正确：“两国之间的战争”指两国之间的武力冲突，持续三年符合语境。"}, {"text": "晚餐", "is_correct": false, "explanation": "配价：“晚餐”是一次性的具体事件，不能作“持续了三年”的主语。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是个人的疾病，与两国之间的关系不符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”不是两国之间的武力冲突，句意不通。"}], "explanations": {"战争": "正确：“两国之间的战争”指两国之间的武力冲突，持续三年符合语境。", "晚餐": "配价：“晚餐”是一次性的具体事件，不能作“持续了三年”的主语。", "感冒": "语义：“感冒”是个人的疾病，与两国之间的关系不符。", "电影": "语义：“电影”不是两国之间的武力冲突，句意不通。"}, "sentence_index": 0, "correct_answer": "战争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国之间打了一艘战争，持续了三年。", "explanation": "这里应该用〈场〉。“艘”用于船只，不能用来数“战争”，应说“一场战争”。"}, {"text": "两国之间爆发了一本战争，损失很大。", "explanation": "这里应该用〈场〉。“本”用于书、杂志等，不能用来数“战争”，应说“一场战争”。"}, {"text": "两国之间打了一个战争。", "explanation": "这里应该用〈场〉。“战争”的量词是“场”，不说“一个战争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战争", "is_correct": true, "explanation": "正确：“战争会破坏一个国家的发展”符合常识，句意通顺。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会破坏一个国家的发展，句意不通。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声不会破坏国家发展，与句意不符。"}, {"text": "花朵", "is_correct": false, "explanation": "配价：“花朵”不能作“破坏”的施事，搭配不当。"}], "explanations": {"战争": "正确：“战争会破坏一个国家的发展”符合常识，句意通顺。", "歌曲": "语义：歌曲不会破坏一个国家的发展，句意不通。", "笑声": "语义：笑声不会破坏国家发展，与句意不符。", "花朵": "配价：“花朵”不能作“破坏”的施事，搭配不当。"}, "sentence_index": 6, "correct_answer": "战争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国之间打了一条战争，边境很紧张。", "explanation": "这里应该用〈场〉。“条”用于细长的东西，不能用来数“战争”，应说“一场战争”。"}, {"text": "他们之间打了一顿战争，持续了三年。", "explanation": "这里应该用〈场〉。“顿”用于吃饭、挨打，不能用来数“战争”，应说“一场战争”。"}, {"text": "两国之间进行了一把战争，持续了三年。", "explanation": "这里应该用〈场〉。“把”用于有柄的器具，不能用来数“战争”，应说“一场战争”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多国家都希望避免一个战争。", "corrected_sentence": "很多国家都希望避免战争。", "error_description": "错误在于“战争”前多加了“一个”；“避免战争”的“战争”不带数量词，应为“很多国家都希望避免战争”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国之间的那战争结束了。", "corrected_sentence": "两国之间的那场战争结束了。", "error_description": "“那”后面的“战争”缺少量词“场”，应为“那场战争”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
