INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86143, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“每”是说一个一个都这样，一个也不少。", "primary_collocate": null, "pronunciation": "měi", "ipa": "mei˨˩˦", "syllable_count": 1, "sentences": [{"text": "每个学生都来了，一个也没少。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有一本书。", "target_word": "每", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们班每个人都喜欢这位老师。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上每个杯子都是满的。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师看了每个孩子的作业。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每家商店都关门了，我什么也没买到。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几本书每本我都看过。", "target_word": "每", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给每个孩子都做了一件新衣服。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每位客人都拿到了一份小礼物。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把每个字都写得很清楚。", "target_word": "每", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "每天", "label": "复合词"}, {"form": "每年", "label": "复合词"}], "register": "中性", "sense_fingerprint": "每：逐一都是这样，无一例外（每个人都……）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86143, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi（第三声）表示全体中的每一个。"}, {"text": "妹", "is_correct": false, "explanation": "妹 mèi（第四声）与 měi 声调不同，意思是妹妹。"}, {"text": "没", "is_correct": false, "explanation": "没 méi（第二声）与 měi 声调不同，意思是没有。"}, {"text": "北", "is_correct": false, "explanation": "北 běi 与 měi 声母不同（b 与 m），意思是北方。"}], "explanations": {"每": "正确：每 měi（第三声）表示全体中的每一个。", "妹": "妹 mèi（第四声）与 měi 声调不同，意思是妹妹。", "没": "没 méi（第二声）与 měi 声调不同，意思是没有。", "北": "北 běi 与 měi 声母不同（b 与 m），意思是北方。"}, "sentence_index": null, "correct_answer": "每"}, "level_3": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi 表示逐一都这样，与“一个也没少”相符。"}, {"text": "这", "is_correct": false, "explanation": "语义：“这个学生都来了”只指一个人，与“一个也没少”所说的全体不符。"}, {"text": "那", "is_correct": false, "explanation": "语义：“那个学生都来了”只指一个人，与“一个也没少”所说的全体不符。"}, {"text": "某", "is_correct": false, "explanation": "搭配：“某个……都”不能表示全体，与“一个也没少”冲突。"}], "explanations": {"每": "正确：每 měi 表示逐一都这样，与“一个也没少”相符。", "这": "语义：“这个学生都来了”只指一个人，与“一个也没少”所说的全体不符。", "那": "语义：“那个学生都来了”只指一个人，与“一个也没少”所说的全体不符。", "某": "搭配：“某个……都”不能表示全体，与“一个也没少”冲突。"}, "sentence_index": 0, "correct_answer": "每"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个学生们都去了公园。", "explanation": "这里应该去掉〈们〉。“每个”已表示逐一，不能再加复数标记“们”。"}, {"text": "每李老师都来了，大家很高兴。", "explanation": "这里不能用“每”。“每”表示一类事物中逐一的每一个，不能直接修饰专有人名。"}, {"text": "这个班每有三个学生，都很活泼。", "explanation": "这里应该用〈只〉。“每”表示逐一，不能表示总数只有三个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86143, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi（第三声）表示全体中的每一个。"}, {"text": "眉", "is_correct": false, "explanation": "眉 méi（第二声）与 měi 声调不同，意思是眉毛。"}, {"text": "煤", "is_correct": false, "explanation": "煤 méi（第二声）与 měi 声调不同，意思是煤炭。"}, {"text": "梅", "is_correct": false, "explanation": "梅 méi（第二声）与 měi 声调不同，意思是梅花。"}], "explanations": {"每": "正确：每 měi（第三声）表示全体中的每一个。", "眉": "眉 méi（第二声）与 měi 声调不同，意思是眉毛。", "煤": "煤 méi（第二声）与 měi 声调不同，意思是煤炭。", "梅": "梅 méi（第二声）与 měi 声调不同，意思是梅花。"}, "sentence_index": null, "correct_answer": "每"}, "level_3": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi 表示逐一，“每本……都看过”与句意相符。"}, {"text": "其", "is_correct": false, "explanation": "语域：“其”是书面用词，口语中不能放在“几本书”之后修饰量词“本”，此处不自然。"}, {"text": "此", "is_correct": false, "explanation": "搭配：“此”与前面的“这几本书”指称重复，两者不能同时限定同一名词。"}, {"text": "该", "is_correct": false, "explanation": "语义：“该”指前文提到的那一个，与句中按每一本逐一说明的意思不符。"}], "explanations": {"每": "正确：每 měi 表示逐一，“每本……都看过”与句意相符。", "其": "语域：“其”是书面用词，口语中不能放在“几本书”之后修饰量词“本”，此处不自然。", "此": "搭配：“此”与前面的“这几本书”指称重复，两者不能同时限定同一名词。", "该": "语义：“该”指前文提到的那一个，与句中按每一本逐一说明的意思不符。"}, "sentence_index": 6, "correct_answer": "每"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把每的字都写得很清楚。", "explanation": "这里应该用〈个〉。“每”后要接量词，“每的字”不成立，应为“每个字”。"}, {"text": "每有人在门口等你，你快去看看。", "explanation": "这里不能用“每”。“每”表示全体中逐一的每一个，不能表示不确定的一部分人。"}, {"text": "每我都觉得很累，大家也都累了。", "explanation": "这里不能用“每”。“每”表示全体中逐一的每一个，不能修饰单独的人称代词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个老师们都要交一份计划。", "corrected_sentence": "每个老师都要交一份计划。", "error_description": "“每个”已经表示一个一个都这样，后面的名词不能再加“们”。正确：每个老师都要交一份计划。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班每同学都会得到一本笔记。", "corrected_sentence": "我们班每位同学都会得到一本笔记。", "error_description": "“每”后面一般要先接量词再接名词，“每同学”不成立，应说“每位同学”或“每个同学”。正确：我们班每位同学都会得到一本笔记。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
