INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86144, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“每”表示每一次，或每隔一段时间、每遇到某种情况就发生一次。", "primary_collocate": null, "pronunciation": "měi", "ipa": "mei˨˩˦", "syllable_count": 1, "sentences": [{"text": "每次下雨，我都坐地铁上班。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每三天给妈妈打一次电话。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共汽车每十分钟来一辆。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次考试前，他都很紧张。", "target_word": "每", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每次去那家饭馆，都点同一个菜。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每走一步，他都停下来看看。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每到秋天，这里的树叶都变黄。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每两周开一次会。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店每买两杯，就送一杯。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每说一句话，大家都会笑。", "target_word": "每", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "每次", "label": "复合词"}, {"form": "每天", "label": "复合词"}], "register": "中性", "sense_fingerprint": "每：每一次（每次、每隔多久、每到某时）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi（第三声）表示全体中的任何一个或每一次。"}, {"text": "妹", "is_correct": false, "explanation": "妹 mèi（第四声）与 měi 声调不同，意思是妹妹。"}, {"text": "眉", "is_correct": false, "explanation": "眉 méi（第二声）与 měi 声调不同，意思是眉毛。"}, {"text": "北", "is_correct": false, "explanation": "北 běi 与 měi 声母不同（b 与 m），意思是北方。"}], "explanations": {"每": "正确：每 měi（第三声）表示全体中的任何一个或每一次。", "妹": "妹 mèi（第四声）与 měi 声调不同，意思是妹妹。", "眉": "眉 méi（第二声）与 měi 声调不同，意思是眉毛。", "北": "北 běi 与 měi 声母不同（b 与 m），意思是北方。"}, "sentence_index": null, "correct_answer": "每"}, "level_3": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi 表示每一次，与“都坐地铁上班”的习惯相符。"}, {"text": "这", "is_correct": false, "explanation": "语义：“这次下雨”指一次具体的事件，与“都”表示每次的习惯相冲突。"}, {"text": "那", "is_correct": false, "explanation": "语义：“那次”指过去的某一次，与“我都坐地铁上班”表示的习惯冲突。"}, {"text": "某", "is_correct": false, "explanation": "搭配：“某次”指不确定的一次，不能与表示每次习惯的“都”搭配。"}], "explanations": {"每": "正确：每 měi 表示每一次，与“都坐地铁上班”的习惯相符。", "这": "语义：“这次下雨”指一次具体的事件，与“都”表示每次的习惯相冲突。", "那": "语义：“那次”指过去的某一次，与“我都坐地铁上班”表示的习惯冲突。", "某": "搭配：“某次”指不确定的一次，不能与表示每次习惯的“都”搭配。"}, "sentence_index": 0, "correct_answer": "每"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每次吃三顿饭。", "explanation": "这里应该用〈每天〉。“每次”指每一次行为，吃三顿饭是按天计算的，要用“每天”。"}, {"text": "每次的我们都很开心。", "explanation": "这里不能用“每次”修饰人称代词“我们”，“每次的我们”不成立。"}, {"text": "每次到周末的，我都去图书馆。", "explanation": "这里应该用〈每到〉。“每次”后不能接“到周末的”这样的结构；周期性到来的时段应说“每到周末”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86144, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi（第三声）表示全体中的任何一个或每一次。"}, {"text": "没", "is_correct": false, "explanation": "没 méi（第二声）与 měi 声调不同，意思是没有。"}, {"text": "煤", "is_correct": false, "explanation": "煤 méi（第二声）与 měi 声调不同，意思是煤炭。"}, {"text": "梅", "is_correct": false, "explanation": "梅 méi（第二声）与 měi 声调不同，意思是梅花。"}], "explanations": {"每": "正确：每 měi（第三声）表示全体中的任何一个或每一次。", "没": "没 méi（第二声）与 měi 声调不同，意思是没有。", "煤": "煤 méi（第二声）与 měi 声调不同，意思是煤炭。", "梅": "梅 méi（第二声）与 měi 声调不同，意思是梅花。"}, "sentence_index": null, "correct_answer": "每"}, "level_3": {"options": [{"text": "每", "is_correct": true, "explanation": "正确：每 měi 表示每到一次，与“到秋天，树叶都变黄”的说法相符。"}, {"text": "其", "is_correct": false, "explanation": "语域：“其”是书面用词，不能与“到”组成时间短语，口语中不这样说。"}, {"text": "此", "is_correct": false, "explanation": "搭配：“此到秋天”不成词组，“此”不能与表示时间的“到秋天”搭配，无法表示周期。"}, {"text": "该", "is_correct": false, "explanation": "语义：“该”指前文所说的那一个，与“每到秋天”表示反复出现的周期意思不符。"}], "explanations": {"每": "正确：每 měi 表示每到一次，与“到秋天，树叶都变黄”的说法相符。", "其": "语域：“其”是书面用词，不能与“到”组成时间短语，口语中不这样说。", "此": "搭配：“此到秋天”不成词组，“此”不能与表示时间的“到秋天”搭配，无法表示周期。", "该": "语义：“该”指前文所说的那一个，与“每到秋天”表示反复出现的周期意思不符。"}, "sentence_index": 6, "correct_answer": "每"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药每次两小时吃一次。", "explanation": "这里应该用〈每隔〉。“每次”表示每一次，不能与“两小时”这种间隔时间搭配。"}, {"text": "每次书都很厚。", "explanation": "这里应该用〈每本〉。“每次”指一次一次的行为或时间，不能修饰“书”这类事物。"}, {"text": "这每次的旅行很愉快。", "explanation": "这里应该用〈这次〉。“每次”表示每一次，前面不能直接加“这”来指某一次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每次三天去一次健身房。", "corrected_sentence": "我每三天去一次健身房。", "error_description": "词语混用：表示间隔时间应说“每三天”，不能说“每次三天”。正确：我每三天去一次健身房。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每次到冬天，这里都会下雪。", "corrected_sentence": "每到冬天，这里都会下雪。", "error_description": "词语混用：说某个季节或时候周期性到来，用“每到……”，不说“每次到……”。正确：每到冬天，这里都会下雪。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
