INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86145, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说法是讲一件事的话。", "primary_collocate": null, "pronunciation": "shuō fa", "ipa": "ʂuɔ˥ fa", "syllable_count": 2, "sentences": [{"text": "这个说法我从来没听过。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这件事，大家有不同的说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的说法让我很吃惊。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上有一种说法，喝水能减肥。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶有个说法：饭前要洗手。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个说法听起来有道理。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的说法完全不一样。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太相信这种说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁先到的？你们各有各的说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次听到这种说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们对一件事所讲的话或流传的讲法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说法", "is_correct": true, "explanation": "正确：“这个说法”指刚听到的这种讲法，与“从来没听过”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“听过”接的是可以听到的话语或消息，味道要用“尝”或“闻”，不能说“没听过味道”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不是可以听到的内容，与“听过”冲突。"}, {"text": "形状", "is_correct": false, "explanation": "体貌：形状属于外观特征，无法被“听”到，与“从来没听过”冲突。"}], "explanations": {"说法": "正确：“这个说法”指刚听到的这种讲法，与“从来没听过”搭配。", "味道": "搭配：“听过”接的是可以听到的话语或消息，味道要用“尝”或“闻”，不能说“没听过味道”。", "颜色": "语义：颜色是视觉属性，不是可以听到的内容，与“听过”冲突。", "形状": "体貌：形状属于外观特征，无法被“听”到，与“从来没听过”冲突。"}, "sentence_index": 0, "correct_answer": "说法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想到一个说法，很快解决了那个难题。", "explanation": "这里应该用〈办法〉。说法指讲一件事的话，不指解决问题的办法，应说“办法”。"}, {"text": "我有一个说法，我们周末去爬山吧。", "explanation": "这里应该用〈想法〉。说法指讲出来的话，不指打算或主意。"}, {"text": "我找到了一个说法，这道题就解出来了。", "explanation": "这里应该用〈方法〉。说法指讲一件事的话，不指解题的方法，应说“方法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说法", "is_correct": true, "explanation": "正确：“两个人的说法”指两人各自讲的话，与“完全不一样”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指一地的气象状况，不属于某个人，“两个人的天气”不成立。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“两个人的”后面接人或人所拥有的事物，季节不能这样说。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是环境的数值，不能属于两个人，句意不通。"}], "explanations": {"说法": "正确：“两个人的说法”指两人各自讲的话，与“完全不一样”搭配。", "天气": "语义：天气指一地的气象状况，不属于某个人，“两个人的天气”不成立。", "季节": "搭配：“两个人的”后面接人或人所拥有的事物，季节不能这样说。", "气温": "语义：气温是环境的数值，不能属于两个人，句意不通。"}, "sentence_index": 6, "correct_answer": "说法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用说法炒了一盘菜。", "explanation": "这里应该用〈锅〉。炒菜要用锅，“说法”指讲出来的话，不能用来烹饪。"}, {"text": "他戴着说法去游泳。", "explanation": "这里应该用〈泳镜〉。“说法”指讲出来的话，不是可以戴的物件。"}, {"text": "他用说法画了一幅画。", "explanation": "这里应该用〈颜料〉。说法指讲出来的话，不能用来画画，画画要用“颜料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的那只说法我还是不太相信。", "corrected_sentence": "他的那个说法我还是不太相信。", "error_description": "量词错误：“说法”的量词应为“个”或“种”，“只”只用于动物等，应说“那个说法”，不说“那只说法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他讲了两说法，我都听过。", "corrected_sentence": "他讲了两个说法，我都听过。", "error_description": "量词缺失：数词“两”与“说法”之间要加量词，应说“两个说法”，不说“两说法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
