INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关于某事的说明、意见；也指措辞。", "primary_collocate": null, "pronunciation": "shuō fa", "ipa": "ʂuɔ˥ fa", "syllable_count": 2, "sentences": [{"text": "学校应该给家长一个说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的说法我不同意。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换个说法，这样听起来更好。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这个问题，老师有自己的说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事公司还没有说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的说法是，那天路上堵车了。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个说法意思差不多。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人要一个说法，经理来道歉了。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这个说法太客气了。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听听医生的说法。", "target_word": "说法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "对某事的说明、意见或交代，也指措辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说法", "is_correct": true, "explanation": "正确：“一个说法”指学校向家长作出的交代，与语境相合。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“给”接的是可以交付的东西，考试不能这样“给”家长。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是交代或说明，句意不通。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是场地，不属于可以交给家长的说明或答复。"}], "explanations": {"说法": "正确：“一个说法”指学校向家长作出的交代，与语境相合。", "考试": "搭配：“给”接的是可以交付的东西，考试不能这样“给”家长。", "颜色": "语义：颜色不是交代或说明，句意不通。", "操场": "语义：操场是场地，不属于可以交给家长的说明或答复。"}, "sentence_index": 0, "correct_answer": "说法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想出了一个好说法，很快修好了电脑。", "explanation": "这里应该用〈办法〉。“说法”指说明、意见或措辞，不指解决问题的办法。"}, {"text": "他用这种说法解出了题目。", "explanation": "这里应该用〈方法〉。说法指说明或措辞，不能用来解题，解题要用“方法”。"}, {"text": "这个软件是很好的说法，能帮我们省时间。", "explanation": "这里应该用〈工具〉。说法不指用来做事的工具，形容软件应说“工具”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "说法", "is_correct": true, "explanation": "正确：“这两个说法”指两种讲法，与“意思差不多”搭配。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯是器具，句意不通；“意思差不多”指话语或看法相近，不能用于茶杯。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是话语，不能说“意思差不多”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“意思”要配话语、词句，价格不能说“意思差不多”。"}], "explanations": {"说法": "正确：“这两个说法”指两种讲法，与“意思差不多”搭配。", "茶杯": "语义：茶杯是器具，句意不通；“意思差不多”指话语或看法相近，不能用于茶杯。", "房间": "语义：房间不是话语，不能说“意思差不多”。", "价格": "搭配：“意思”要配话语、词句，价格不能说“意思差不多”。"}, "sentence_index": 6, "correct_answer": "说法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个说法能打开这扇门。", "explanation": "这里应该用〈钥匙〉。说法指讲出来的话，不指开门的物件，开门要用“钥匙”。"}, {"text": "这个说法擦得很干净。", "explanation": "这里应该用〈橡皮〉。说法不指擦东西的物件，擦干净要用“橡皮”。"}, {"text": "他骑着一个说法去上班。", "explanation": "这里应该用〈自行车〉。说法不指交通工具，骑着去上班要用“自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不同意他的这把说法。", "corrected_sentence": "我不同意他的这个说法。", "error_description": "量词错误：“说法”不能用“把”计量（“把”用于有柄的物件），应说“这个说法”，不说“这把说法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给了我一说法。", "corrected_sentence": "他给了我一个说法。", "error_description": "量词缺失：数词“一”与“说法”之间要加量词，应说“一个说法”，不说“一说法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
