INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86149, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“比较”是说和别的东西比起来，多一点或少一点。", "primary_collocate": null, "pronunciation": "bǐ jiào", "ipa": "pi˨˩ tɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "今天比较冷，你多穿点。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆比较小，但是菜很好吃。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我比较喜欢喝茶，不太喜欢咖啡。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他个子比较高，打篮球很有优势。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题比较难，我想了很久。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末地铁上的人比较少。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话比较慢，我听得很清楚。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间比较安静，适合看书。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家离学校比较近，走路十分钟。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年比较忙，很少回家。", "target_word": "比较", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "比較", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，表示相对而言有一定程度（可高可低），放在形容词或心理动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "比较", "is_correct": true, "explanation": "正确：“比较”作副词，表示程度稍高，放在形容词前。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同，不能表示“冷”的程度。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”要用于否定或经历，不能修饰“冷”。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”指两件事同时发生，句意不通。"}], "explanations": {"比较": "正确：“比较”作副词，表示程度稍高，放在形容词前。", "一起": "语义：“一起”表示共同，不能表示“冷”的程度。", "从来": "搭配：“从来”要用于否定或经历，不能修饰“冷”。", "同时": "语义：“同时”指两件事同时发生，句意不通。"}, "sentence_index": 0, "correct_answer": "比较"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是比较唯一的办法，大家都同意。", "explanation": "这里不能用〈比较〉。“唯一”表示只有一个，本身不能表示程度稍高，应直接说“唯一的办法”。"}, {"text": "这次考试他比较是第一名。", "explanation": "这里不能用〈比较〉。“第一名”是固定的名次，不能表示程度稍高，应直接说“是第一名”。"}, {"text": "这两个数字比较相等。", "explanation": "这里不能用〈比较〉。“相等”表示完全一样，不表示程度，应直接说“相等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "比较", "is_correct": true, "explanation": "正确：“比较”作副词，表示相对而言有一定程度，放在形容词“慢”前。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指很快发生，不能用来表示“慢”的程度。"}, {"text": "一共", "is_correct": false, "explanation": "语义：“一共”表示总计，不能修饰“慢”。"}, {"text": "曾经", "is_correct": false, "explanation": "搭配：“曾经”表示过去的经历，不能修饰现在的说话速度。"}], "explanations": {"比较": "正确：“比较”作副词，表示相对而言有一定程度，放在形容词“慢”前。", "马上": "语义：“马上”指很快发生，不能用来表示“慢”的程度。", "一共": "语义：“一共”表示总计，不能修饰“慢”。", "曾经": "搭配：“曾经”表示过去的经历，不能修饰现在的说话速度。"}, "sentence_index": 6, "correct_answer": "比较"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比较第一个到了终点，大家都很惊讶。", "explanation": "这里不能用〈比较〉。“第一个”表示次序，不表示程度稍高，应直接说“第一个到了终点”。"}, {"text": "这张桌子比较木头做的，很结实。", "explanation": "这里不能用〈比较〉。“木头做的”说明材料，不表示程度稍高，应直接说“木头做的”。"}, {"text": "这个方案比较全部通过了，没有任何漏洞。", "explanation": "这里不能用〈比较〉。“全部”表示整体范围，不表示程度稍高，应直接说“全部通过了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子很比较舒服，你坐一下。", "corrected_sentence": "这把椅子比较舒服，你坐一下。", "error_description": "程度词重复：“比较”本身已表示程度稍高，前面不能再加“很”，应写作“这把椅子比较舒服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这个月比较得忙，没有时间休息。", "corrected_sentence": "我这个月比较忙，没有时间休息。", "error_description": "结构助词错误：“比较”是副词，后面直接接形容词，不能加结构助词“得”，应写作“这个月比较忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "与“违法”是反义关系，指符合法律规定。"}, {"text": "友善", "is_correct": false, "explanation": "与“违法”没有反义关系，指态度亲切、和气。"}, {"text": "干净", "is_correct": false, "explanation": "与“违法”没有反义关系，指没有污垢。"}, {"text": "直接", "is_correct": false, "explanation": "与“违法”没有反义关系，指不绕弯子。"}], "correct_answer": "合法", "explanations": {"合法": "与“违法”是反义关系，指符合法律规定。", "友善": "与“违法”没有反义关系，指态度亲切、和气。", "干净": "与“违法”没有反义关系，指没有污垢。", "直接": "与“违法”没有反义关系，指不绕弯子。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "与“违法”是反义关系，指符合法律规定。"}, {"text": "柔软", "is_correct": false, "explanation": "与“违法”没有反义关系，指质地不硬。"}, {"text": "湿润", "is_correct": false, "explanation": "与“违法”没有反义关系，指略带水分。"}, {"text": "饱满", "is_correct": false, "explanation": "与“违法”没有反义关系，指充实、不干瘪。"}], "correct_answer": "合法", "explanations": {"合法": "与“违法”是反义关系，指符合法律规定。", "柔软": "与“违法”没有反义关系，指质地不硬。", "湿润": "与“违法”没有反义关系，指略带水分。", "饱满": "与“违法”没有反义关系，指充实、不干瘪。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "违法是做了法律不让做的事。", "primary_collocate": null, "pronunciation": "wéi fǎ", "ipa": "wei˧˥ fa˨˩", "syllable_count": 2, "sentences": [{"text": "警察把违法的人带走了。", "target_word": "违法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偷东西是违法的事。", "target_word": "违法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他以前做过违法的事，现在很后悔。", "target_word": "违法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不让孩子上学是违法的。", "target_word": "违法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你这样做违法，最好马上停下来。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他知道自己在违法，可是还想试一试。", "target_word": "违法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在河里用电打鱼是违法的。", "target_word": "违法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板不给工人钱，这是违法行为。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别做违法的事，不然你会有大麻烦。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他卖假药，做了很多违法的生意。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "违了法", "label": "体标"}, {"form": "违过法", "label": "体标"}], "register": "通用", "sense_fingerprint": "做了法律不允许做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adca781d-1525-4feb-b95c-ac2c37686162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违法", "is_correct": true, "explanation": "“违法的人”指做了违法事情的人，与“警察把……带走了”相合。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容品性好，与“警察带走”的情形不符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容智力好，不能说明被警察带走的原因。"}, {"text": "整洁", "is_correct": false, "explanation": "搭配：“整洁”形容外表干净，不用来说明被带走的人。"}], "explanations": {"违法": "“违法的人”指做了违法事情的人，与“警察把……带走了”相合。", "善良": "语义：“善良”形容品性好，与“警察带走”的情形不符。", "聪明": "语义：“聪明”形容智力好，不能说明被警察带走的原因。", "整洁": "搭配：“整洁”形容外表干净，不用来说明被带走的人。"}, "sentence_index": 0, "correct_answer": "违法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的头发很违法，老师请他去剪了。", "explanation": "这里应该用〈不整齐〉。“违法”不能形容头发。"}, {"text": "他没写完作业就去玩，这样做很违法。", "explanation": "这里应该用〈不负责任〉。作业拖延是学习态度问题，不属于违法；〈违法〉只指违反法律。"}, {"text": "他每天晚睡早起，这种生活习惯很违法。", "explanation": "这里应该用〈不健康〉。作息习惯属于健康问题，不属于违法；〈违法〉只指违反法律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违法", "is_correct": true, "explanation": "“是违法的”指这种捕鱼方式违反法律，与句子语境相合。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：“好吃”形容味道，与“用电打鱼”的违法性质无关。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：“好看”形容外貌或景象，不能用来评价捕鱼方式。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”形容心情，与捕鱼方式的性质不符。"}], "explanations": {"违法": "“是违法的”指这种捕鱼方式违反法律，与句子语境相合。", "好吃": "语义：“好吃”形容味道，与“用电打鱼”的违法性质无关。", "好看": "搭配：“好看”形容外貌或景象，不能用来评价捕鱼方式。", "高兴": "语义：“高兴”形容心情，与捕鱼方式的性质不符。"}, "sentence_index": 6, "correct_answer": "违法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中违法，裁判罚他下场。", "explanation": "这里应该用〈犯规〉。比赛中的不当动作用〈犯规〉，〈违法〉只用于法律。"}, {"text": "他在考试中违法，监考老师把他的试卷收走了。", "explanation": "这里应该用〈作弊〉。考试中的舞弊行为用〈作弊〉，不是〈违法〉。"}, {"text": "他在图书馆违法，被管理员提醒了。", "explanation": "这里应该用〈违规〉。图书馆的不当行为应说〈违规〉，不是〈违法〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他偷了别人的钱，这是违法地行为。", "corrected_sentence": "他偷了别人的钱，这是违法的行为。", "error_description": "错误：“违法地行为”。“地”用于修饰动词，“违法”修饰名词时用“的”；“违法行为”是固定词语，可不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司偷税漏税，做了很多被违法的生意。", "corrected_sentence": "这家公司偷税漏税，做了很多违法的生意。", "error_description": "错误：“被违法的生意”。正确：“违法的生意”。“违法”不是及物动词，不能用“被”字句表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "与“违法”是反义关系，指符合法律规定。"}, {"text": "明亮", "is_correct": false, "explanation": "与“违法”没有反义关系，指光线充足。"}, {"text": "清楚", "is_correct": false, "explanation": "与“违法”没有反义关系，指明白、不模糊。"}, {"text": "健康", "is_correct": false, "explanation": "与“违法”没有反义关系，指身体状况良好。"}], "correct_answer": "合法", "explanations": {"合法": "与“违法”是反义关系，指符合法律规定。", "明亮": "与“违法”没有反义关系，指光线充足。", "清楚": "与“违法”没有反义关系，指明白、不模糊。", "健康": "与“违法”没有反义关系，指身体状况良好。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合法", "is_correct": true, "explanation": "与“违法”是反义关系，指符合法律规定。"}, {"text": "温暖", "is_correct": false, "explanation": "与“违法”没有反义关系，指有温度、让人舒适。"}, {"text": "新鲜", "is_correct": false, "explanation": "与“违法”没有反义关系，指刚产生或刚采摘不久。"}, {"text": "聪明", "is_correct": false, "explanation": "与“违法”没有反义关系，指智力水平高。"}], "correct_answer": "合法", "explanations": {"合法": "与“违法”是反义关系，指符合法律规定。", "温暖": "与“违法”没有反义关系，指有温度、让人舒适。", "新鲜": "与“违法”没有反义关系，指刚产生或刚采摘不久。", "聪明": "与“违法”没有反义关系，指智力水平高。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "违反法律。", "primary_collocate": null, "pronunciation": "wéi fǎ", "ipa": "wei˧˥ fa˨˩", "syllable_count": 2, "sentences": [{"text": "开车喝酒是违法的。", "target_word": "违法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在这里停车违法，会被罚钱。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做生意从来不违法。", "target_word": "违法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不交税就是违法。", "target_word": "违法", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司这样做已经违法了。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有驾照就开车，当然违法。", "target_word": "违法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他后来才知道自己的做法违法，所以很害怕。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随便拿别人的东西，不但不对，而且违法。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂把脏水倒进河里，已经违法了。", "target_word": "违法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们，不管做什么，都不能违法。", "target_word": "违法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "违了法", "label": "体标"}, {"form": "违过法", "label": "体标"}], "register": "通用", "sense_fingerprint": "违反法律，不合乎法律规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adca781d-1525-4feb-b95c-ac2c37686162') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违法", "is_correct": true, "explanation": "“违法”指违反法律，与“开车喝酒”的法律后果相合。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”形容心情好，与“开车喝酒”的危险后果不符。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：“美丽”形容外貌或景色，不能用来评价“开车喝酒”这种行为。"}, {"text": "合理", "is_correct": false, "explanation": "语义：“合理”指合乎道理，与“开车喝酒是……的”所指的法律意义冲突。"}], "explanations": {"违法": "“违法”指违反法律，与“开车喝酒”的法律后果相合。", "愉快": "语义：“愉快”形容心情好，与“开车喝酒”的危险后果不符。", "美丽": "搭配：“美丽”形容外貌或景色，不能用来评价“开车喝酒”这种行为。", "合理": "语义：“合理”指合乎道理，与“开车喝酒是……的”所指的法律意义冲突。"}, "sentence_index": 0, "correct_answer": "违法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生在课堂上玩手机，这是违法行为，老师把手机收走了。", "explanation": "这里应该用〈违纪〉。课堂纪律问题用〈违纪〉，〈违法〉只指违反法律的行为。"}, {"text": "她的字写得很违法，老师说要多练习。", "explanation": "这里应该用〈潦草〉。“违法”不能用来形容字迹。"}, {"text": "这家店的菜做得很违法，大家都不爱吃。", "explanation": "这里应该用〈难吃〉。“违法”不能用来形容菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违法", "is_correct": true, "explanation": "“违法”指做法违反法律，与“后来才知道”和“很害怕”的语境相合。"}, {"text": "高明", "is_correct": false, "explanation": "语义：“高明”形容本领好，与“很害怕”冲突。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约”指不浪费，与“很害怕”的心理不符。"}, {"text": "文雅", "is_correct": false, "explanation": "搭配：“做法文雅”不能说明害怕，“文雅”多形容言谈举止。"}], "explanations": {"违法": "“违法”指做法违反法律，与“后来才知道”和“很害怕”的语境相合。", "高明": "语义：“高明”形容本领好，与“很害怕”冲突。", "节约": "语义：“节约”指不浪费，与“很害怕”的心理不符。", "文雅": "搭配：“做法文雅”不能说明害怕，“文雅”多形容言谈举止。"}, "sentence_index": 6, "correct_answer": "违法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考试中违法，被取消了成绩。", "explanation": "这里应该用〈违规〉。考试中的不当行为是违反考试规定，不是违反法律。"}, {"text": "这个球员在比赛中违法，被裁判罚下了场。", "explanation": "这里应该用〈犯规〉。〈犯规〉用于比赛，〈违法〉只用于法律。"}, {"text": "他在图书馆里大声说话，这个行为很违法。", "explanation": "这里应该用〈不文明〉。大声说话不文明，但并不违反法律，不能说〈违法〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司违法了规定，所以被罚了款。", "corrected_sentence": "这家公司违法了，所以被罚了款。", "error_description": "错误：“违法了规定”。正确：“违法”。“违法”是不及物动词，不能带宾语；“违反规定”才带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂被违法了，所以被罚款了。", "corrected_sentence": "这家工厂违法了，所以被罚款了。", "error_description": "错误：“被违法了”。正确：“违法了”。“违法”不能用“被”字句，它本身不表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad5a228-33b1-4a81-90f6-5bd375ffe5fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
