INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "照片是用相机或手机拍出来的画面，可以留下人和东西的样子。", "primary_collocate": null, "pronunciation": "zhào piàn", "ipa": "ʈʂau̯˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这张照片是我拍的。", "target_word": "照片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有一张全家的照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把照片给妈妈看。", "target_word": "照片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手机里有很多照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片里的小狗很可爱。", "target_word": "照片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想看你小时候的照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我们在公园拍了很多照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上挂着一张老照片。", "target_word": "照片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把照片发给我吗？", "target_word": "照片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍得真好，我很喜欢。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张照片", "label": "量词"}, {"form": "老照片", "label": "复合"}], "register": "中性", "sense_fingerprint": "用相机或手机拍下来、留着人和东西样子的画面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86153, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照片", "is_correct": true, "explanation": "正确：照片是用相机拍下来的画面，与「拍」搭配，量词用「张」。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：歌不论「张」，也不能「拍」，「这张歌是我拍的」说不通。"}, {"text": "视频", "is_correct": false, "explanation": "搭配：视频是动态影像，量词用「段」，不能说「这张视频」。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子是用来照见自己的物件，不是拍下来的图像，不能说「我拍的镜子」。"}], "explanations": {"照片": "正确：照片是用相机拍下来的画面，与「拍」搭配，量词用「张」。", "歌": "搭配：歌不论「张」，也不能「拍」，「这张歌是我拍的」说不通。", "视频": "搭配：视频是动态影像，量词用「段」，不能说「这张视频」。", "镜子": "语义：镜子是用来照见自己的物件，不是拍下来的图像，不能说「我拍的镜子」。"}, "sentence_index": 0, "correct_answer": "照片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片是画家用水彩画的。", "explanation": "这里应该用〈画〉。照片要用相机拍下来，画家用水彩画出来的是「画」，不能叫照片。"}, {"text": "老师让我们在纸上画一张照片。", "explanation": "这里应该用〈图画〉。照片要用相机拍出来，用笔在纸上画出来的要说「图画」，不能叫照片。"}, {"text": "这本书的照片是用颜料和画笔画出来的。", "explanation": "这里应该用〈插图〉。照片是拍摄得到的图像，用颜料和画笔画出来的插图不能叫照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "照片", "is_correct": true, "explanation": "正确：照片是拍摄得到的画面，与「拍」搭配，符合句意。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：「拍」不能带「歌」作宾语，应说「唱歌」。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是睡觉时的想象，不能被拍下来，「拍了很多梦」说不通。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：笑声是声音，不是图像，不能被拍下来，句子不通。"}], "explanations": {"照片": "正确：照片是拍摄得到的画面，与「拍」搭配，符合句意。", "歌": "搭配：「拍」不能带「歌」作宾语，应说「唱歌」。", "梦": "语义：梦是睡觉时的想象，不能被拍下来，「拍了很多梦」说不通。", "笑声": "语义：笑声是声音，不是图像，不能被拍下来，句子不通。"}, "sentence_index": 6, "correct_answer": "照片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在本子上画照片。", "explanation": "这里应该用〈漫画〉。照片要用相机拍，画在本子上的要说「漫画」。"}, {"text": "我们用手机录下了你跳舞的照片。", "explanation": "这里应该用〈视频〉。「录」用于视频和声音，照片是静止的画面，不能说「录」。"}, {"text": "她用铅笔画了一张照片。", "explanation": "这里应该用〈素描〉。照片靠相机拍摄，用铅笔画出来的要说「素描」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在公园拍了一只照片。", "corrected_sentence": "我昨天在公园拍了一张照片。", "error_description": "量词错误：「照片」是平面的，应用「张」计量，不能用「只」（「只」用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把我的一条照片贴在冰箱上。", "corrected_sentence": "妈妈把我的一张照片贴在冰箱上。", "error_description": "量词错误：「照片」是平面的，应用「张」计量，不能用「条」（「条」用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
