INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用照相机拍摄后冲洗或打印出来的图像。", "primary_collocate": null, "pronunciation": "zhào piàn", "ipa": "ʈʂau̯˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他去店里打印了十张照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片冲洗好了，你可以来拿。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片的颜色很鲜艳。", "target_word": "照片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把照片放进相册里。", "target_word": "照片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把旧照片放在盒子里。", "target_word": "照片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说照片明天下午可以取。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买了一个相框放照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店冲洗照片很便宜。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给你寄去了几张照片。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打印出来的照片比手机里的好看。", "target_word": "照片", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张照片", "label": "量词"}, {"form": "老照片", "label": "复合"}], "register": "中性", "sense_fingerprint": "拍摄后冲洗或打印出来、可以拿在手里的纸质图像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "照片", "is_correct": true, "explanation": "正确：「打印」的对象是照片，「张」计量平面的纸质图像，符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：热情是情感，不是纸张，不能打印出来，句子说不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树是植物，不能被打印出来，「打印了十张树」说不通。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：「歌」不能用「张」计量，也不说「打印歌」，句子不通。"}], "explanations": {"照片": "正确：「打印」的对象是照片，「张」计量平面的纸质图像，符合句意。", "热情": "语义：热情是情感，不是纸张，不能打印出来，句子说不通。", "树": "语义：树是植物，不能被打印出来，「打印了十张树」说不通。", "歌": "搭配：「歌」不能用「张」计量，也不说「打印歌」，句子不通。"}, "sentence_index": 0, "correct_answer": "照片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们用毛笔在纸上画一张照片。", "explanation": "这里应该用〈国画〉。照片是拍摄或冲洗得到的图像，用毛笔在纸上画出来的作品要说「国画」，不能叫照片。"}, {"text": "他用石头刻出来的照片很精美。", "explanation": "这里应该用〈雕像〉。照片是拍摄得到的图像，用石头刻出来的立体作品要说「雕像」，不能叫照片。"}, {"text": "我们用手机录下了操场上的照片。", "explanation": "这里应该用〈视频〉。「录」用于视频和声音，照片是静止的画面，不能说「录」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "照片", "is_correct": true, "explanation": "正确：相框是用来放照片的，「放照片」搭配自然，符合句意。"}, {"text": "汤", "is_correct": false, "explanation": "语义：相框是装平面物品的，不能盛汤，「放汤」说不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能放进相框里，句子不通。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：「放」不能带「脚印」作宾语，应说「留下脚印」。"}], "explanations": {"照片": "正确：相框是用来放照片的，「放照片」搭配自然，符合句意。", "汤": "语义：相框是装平面物品的，不能盛汤，「放汤」说不通。", "雨": "语义：雨是天气现象，不能放进相框里，句子不通。", "脚印": "搭配：「放」不能带「脚印」作宾语，应说「留下脚印」。"}, "sentence_index": 6, "correct_answer": "照片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张照片是用电脑绘制的。", "explanation": "这里应该用〈插画〉。照片要用相机拍摄，用电脑绘制的画面要说「插画」，不能叫照片。"}, {"text": "她在纸上画了一张照片。", "explanation": "这里应该用〈素描〉。照片靠拍摄得到，用笔在纸上画出来的要说「素描」。"}, {"text": "他喜欢在本子上画照片。", "explanation": "这里应该用〈漫画〉。照片要用相机拍，画在本子上的要说「漫画」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "打印机里的三只照片都很清楚。", "corrected_sentence": "打印机里的三张照片都很清楚。", "error_description": "量词错误：「照片」是平面的，应用「张」计量，不能用「只」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有三条照片，都是去年拍的。", "corrected_sentence": "桌上有三张照片，都是去年拍的。", "error_description": "量词错误：「照片」是平面的，应用「张」计量，不能用「条」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
