INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86155, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酒店是人出远门时睡觉、住的大房子。", "primary_collocate": null, "pronunciation": "jiǔ diàn", "ipa": "tɕiou̯˨˩˦ tiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们今天住在海边的酒店。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店离火车站很近。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上订了一家酒店。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的房间又大又干净。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出差时总住同一家酒店。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店里有一个小花园。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行的时候，我们晚上住酒店。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到酒店的时候已经很晚了。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店一晚多少钱？", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在酒店的房间里休息。", "target_word": "酒店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "大酒店", "label": "复合"}, {"form": "五星级酒店", "label": "复合"}], "register": "中性", "sense_fingerprint": "出门在外住宿用的大房子，旅行时睡觉的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0344090-a91f-48fd-a918-ec4ab7350984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酒店", "is_correct": true, "explanation": "正确：“酒店”是出门在外住宿的地方，海边可以住在酒店里。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”供人吃饭，不是住宿的地方，与“住在”不合。"}, {"text": "超市", "is_correct": false, "explanation": "语义：“超市”是购物的场所，不能用来住。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“住在”后面不能接“书店”，书店不供人住宿。"}], "explanations": {"酒店": "正确：“酒店”是出门在外住宿的地方，海边可以住在酒店里。", "饭馆": "语义：“饭馆”供人吃饭，不是住宿的地方，与“住在”不合。", "超市": "语义：“超市”是购物的场所，不能用来住。", "书店": "搭配：“住在”后面不能接“书店”，书店不供人住宿。"}, "sentence_index": 0, "correct_answer": "酒店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在酒店里养了一群鸡。", "explanation": "这里应该用〈农场〉。养鸡要在农场，“酒店”是提供住宿的场所。"}, {"text": "这家酒店跑得很快。", "explanation": "这里应该用〈汽车〉。“跑得快”说的是车辆或人，“酒店”是建筑，不能跑。"}, {"text": "这家酒店的头发很长。", "explanation": "这里应该用〈人〉。头发长是人的特征，“酒店”是建筑，没有头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酒店", "is_correct": true, "explanation": "正确：“住”后接“酒店”，旅行时晚上住在酒店。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”供人吃饭，不是住宿的地方。"}, {"text": "商场", "is_correct": false, "explanation": "语义：“商场”是购物的地方，不能用来住。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“图书馆”是借阅书籍的地方，不与“住”搭配。"}], "explanations": {"酒店": "正确：“住”后接“酒店”，旅行时晚上住在酒店。", "餐厅": "语义：“餐厅”供人吃饭，不是住宿的地方。", "商场": "语义：“商场”是购物的地方，不能用来住。", "图书馆": "搭配：“图书馆”是借阅书籍的地方，不与“住”搭配。"}, "sentence_index": 6, "correct_answer": "酒店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天给酒店刷牙。", "explanation": "这里应该用〈牙齿〉。刷牙的对象是牙齿，“酒店”是住宿的场所，不能用来刷。"}, {"text": "这家酒店每天都去上班。", "explanation": "这里应该用〈人〉。上班的是人，“酒店”是建筑，不能去上班。"}, {"text": "他一边跑步，一边吃酒店。", "explanation": "这里应该用〈饭〉。能吃的是食物，“酒店”是住宿的场所，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在火车站附近找了几家酒店们。", "corrected_sentence": "我们在火车站附近找了几家酒店。", "error_description": "“酒店”指建筑，不是人，不能加复数后缀“们”。错误是“酒店们”，正确应说“几家酒店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在海边找到了一张酒店。", "corrected_sentence": "他们在海边找到了一家酒店。", "error_description": "酒店应用“家”计量，“张”用于平面的东西。错误是“一张酒店”，正确应说“一家酒店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be1eec8e-4991-47be-b6b4-887621ef7c45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
