INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某些国家的国家元首或政府首脑。", "primary_collocate": null, "pronunciation": "zǒng tǒng", "ipa": "tsʊŋ˧˥ tʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "总统每四年选一次。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国总统住在白宫。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法国总统今天会见了中国朋友。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统宣布明年要建新学校。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位总统很受人民喜欢。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统和记者谈了一个小时。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个国家的新总统是医生。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统在会上说，大家要努力工作。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是第一位女总统，大家都知道她。", "target_word": "总统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统走进房间，大家都站起来了。", "target_word": "总统", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副总统", "label": "复合"}, {"form": "總統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，某些国家的国家元首或政府首脑，由选举等方式产生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总统", "is_correct": true, "explanation": "正确。“总统”是经选举产生的国家元首，可以每四年选一次。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“选”的对象是人或职位，电视不能每四年被选一次。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能被选举。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“选”指选举人或职务，不能和“蛋糕”搭配。"}], "explanations": {"总统": "正确。“总统”是经选举产生的国家元首，可以每四年选一次。", "电视": "语义：“选”的对象是人或职位，电视不能每四年被选一次。", "春天": "语义：春天是季节，不能被选举。", "蛋糕": "搭配：“选”指选举人或职务，不能和“蛋糕”搭配。"}, "sentence_index": 0, "correct_answer": "总统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所大学的总统每年都给新生讲话。", "explanation": "这里应该用〈校长〉。“总统”指国家元首；大学的负责人要说“校长”。"}, {"text": "我们市的总统每年都来看我们。", "explanation": "这里应该用〈市长〉。“总统”指国家元首；城市的行政负责人要说“市长”。"}, {"text": "这个州的总统是我的朋友。", "explanation": "这里应该用〈州长〉。州的行政负责人叫“州长”，不是“总统”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总统", "is_correct": true, "explanation": "正确。“是医生”的主语是人，“总统”符合语境。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是人，不能是医生。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是人，不能是医生。"}, {"text": "掌柜", "is_correct": false, "explanation": "语域：“掌柜”是旧时店铺老板的称呼，用来指现代国家的领导人不合语域。"}], "explanations": {"总统": "正确。“是医生”的主语是人，“总统”符合语境。", "房子": "语义：“房子”不是人，不能是医生。", "空气": "语义：“空气”不是人，不能是医生。", "掌柜": "语域：“掌柜”是旧时店铺老板的称呼，用来指现代国家的领导人不合语域。"}, "sentence_index": 6, "correct_answer": "总统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个剧团的总统每周都来排练场看看。", "explanation": "这里应该用〈团长〉。“总统”指国家元首；剧团的负责人要说“团长”。"}, {"text": "我们球队的总统每场比赛前都会讲几句话。", "explanation": "这里应该用〈队长〉。“总统”指国家元首；球队的负责人要说“队长”。"}, {"text": "我们班的总统每天早上都在教室门口迎接学生。", "explanation": "这里应该用〈班主任〉。“总统”指国家元首；班级的负责老师要说“班主任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家选了一只新总统。", "corrected_sentence": "这个国家选了一位新总统。", "error_description": "错误：量词“只”用错了。“总统”指人，应用量词“位”，不能用动物量词“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个国家选出了一只年轻的总统。", "corrected_sentence": "那个国家选出了一位年轻的总统。", "error_description": "错误：量词“只”用错了。“总统”指人，应用量词“位”，不能用动物量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
