INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "共有是一共有这么多。", "primary_collocate": null, "pronunciation": "gòng yǒu", "ipa": "kʊŋ˥˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们班共有三十个学生。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市共有五个公园。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书共有十章。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一年共有十二个月。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校里共有两百多位老师。", "target_word": "共有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街上共有八家饭馆。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家共有四口人。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试共有五十道题。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一周共有七天。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司共有一百个人。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说明总数：合起来一共有多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共有", "is_correct": true, "explanation": "“共有”表示总共有，符合“我们班一共有三十个学生”的句意。"}, {"text": "占", "is_correct": false, "explanation": "搭配：“占”指占据位置或比例，不说“我们班占三十个学生”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语是活动、组织，不能说“我们班参加三十个学生”。"}, {"text": "夺得", "is_correct": false, "explanation": "搭配：“夺得”指争取到名次、奖项或胜利，不能用来数人数。"}], "explanations": {"共有": "“共有”表示总共有，符合“我们班一共有三十个学生”的句意。", "占": "搭配：“占”指占据位置或比例，不说“我们班占三十个学生”。", "参加": "配价：“参加”的宾语是活动、组织，不能说“我们班参加三十个学生”。", "夺得": "搭配：“夺得”指争取到名次、奖项或胜利，不能用来数人数。"}, "sentence_index": 0, "correct_answer": "共有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅共有很高的评分。", "explanation": "这里应该用〈获得〉。共有指总数或几方共同拥有，评分这类结果要说获得。"}, {"text": "他共有很高的水平。", "explanation": "这里应该用〈具有〉。共有只用于数量或几方共同拥有的事物，人的水平要用具有。"}, {"text": "他共有丰富的工作经验。", "explanation": "这里应该用〈具备〉。共有只用于总数或几方共同拥有的事物，个人的经验要说具备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共有", "is_correct": true, "explanation": "“共有”表示一共有，符合“我家一共四口人”的句意。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”是分开、分配的意思，不表示家里总共有几口人。"}, {"text": "组成", "is_correct": false, "explanation": "配价：“组成”要用“由……组成”的格式，不直接带人数，“我家组成四口人”不通。"}, {"text": "生", "is_correct": false, "explanation": "语义：“生”是生育的意思，“我家生四口人”指生育，不是家里总共有几口人。"}], "explanations": {"共有": "“共有”表示一共有，符合“我家一共四口人”的句意。", "分": "语义：“分”是分开、分配的意思，不表示家里总共有几口人。", "组成": "配价：“组成”要用“由……组成”的格式，不直接带人数，“我家组成四口人”不通。", "生": "语义：“生”是生育的意思，“我家生四口人”指生育，不是家里总共有几口人。"}, "sentence_index": 6, "correct_answer": "共有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司共有很高的声誉。", "explanation": "这里应该用〈享有〉。共有指数量或几方共同拥有的事物，不用来说声誉。"}, {"text": "这位老师共有很强的教学能力。", "explanation": "这里应该用〈拥有〉。共有指总数或几方共同拥有，老师个人的能力要说拥有。"}, {"text": "这位运动员共有很好的状态。", "explanation": "这里应该用〈保持〉。共有指总数或几方共同拥有，个人的状态要说保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们年级共有八只班。", "corrected_sentence": "我们年级共有八个班。", "error_description": "错误：量词“只”；正确：“个”。“班”的量词用“个”，“只”用于动物等，不能用于班级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校共有十条年级。", "corrected_sentence": "这所学校共有十个年级。", "error_description": "错误：量词“条”；正确：“个”。“年级”的量词用“个”，“条”用于细长的东西，不能用于年级。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
