INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86160, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "几个人或几方一起拥有同一样东西或同一种想法。", "primary_collocate": null, "pronunciation": "gòng yǒu", "ipa": "kʊŋ˥˩ joʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这片花园是邻居共有的。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这套房子是夫妻共有的。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们共有一个梦想。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器是三家工厂共有的。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兄弟两人共有一辆车。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些书是全班同学共有的。", "target_word": "共有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间共有很多回忆。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块地是两家人共有的。", "target_word": "共有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们共有一个愿望，就是回家。", "target_word": "共有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店是三个朋友共有的。", "target_word": "共有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "几个人或几方一起拥有同一样东西或同一种想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共有", "is_correct": true, "explanation": "“共有”表示几方一起拥有，符合“邻居共同拥有这片花园”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是吞咽食物，句子说的是拥有关系，这里不成立。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能用“是邻居参观的”表示归属。"}, {"text": "叫", "is_correct": false, "explanation": "语义：“叫”是喊、称呼的意思，与花园的归属无关。"}], "explanations": {"共有": "“共有”表示几方一起拥有，符合“邻居共同拥有这片花园”的句意。", "吃": "语义：“吃”是吞咽食物，句子说的是拥有关系，这里不成立。", "参观": "搭配：“参观”的对象是场所或展览，不能用“是邻居参观的”表示归属。", "叫": "语义：“叫”是喊、称呼的意思，与花园的归属无关。"}, "sentence_index": 0, "correct_answer": "共有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班共有很高的平均分。", "explanation": "这里应该用〈取得〉。共有指总数或几方共同拥有，平均分这类成绩要说取得。"}, {"text": "这家小店共有很强的竞争力。", "explanation": "这里应该用〈拥有〉。共有指总数或几方共同拥有，店铺的竞争力要说拥有。"}, {"text": "他共有很强的组织能力。", "explanation": "这里应该用〈具有〉。共有指几方一起拥有同一样东西或想法，一个人自己的能力要用具有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共有", "is_correct": true, "explanation": "“共有”表示几方共同拥有，朋友之间共同拥有回忆，符合句意。"}, {"text": "夺得", "is_correct": false, "explanation": "搭配：“夺得”指争取到名次、奖项或胜利，不能用来说回忆。"}, {"text": "组成", "is_correct": false, "explanation": "配价：“组成”要用“由……组成”的格式，不直接带“回忆”作宾语。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”的宾语是事件，不能说“发生很多回忆”。"}], "explanations": {"共有": "“共有”表示几方共同拥有，朋友之间共同拥有回忆，符合句意。", "夺得": "搭配：“夺得”指争取到名次、奖项或胜利，不能用来说回忆。", "组成": "配价：“组成”要用“由……组成”的格式，不直接带“回忆”作宾语。", "发生": "配价：“发生”的宾语是事件，不能说“发生很多回忆”。"}, "sentence_index": 6, "correct_answer": "共有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手共有很高的声誉。", "explanation": "这里应该用〈享有〉。共有指几方一起拥有，不能用来说一个人的声誉。"}, {"text": "这位医生共有很好的口碑。", "explanation": "这里应该用〈赢得〉。共有指总数或几方共同拥有，口碑要说赢得。"}, {"text": "这所学校共有很好的条件。", "explanation": "这里应该用〈具备〉。共有指几方共同拥有，学校具备条件要说具备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间仓库是几位农民共有地的。", "corrected_sentence": "这间仓库是几位农民共有的。", "error_description": "错误：结构助词“地”；正确：“的”。“是……共有的”是“是……的”结构，要用“的”，“地”是状语标记，不能用于此处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套乐器是三个乐手共有了的。", "corrected_sentence": "这套乐器是三个乐手共有的。", "error_description": "错误：“共有了的”；正确：“共有的”。“共有”是表示拥有关系的动词，一般不加“了”，修饰名词时直接用“共有的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
