INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86161, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“各”是说每一个都有自己的，不是同一个。", "primary_collocate": null, "pronunciation": "gè", "ipa": "kɤ˥˩", "syllable_count": 1, "sentences": [{"text": "大家各有各的想法。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们各回各的家。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个人各说各的。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "兄弟两个各有各的房间。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们各做各的作业，教室很安静。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两件衣服各有各的好处。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们各忙各的，很少见面。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们各走各的路，再也没有见过面。", "target_word": "各", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个孩子各有各的脾气。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们各想各的办法。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "各自", "label": "复合"}, {"form": "各个", "label": "复合"}], "register": "中性", "sense_fingerprint": "各有各的，每个都有自己的，彼此不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86161, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "各", "is_correct": true, "explanation": "正确答案：各（gè，第四声），指每一个各自的。"}, {"text": "歌", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是歌。"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是格子、标准。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），意思是课。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 gè 韵母不同（u 与 e），意思是故事、缘故。"}], "explanations": {"各": "正确答案：各（gè，第四声），指每一个各自的。", "歌": "gē（第一声）与 gè（第四声）声调不同，意思是歌。", "格": "gé（第二声）与 gè（第四声）声调不同，意思是格子、标准。", "课": "kè 与 gè 声母不同（k 与 g），意思是课。", "故": "gù 与 gè 韵母不同（u 与 e），意思是故事、缘故。"}, "sentence_index": null, "correct_answer": "各"}, "level_3": {"options": [{"text": "各", "is_correct": true, "explanation": "“大家”后接“各有各的想法”，表示每人各自有想法，只有“各”合适。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“大家”已指全体，再用“他们”重复指代，句子不通。"}, {"text": "其他", "is_correct": false, "explanation": "语义：“其他”指别的人，与“大家”指全体中的每一个不符。"}, {"text": "每", "is_correct": false, "explanation": "语法：“每”须与量词或名词组合，“大家每有”不成立。"}], "explanations": {"各": "“大家”后接“各有各的想法”，表示每人各自有想法，只有“各”合适。", "他们": "语义：“大家”已指全体，再用“他们”重复指代，句子不通。", "其他": "语义：“其他”指别的人，与“大家”指全体中的每一个不符。", "每": "语法：“每”须与量词或名词组合，“大家每有”不成立。"}, "sentence_index": 0, "correct_answer": "各"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这三个孩子各长得一模一样。", "explanation": "这里应该用〈都〉。“各”强调彼此不同，与“一模一样”矛盾；说几个人都一样时用“都”。"}, {"text": "我各有一把钥匙。", "explanation": "“各”要求两个或以上的人或事物分别行动，这里只有“我”一个主体，不能用“各”。"}, {"text": "我们各在一起吃饭。", "explanation": "这里应该用〈都〉。“各”表示分别、各自，与“在一起”的共同行动矛盾；大家共同吃饭时用“都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86161, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "各", "is_correct": true, "explanation": "正确答案：各（gè，第四声），指每一个各自的。"}, {"text": "割", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是割开。"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是隔开、间隔。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），意思是客人。"}, {"text": "顾", "is_correct": false, "explanation": "gù 与 gè 韵母不同（u 与 e），意思是照顾、顾及。"}, {"text": "贺", "is_correct": false, "explanation": "hè 与 gè 声母不同（h 与 g），都是第四声，意思是祝贺。"}], "explanations": {"各": "正确答案：各（gè，第四声），指每一个各自的。", "割": "gē（第一声）与 gè（第四声）声调不同，意思是割开。", "隔": "gé（第二声）与 gè（第四声）声调不同，意思是隔开、间隔。", "客": "kè 与 gè 声母不同（k 与 g），意思是客人。", "顾": "gù 与 gè 韵母不同（u 与 e），意思是照顾、顾及。", "贺": "hè 与 gè 声母不同（h 与 g），都是第四声，意思是祝贺。"}, "sentence_index": null, "correct_answer": "各"}, "level_3": {"options": [{"text": "各", "is_correct": true, "explanation": "“周末我们”后接“忙各的”，表示每人忙自己的事，只有“各”合适。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指说话人以外的人，与“我们”指同一群体不符。"}, {"text": "人家", "is_correct": false, "explanation": "语法：“人家”指别人，不能与“我们”并列作主语，“我们人家”不成立。"}, {"text": "谁", "is_correct": false, "explanation": "配价：“谁”是疑问代词，不能放在“我们”后面充当陈述句中同指的成分。"}], "explanations": {"各": "“周末我们”后接“忙各的”，表示每人忙自己的事，只有“各”合适。", "别人": "语义：“别人”指说话人以外的人，与“我们”指同一群体不符。", "人家": "语法：“人家”指别人，不能与“我们”并列作主语，“我们人家”不成立。", "谁": "配价：“谁”是疑问代词，不能放在“我们”后面充当陈述句中同指的成分。"}, "sentence_index": 6, "correct_answer": "各"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们各想一样的办法。", "explanation": "这里应该用〈都〉。“各”强调各自不同，与“一样的”矛盾；大家想同样的办法时用“都”。"}, {"text": "老师让我一个人各想了办法。", "explanation": "“各”要求两个以上的主体分别行动，这里只有“我”一个人，不能用“各”。"}, {"text": "老师让我们各一起想办法。", "explanation": "这里应该用〈都〉。“各”表示分别、各自，与“一起”所表示的共同行动矛盾；大家共同做同一件事时用“都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们各有各任务。", "corrected_sentence": "我们各有各的任务。", "error_description": "错误：“各有各任务”。正确：“各有各的任务”。“各的”后接名词时要保留“的”，漏掉“的”不符合规范说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们各拿的各书。", "corrected_sentence": "孩子们各拿各的书。", "error_description": "错误：“的各书”。正确：“各的书”。“的”应紧跟“各”，放在“各”后面，不能放在“各”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
