INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86162, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，表示全体中的每一个。", "primary_collocate": null, "pronunciation": "gè", "ipa": "kɤ˥˩", "syllable_count": 1, "sentences": [{"text": "我们各带一本书。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个小组各选一个人。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "各班都在上课。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每张桌子上各放一杯茶。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个队各有十个人。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "各部门的老师都来开会。", "target_word": "各", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次比赛，各学校都派了学生参加。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给每个学生发书，各发两本。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们三个人各付一百块钱。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给两个孩子各买了一件新衣服。", "target_word": "各", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "各自", "label": "复合"}, {"form": "各位", "label": "复合"}], "register": "中性", "sense_fingerprint": "指全体中的每一个，各+量词／名词／动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "各", "is_correct": true, "explanation": "正确答案：各（gè，第四声），指全体中的每一个。"}, {"text": "歌", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是歌。"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是格子、标准。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），意思是客人。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 gè 韵母不同（u 与 e），意思是故事、缘故。"}], "explanations": {"各": "正确答案：各（gè，第四声），指全体中的每一个。", "歌": "gē（第一声）与 gè（第四声）声调不同，意思是歌。", "格": "gé（第二声）与 gè（第四声）声调不同，意思是格子、标准。", "客": "kè 与 gè 声母不同（k 与 g），意思是客人。", "故": "gù 与 gè 韵母不同（u 与 e），意思是故事、缘故。"}, "sentence_index": null, "correct_answer": "各"}, "level_3": {"options": [{"text": "各", "is_correct": true, "explanation": "“我们”后面接“带一本书”，表示每人各带一本，只有“各”表示“每一个”。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“我们”与“他们”指代不同群体，不能并列作主语表示每一个人。"}, {"text": "其他", "is_correct": false, "explanation": "语义：“其他”指别的人，与“我们”不是同一指称范围。"}, {"text": "彼此", "is_correct": false, "explanation": "搭配：“彼此”表示相互关系，不与“带一本书”这种分别行动搭配。"}], "explanations": {"各": "“我们”后面接“带一本书”，表示每人各带一本，只有“各”表示“每一个”。", "他们": "语义：“我们”与“他们”指代不同群体，不能并列作主语表示每一个人。", "其他": "语义：“其他”指别的人，与“我们”不是同一指称范围。", "彼此": "搭配：“彼此”表示相互关系，不与“带一本书”这种分别行动搭配。"}, "sentence_index": 0, "correct_answer": "各"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几张桌子各一样高。", "explanation": "这里应该用〈都〉。“各”强调彼此不同，与“一样高”矛盾；说几张桌子都一样高时用“都”。"}, {"text": "这张桌子各放了一杯茶。", "explanation": "“各”要求两个或以上的对象分别行动，这里只有一张桌子，不能用“各”。"}, {"text": "每张桌子上各一起放了一杯茶。", "explanation": "“各”表示分别、各自，与“一起”的共同行动矛盾；去掉“一起”，说“每张桌子上各放了一杯茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86162, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "各", "is_correct": true, "explanation": "正确答案：各（gè，第四声），指全体中的每一个。"}, {"text": "割", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是割开。"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是隔开、间隔。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），意思是课。"}, {"text": "顾", "is_correct": false, "explanation": "gù 与 gè 韵母不同（u 与 e），意思是照顾、顾及。"}, {"text": "贺", "is_correct": false, "explanation": "hè 与 gè 声母不同（h 与 g），都是第四声，意思是祝贺。"}], "explanations": {"各": "正确答案：各（gè，第四声），指全体中的每一个。", "割": "gē（第一声）与 gè（第四声）声调不同，意思是割开。", "隔": "gé（第二声）与 gè（第四声）声调不同，意思是隔开、间隔。", "课": "kè 与 gè 声母不同（k 与 g），意思是课。", "顾": "gù 与 gè 韵母不同（u 与 e），意思是照顾、顾及。", "贺": "hè 与 gè 声母不同（h 与 g），都是第四声，意思是祝贺。"}, "sentence_index": null, "correct_answer": "各"}, "level_3": {"options": [{"text": "各", "is_correct": true, "explanation": "“各学校都派了学生”表示每所学校都派了人，只有“各”表示全体中的每一个。"}, {"text": "每", "is_correct": false, "explanation": "搭配：“每”修饰学校时要带量词“所”，“每学校”不能单独成立。"}, {"text": "某", "is_correct": false, "explanation": "语义：“某”指某个特定的一所学校，与“都派了学生”的全体含义冲突。"}, {"text": "本", "is_correct": false, "explanation": "语义：“本”指这一所，只能指代一个学校，与“各学校”的复数范围不符。"}], "explanations": {"各": "“各学校都派了学生”表示每所学校都派了人，只有“各”表示全体中的每一个。", "每": "搭配：“每”修饰学校时要带量词“所”，“每学校”不能单独成立。", "某": "语义：“某”指某个特定的一所学校，与“都派了学生”的全体含义冲突。", "本": "语义：“本”指这一所，只能指代一个学校，与“各学校”的复数范围不符。"}, "sentence_index": 6, "correct_answer": "各"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给两个孩子各买了一样的一件衣服。", "explanation": "“各”强调分别给每一个，句中“一样的一件”却指同一件东西，前后矛盾，不能用“各”。"}, {"text": "妈妈给一个孩子各买了一件新衣服。", "explanation": "“各”要求两个以上的对象分别行动，这里只有一个孩子，不能用“各”。"}, {"text": "妈妈给两个孩子各一起买了一件新衣服。", "explanation": "“各”表示分别、各自，与“一起”的共同行动矛盾；去掉“一起”，说“妈妈给两个孩子各买了一件新衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们拿各一把伞。", "corrected_sentence": "我们各拿一把伞。", "error_description": "错误：“拿各一把伞”。正确：“各拿一把伞”。“各”修饰动词，应放在主语之后、动词之前，不能放在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个班有各二十个学生。", "corrected_sentence": "两个班各有二十个学生。", "error_description": "错误：“有各二十个学生”。正确：“各有二十个学生”。“各”要放在动词“有”的前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
