INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86163, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "冠军是比赛里得第一名的人。", "primary_collocate": null, "pronunciation": "guàn jūn", "ipa": "kwan˥˩ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "这次比赛的冠军是一位小学生。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冠军站在台上，大家都给他鼓掌。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我认识那位游泳冠军。", "target_word": "冠军", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冠军今天会来我们学校。", "target_word": "冠军", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "记者问冠军：“你累不累？”", "target_word": "冠军", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位冠军每天早上六点起床练习。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冠军笑着对大家说谢谢。", "target_word": "冠军", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的冠军今年又来了。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我们市的乒乓球冠军。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冠军的妈妈在台下哭了。", "target_word": "冠军", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "世界冠军", "label": "复合"}, {"form": "冠軍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛中获得第一名的那个人或队伍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39686117-ff5b-4662-b33e-7c30377afa02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冠军", "is_correct": true, "explanation": "正确：冠军指比赛中获得第一名的人，与“一位小学生”相符。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：奖杯是物品，不能“是一位小学生”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师的身份与“小学生”矛盾，句子读起来不通。"}, {"text": "教授", "is_correct": false, "explanation": "语义：教授是大学教师，与“小学生”的身份矛盾，句子读起来不通。"}], "explanations": {"冠军": "正确：冠军指比赛中获得第一名的人，与“一位小学生”相符。", "奖杯": "语义：奖杯是物品，不能“是一位小学生”。", "老师": "语义：老师的身份与“小学生”矛盾，句子读起来不通。", "教授": "语义：教授是大学教师，与“小学生”的身份矛盾，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "冠军"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位冠军在比赛中得了第二名。", "explanation": "这里应该用〈选手〉。“冠军”就是得第一名的人，不能“得了第二名”；“选手”不限名次。"}, {"text": "这次比赛第三名的冠军很开心。", "explanation": "这里应该用〈运动员〉。“冠军”专指第一名，不能和“第三名”并列；“运动员”不限名次。"}, {"text": "我昨天在公园见到了一棵冠军。", "explanation": "这里应该用〈位〉。“棵”用于树木，不能用来数人，指人的冠军要用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冠军", "is_correct": true, "explanation": "正确：冠军是获胜的人，可以笑着对大家说谢谢。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“笑”和“说”要求有人做主语，“石头”不能做施事。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不会笑，也不会说谢谢。"}, {"text": "柜子", "is_correct": false, "explanation": "语义：柜子是家具，无法笑着对大家说话。"}], "explanations": {"冠军": "正确：冠军是获胜的人，可以笑着对大家说谢谢。", "石头": "配价：“笑”和“说”要求有人做主语，“石头”不能做施事。", "电脑": "语义：电脑是机器，不会笑，也不会说谢谢。", "柜子": "语义：柜子是家具，无法笑着对大家说话。"}, "sentence_index": 6, "correct_answer": "冠军"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班来了一头冠军。", "explanation": "这里应该用〈位〉。“头”用于大型牲畜，不能用来数人。"}, {"text": "这次比赛的冠军是最后一名。", "explanation": "这里应该用〈选手〉。“冠军”是第一名的人，不能是“最后一名”；“选手”可以是任何名次。"}, {"text": "学校为他买了一件冠军。", "explanation": "这里应该用〈位〉。“件”用于衣物、事情等，不能用来数指人的冠军。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的邻居是一只乒乓球冠军。", "corrected_sentence": "我的邻居是一位乒乓球冠军。", "error_description": "量词错误：指人的“冠军”要用“位”，“只”用于动物，不能用来数人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位冠军们都来了。", "corrected_sentence": "两位冠军都来了。", "error_description": "重复标记错误：“两位”已经表示数量，“冠军”后不能再加“们”，应说“两位冠军都来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
