INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86165, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "市是很多人住在一起、有很多房子和商店的大地方。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂɻ̩˥˩", "syllable_count": 1, "sentences": [{"text": "我们市很大，有很多商店。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ men shì hěn dà, yǒu hěn duō shāng diàn。", "sentence_source": "generated"}, {"text": "我想搬去你们市，不想待在小村。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ xiǎng bān qù nǐ men shì, bù xiǎng dāi zài xiǎo cūn。", "sentence_source": "generated"}, {"text": "他从小镇搬到了我们市。", "target_word": "市", "complexity_tier": "T3", "furigana": "tā cóng xiǎo zhèn bān dào le wǒ men shì。", "sentence_source": "generated"}, {"text": "我们市人很多，路上常常堵车。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ men shì rén hěn duō, lù shang cháng cháng dǔ chē。", "sentence_source": "generated"}, {"text": "他们市的夜晚很热闹，到处都是商店。", "target_word": "市", "complexity_tier": "T3", "furigana": "tā men shì de yè wǎn hěn rè nao, dào chù dōu shì shāng diàn。", "sentence_source": "generated"}, {"text": "我们市的人都很热情。", "target_word": "市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢我们市的空气。", "target_word": "市", "complexity_tier": "T3", "furigana": "tā bù xǐ huan wǒ men shì de kōng qì。", "sentence_source": "generated"}, {"text": "你们市有很多高楼和大商店。", "target_word": "市", "complexity_tier": "T3", "furigana": "nǐ men shì yǒu hěn duō gāo lóu hé dà shāng diàn。", "sentence_source": "generated"}, {"text": "她第一次来我们市，还不认识路。", "target_word": "市", "complexity_tier": "T3", "furigana": "tā dì yī cì lái wǒ men shì, hái bú rèn shi lù。", "sentence_source": "generated"}, {"text": "我们市晚上也有很多人逛街。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ men shì wǎn shang yě yǒu hěn duō rén guàng jiē。", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "城市", "label": "复合词"}, {"form": "市长", "label": "复合词"}], "register": "中性", "sense_fingerprint": "市：人多房多、有商店的大地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86165, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“市”（shì）指人多房多、有商店的大地方。"}, {"text": "时", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）声调不同，“时”意思是时间。"}, {"text": "失", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shì（第四声）声调不同，“失”意思是失去。"}, {"text": "始", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“始”意思是开始。"}, {"text": "寺", "is_correct": false, "explanation": "声母不同：sì 与 shì 的区别在于 s 与 sh，“寺”意思是寺庙。"}], "explanations": {"市": "正确答案。“市”（shì）指人多房多、有商店的大地方。", "时": "声调不同：shí（第二声）与 shì（第四声）声调不同，“时”意思是时间。", "失": "声调不同：shī（第一声）与 shì（第四声）声调不同，“失”意思是失去。", "始": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“始”意思是开始。", "寺": "声母不同：sì 与 shì 的区别在于 s 与 sh，“寺”意思是寺庙。"}, "sentence_index": null, "correct_answer": "市"}, "level_3": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“我们市很大，有很多商店”描述的是人多房多的大地方，是唯一符合语境的选项。"}, {"text": "树", "is_correct": false, "explanation": "语义：“树”指植物，“树很大，有很多商店”不能成立。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不是可以开设商店的地方，“书很大，有很多商店”说不通。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“很大，有很多商店”描述地方，不能用来形容“鞋”。"}], "explanations": {"市": "正确答案。“我们市很大，有很多商店”描述的是人多房多的大地方，是唯一符合语境的选项。", "树": "语义：“树”指植物，“树很大，有很多商店”不能成立。", "书": "语义：“书”不是可以开设商店的地方，“书很大，有很多商店”说不通。", "鞋": "搭配：“很大，有很多商店”描述地方，不能用来形容“鞋”。"}, "sentence_index": 0, "correct_answer": "市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们有一条市，人口很多。", "explanation": "量词误用：“条”用于路、河、鱼等长条形的东西，不能计量“市”，应用“个”。"}, {"text": "我们有一朵市，人口很多。", "explanation": "量词误用：“朵”用于花、云等，不能计量“市”，应用“座”或“个”。"}, {"text": "我们有一台市，人口很多。", "explanation": "量词误用：“台”用于机器、电器等，不能计量“市”，应用“座”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86165, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“市”（shì）指人多房多、有商店的大地方。"}, {"text": "十", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）声调不同，“十”是数字。"}, {"text": "史", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“史”意思是历史。"}, {"text": "石", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）声调不同，“石”意思是石头。"}, {"text": "四", "is_correct": false, "explanation": "声母不同：sì 与 shì 的区别在于 s 与 sh，“四”是数字。"}], "explanations": {"市": "正确答案。“市”（shì）指人多房多、有商店的大地方。", "十": "声调不同：shí（第二声）与 shì（第四声）声调不同，“十”是数字。", "史": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“史”意思是历史。", "石": "声调不同：shí（第二声）与 shì（第四声）声调不同，“石”意思是石头。", "四": "声母不同：sì 与 shì 的区别在于 s 与 sh，“四”是数字。"}, "sentence_index": null, "correct_answer": "市"}, "level_3": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“他不喜欢我们市的空气”中，“市”指所在的城市，是唯一符合语境的选项。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”不是地方，“我们花的空气”说不通。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“猫”不是地方，“我们猫的空气”不能表示所在的环境。"}, {"text": "笔", "is_correct": false, "explanation": "搭配：“笔”不能用来修饰“空气”，与“我们……的空气”不搭配。"}], "explanations": {"市": "正确答案。“他不喜欢我们市的空气”中，“市”指所在的城市，是唯一符合语境的选项。", "花": "语义：“花”不是地方，“我们花的空气”说不通。", "猫": "语义：“猫”不是地方，“我们猫的空气”不能表示所在的环境。", "笔": "搭配：“笔”不能用来修饰“空气”，与“我们……的空气”不搭配。"}, "sentence_index": 6, "correct_answer": "市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张市很大。", "explanation": "量词误用：“张”用于纸、桌子等平面的东西，不能计量“市”，应用“个”。"}, {"text": "这件市人很多。", "explanation": "量词误用：“件”用于衣服、事情，不能计量“市”，应用“个”。"}, {"text": "这首市很热闹。", "explanation": "量词误用：“首”用于诗词、歌曲，不能计量“市”，应用“座”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只市的夜晚很热闹。", "corrected_sentence": "这个市的夜晚很热闹。", "error_description": "量词错误：“只”用于动物，不能计量“市”，应用“个”。正确形式是“这个市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86165, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个市们的交通很方便。", "corrected_sentence": "那个市的交通很方便。", "error_description": "“市”后加复数后缀“们”是错误：“们”一般只加在指人的名词后，“市”是地方名词，不能加“们”，应说“那个市的交通很方便”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
