INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86166, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行政区划单位，也指人口集中的城镇。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂɻ̩˥˩", "syllable_count": 1, "sentences": [{"text": "我们市的春天来得很早。", "target_word": "市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们市有三百多万人口。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ men shì yǒu sān bǎi duō wàn rén kǒu。", "sentence_source": "generated"}, {"text": "你们市每年都有很多游客吗？", "target_word": "市", "complexity_tier": "T3", "furigana": "nǐ men shì měi nián dōu yǒu hěn duō yóu kè ma？", "sentence_source": "generated"}, {"text": "我们市新修了三条地铁线。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ men shì xīn xiū le sān tiáo dì tiě xiàn。", "sentence_source": "generated"}, {"text": "你们市冬天冷不冷？", "target_word": "市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们市离海很近，空气很好。", "target_word": "市", "complexity_tier": "T3", "furigana": "tā men shì lí hǎi hěn jìn, kōng qì hěn hǎo。", "sentence_source": "generated"}, {"text": "他从小就住在我们市。", "target_word": "市", "complexity_tier": "T3", "furigana": "tā cóng xiǎo jiù zhù zài wǒ men shì。", "sentence_source": "generated"}, {"text": "我们市的公园比你们市的多。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ men shì de gōng yuán bǐ nǐ men shì de duō。", "sentence_source": "generated"}, {"text": "我去过很多地方，还是最喜欢我们市。", "target_word": "市", "complexity_tier": "T3", "furigana": "wǒ qù guo hěn duō dì fang, háishi zuì xǐ huan wǒ men shì。", "sentence_source": "generated"}, {"text": "我们市的老人都爱在早上打太极拳。", "target_word": "市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "城市", "label": "复合词"}, {"form": "市长", "label": "复合词"}], "register": "中性", "sense_fingerprint": "市：行政区划单位，也指城镇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86166, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“市”（shì）指行政区划单位或城镇。"}, {"text": "四", "is_correct": false, "explanation": "声母不同：sì 与 shì 的区别在于 s 与 sh，“四”是数字。"}, {"text": "十", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）声调不同，“十”是数字。"}, {"text": "失", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shì（第四声）声调不同，“失”意思是失去。"}, {"text": "史", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“史”意思是历史。"}], "explanations": {"市": "正确答案。“市”（shì）指行政区划单位或城镇。", "四": "声母不同：sì 与 shì 的区别在于 s 与 sh，“四”是数字。", "十": "声调不同：shí（第二声）与 shì（第四声）声调不同，“十”是数字。", "失": "声调不同：shī（第一声）与 shì（第四声）声调不同，“失”意思是失去。", "史": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“史”意思是历史。"}, "sentence_index": null, "correct_answer": "市"}, "level_3": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“我们市的春天来得很早”中，“市”指所在的城市，是唯一符合语境的选项。"}, {"text": "人", "is_correct": false, "explanation": "语义：“人”指人，不是地区，“我们人的春天”不能表示所在的地方。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”指书籍，不能与“春天来得很早”组成表示地点的修饰语。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“歌”不能用作“春天”的所属地点，与“我们”的修饰关系不搭配。"}], "explanations": {"市": "正确答案。“我们市的春天来得很早”中，“市”指所在的城市，是唯一符合语境的选项。", "人": "语义：“人”指人，不是地区，“我们人的春天”不能表示所在的地方。", "书": "语义：“书”指书籍，不能与“春天来得很早”组成表示地点的修饰语。", "歌": "搭配：“歌”不能用作“春天”的所属地点，与“我们”的修饰关系不搭配。"}, "sentence_index": 0, "correct_answer": "市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一本市，很厚。", "explanation": "量词误用：“本”用于书籍，不能计量“市”，应用“座”或“个”。"}, {"text": "我们有一棵市，人口很多。", "explanation": "量词误用：“棵”只用于植物，“市”应用“座”或“个”计量，不能说“一棵市”。"}, {"text": "这把市很大。", "explanation": "量词误用：“把”用于椅子、伞等物品，不能计量“市”，应用“座”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86166, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“市”（shì）指行政区划单位或城镇。"}, {"text": "时", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）声调不同，“时”意思是时间。"}, {"text": "石", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）声调不同，“石”意思是石头。"}, {"text": "使", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“使”意思是使用或让。"}, {"text": "寺", "is_correct": false, "explanation": "声母不同：sì 与 shì 的区别在于 s 与 sh，“寺”意思是寺庙。"}], "explanations": {"市": "正确答案。“市”（shì）指行政区划单位或城镇。", "时": "声调不同：shí（第二声）与 shì（第四声）声调不同，“时”意思是时间。", "石": "声调不同：shí（第二声）与 shì（第四声）声调不同，“石”意思是石头。", "使": "声调不同：shǐ（第三声）与 shì（第四声）声调不同，“使”意思是使用或让。", "寺": "声母不同：sì 与 shì 的区别在于 s 与 sh，“寺”意思是寺庙。"}, "sentence_index": null, "correct_answer": "市"}, "level_3": {"options": [{"text": "市", "is_correct": true, "explanation": "正确答案。“他从小就住在我们市”中，“市”指居住的城市，是唯一符合语境的选项。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”不是可以从小一直居住的地方，“从小就住在我们车”不成立。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“住在……”需要地点，“饭”不能作处所。"}, {"text": "手", "is_correct": false, "explanation": "语义：“手”不是地方，“住在我们手”说不通。"}], "explanations": {"市": "正确答案。“他从小就住在我们市”中，“市”指居住的城市，是唯一符合语境的选项。", "车": "语义：“车”不是可以从小一直居住的地方，“从小就住在我们车”不成立。", "饭": "搭配：“住在……”需要地点，“饭”不能作处所。", "手": "语义：“手”不是地方，“住在我们手”说不通。"}, "sentence_index": 6, "correct_answer": "市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张市很热闹。", "explanation": "量词误用：“张”用于纸、桌子等平面的东西，不能计量“市”，应用“个”。"}, {"text": "这盏市很大。", "explanation": "量词误用：“盏”用于灯，不能计量“市”，应用“座”或“个”。"}, {"text": "这台市很干净。", "explanation": "量词误用：“台”用于机器、电器等，不能计量“市”，应用“座”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本市的人口越来越多。", "corrected_sentence": "这个市的人口越来越多。", "error_description": "量词错误：“本”用于书籍，不能计量“市”，应用“个”。正确形式是“这个市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个市们的人很热情。", "corrected_sentence": "那个市的人很热情。", "error_description": "“市”后加复数后缀“们”是错误：“们”一般只加在指人的名词后，“市”是地方名词，不能加“们”，应说“那个市的人很热情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86167, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "反义：“缺席”与“出席”相对，指应当到场而没有到场。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与“出席”既非近义也非反义。"}, {"text": "发表", "is_correct": false, "explanation": "“发表”指公开表达意见或作品，与“出席”既非近义也非反义。"}, {"text": "准备", "is_correct": false, "explanation": "“准备”指事先做好安排，与“出席”既非近义也非反义。"}], "correct_answer": "缺席", "explanations": {"缺席": "反义：“缺席”与“出席”相对，指应当到场而没有到场。", "讨论": "“讨论”指交换意见，与“出席”既非近义也非反义。", "发表": "“发表”指公开表达意见或作品，与“出席”既非近义也非反义。", "准备": "“准备”指事先做好安排，与“出席”既非近义也非反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86167, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "反义：“缺席”与“出席”相对，指应当到场而没有到场。"}, {"text": "游玩", "is_correct": false, "explanation": "“游玩”指玩耍娱乐，与“出席”既非近义也非反义。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指用脑子考虑问题，与“出席”既非近义也非反义。"}, {"text": "解释", "is_correct": false, "explanation": "“解释”指说明事情的道理，与“出席”既非近义也非反义。"}], "correct_answer": "缺席", "explanations": {"缺席": "反义：“缺席”与“出席”相对，指应当到场而没有到场。", "游玩": "“游玩”指玩耍娱乐，与“出席”既非近义也非反义。", "思考": "“思考”指用脑子考虑问题，与“出席”既非近义也非反义。", "解释": "“解释”指说明事情的道理，与“出席”既非近义也非反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86167, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人到会议或活动现场参加。", "primary_collocate": null, "pronunciation": "chū xí", "ipa": "tʂʰu˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "明天的会你出席吗？", "target_word": "出席", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我下午要出席一个会议。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天出席了朋友的婚礼。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长也出席了今天的会。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈没有出席孩子的毕业典礼。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请大家准时出席会议。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病了，不能出席明天的晚会。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我出席过很多次这样的会议。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理很忙，没能出席这次会议。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着新西服出席了孩子的生日会。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出席了", "label": "体标：了"}, {"form": "出席过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "人到场，坐在会议或活动现场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出席", "is_correct": true, "explanation": "正确。“出席”指人到场参加会议，与“明天的会”相符。"}, {"text": "出游", "is_correct": false, "explanation": "语义：“出游”指外出游玩，与正式的会议不相符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行，不能用于人参加会议。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”表示降生，不能用于参加会议的人。"}], "explanations": {"出席": "正确。“出席”指人到场参加会议，与“明天的会”相符。", "出游": "语义：“出游”指外出游玩，与正式的会议不相符。", "出版": "语义：“出版”指印刷发行，不能用于人参加会议。", "出生": "搭配：“出生”表示降生，不能用于参加会议的人。"}, "sentence_index": 0, "correct_answer": "出席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们上午出席了数学考试。", "explanation": "这里应该用〈参加〉。出席用于会议、典礼等活动，考试要说“参加考试”。"}, {"text": "这份文件出席了会议。", "explanation": "这里应该用〈提交给〉。出席的主语须是人，文件应“提交给”会议。"}, {"text": "他出席了火车站。", "explanation": "这里应该用〈到〉。出席的宾语应是会议、典礼等活动，表示到达某处要用〈到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出席", "is_correct": true, "explanation": "正确。“出席”指人到场参加活动，与“不能……晚会”的语境相符。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖出，不能用于参加晚会。"}, {"text": "出访", "is_correct": false, "explanation": "搭配：“出访”指赴外国访问，不与“晚会”搭配。"}, {"text": "出租", "is_correct": false, "explanation": "语义：“出租”指把东西租给别人，与参加晚会无关。"}], "explanations": {"出席": "正确。“出席”指人到场参加活动，与“不能……晚会”的语境相符。", "出售": "语义：“出售”指卖出，不能用于参加晚会。", "出访": "搭配：“出访”指赴外国访问，不与“晚会”搭配。", "出租": "语义：“出租”指把东西租给别人，与参加晚会无关。"}, "sentence_index": 6, "correct_answer": "出席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出席了我的朋友，一起吃了饭。", "explanation": "这里应该用〈见〉。出席的宾语是会议、典礼，见朋友要用〈见〉。"}, {"text": "他出席了这个俱乐部。", "explanation": "这里应该用〈加入〉。出席指参加会议或典礼，不能用于加入组织。"}, {"text": "他出席了昨天一整天。", "explanation": "这里应该用〈度过〉。出席的宾语是活动，不能是时间，“度过一整天”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
