INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加会议或典礼等活动。", "primary_collocate": null, "pronunciation": "chū xí", "ipa": "tʂʰu˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "王校长出席了开学典礼。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班同学都出席了毕业典礼。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师们都出席了家长会。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长将出席明天的开幕式。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请您准时出席下午的会议。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总统出席了国庆晚会。", "target_word": "出席", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出席这次会议，并发了言。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来开会的人很多，经理也出席了。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，没有出席这次活动。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的领导人将出席明天的签字仪式。", "target_word": "出席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出席了", "label": "体标：了"}, {"form": "出席过", "label": "体标：过"}], "register": "正式", "sense_fingerprint": "以成员或来宾身份参加会议、典礼等正式活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出席", "is_correct": true, "explanation": "正确。“出席”指以身份到场参加典礼，与“开学典礼”相符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行，不能用于人参加典礼。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：“出生”表示降生，不能用于参加典礼的人。"}, {"text": "出租", "is_correct": false, "explanation": "语义：“出租”指把东西租给别人，与参加典礼无关。"}], "explanations": {"出席": "正确。“出席”指以身份到场参加典礼，与“开学典礼”相符。", "出版": "语义：“出版”指印刷发行，不能用于人参加典礼。", "出生": "搭配：“出生”表示降生，不能用于参加典礼的人。", "出租": "语义：“出租”指把东西租给别人，与参加典礼无关。"}, "sentence_index": 0, "correct_answer": "出席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们都出席了期末考试。", "explanation": "这里应该用〈参加〉。出席用于会议、典礼等活动，考试要说“参加考试”。"}, {"text": "校长昨天出席了北京。", "explanation": "这里应该用〈到〉。出席的宾语应是会议、典礼等活动，表示到达某地要用〈到〉。"}, {"text": "这台电脑将出席明天的开幕式。", "explanation": "这里应该用〈展示〉。出席的主语须是人，电脑只能被展示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出席", "is_correct": true, "explanation": "正确。“出席”指以身份到场参加会议，与“这次会议”并“发了言”相符。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”指卖出，与会议和发言无关。"}, {"text": "出访", "is_correct": false, "explanation": "搭配：“出访”指赴外国访问，不与“这次会议”搭配。"}, {"text": "出游", "is_correct": false, "explanation": "语义：“出游”指外出游玩，与开会发言不相符。"}], "explanations": {"出席": "正确。“出席”指以身份到场参加会议，与“这次会议”并“发了言”相符。", "出售": "语义：“出售”指卖出，与会议和发言无关。", "出访": "搭配：“出访”指赴外国访问，不与“这次会议”搭配。", "出游": "语义：“出游”指外出游玩，与开会发言不相符。"}, "sentence_index": 6, "correct_answer": "出席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年出席了这个协会。", "explanation": "这里应该用〈加入〉。出席用于会议、典礼，不能用于加入组织。"}, {"text": "校长出席了我的父母。", "explanation": "这里应该用〈见〉。出席的宾语应是会议、典礼等活动，见人要用〈见〉。"}, {"text": "校长出席了去年一整年。", "explanation": "这里应该用〈度过〉。出席的宾语是活动，不能是时间，“度过一整年”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
