INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86169, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“正在”是说这件事现在正做着。", "primary_collocate": null, "pronunciation": "zhèng zài", "ipa": "ʈʂɤŋ˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "你别吵，弟弟正在睡觉。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在写作业，不能出去玩。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在讨论明天的计划。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打电话的时候，我正在洗澡。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王正在往这里走，马上就到。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在给病人检查身体。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在听音乐，没听到你叫她。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在招人，你可以去试试。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在我们正在等一位朋友。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正在画一只小狗。", "target_word": "正在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正", "label": "省略式"}, {"form": "正在……呢", "label": "句末加呢"}], "register": "中性", "sense_fingerprint": "正在：说这件事现在正做着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86169, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正在", "is_correct": true, "explanation": "正在：表示此刻正在进行，与“睡觉”以及“你别吵”的现场语境相符。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去，与“你别吵”所要求的当下安静情境不符。"}, {"text": "还没", "is_correct": false, "explanation": "语义：“还没”表示尚未发生，与“你别吵”所依据的弟弟已在睡觉的情况相矛盾。"}, {"text": "逐渐", "is_correct": false, "explanation": "语义：“逐渐”表示渐变，与要求对方立即安静的语境不相合。"}], "explanations": {"正在": "正在：表示此刻正在进行，与“睡觉”以及“你别吵”的现场语境相符。", "曾经": "语义：“曾经”指过去，与“你别吵”所要求的当下安静情境不符。", "还没": "语义：“还没”表示尚未发生，与“你别吵”所依据的弟弟已在睡觉的情况相矛盾。", "逐渐": "语义：“逐渐”表示渐变，与要求对方立即安静的语境不相合。"}, "sentence_index": 0, "correct_answer": "正在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我正在知道这件事。", "explanation": "“正在”表示动作进行，不能与“知道”这类表示认知状态的动词连用，应说“我知道这件事”。"}, {"text": "我正在昨天去北京。", "explanation": "“正在”指此刻进行的动作，不能与“昨天”这类过去时间词连用，应说“我昨天去了北京”。"}, {"text": "我正在会开车。", "explanation": "这里不能用〈正在〉。“正在”表示动作正在进行，不能用来说明一个人具备的能力，应说“我会开车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正在", "is_correct": true, "explanation": "正在：表示动作此刻正在进行，与“听音乐”以及“没听到你叫她”的专注状态相符。"}, {"text": "即将", "is_correct": false, "explanation": "语义：“即将”指将要发生，与“没听到你叫她”这一已经出现的情况相矛盾。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”属书面语，与句中口语化的叙述语体不协调。"}, {"text": "逐步", "is_correct": false, "explanation": "语义：“逐步”表示分阶段渐进，与“听音乐、没听到叫声”这种即时状态不符。"}], "explanations": {"正在": "正在：表示动作此刻正在进行，与“听音乐”以及“没听到你叫她”的专注状态相符。", "即将": "语义：“即将”指将要发生，与“没听到你叫她”这一已经出现的情况相矛盾。", "业已": "语域：“业已”属书面语，与句中口语化的叙述语体不协调。", "逐步": "语义：“逐步”表示分阶段渐进，与“听音乐、没听到叫声”这种即时状态不符。"}, "sentence_index": 6, "correct_answer": "正在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我正在昨天买了这本书。", "explanation": "“正在”表示此刻进行，不能与“昨天”这类过去时间词连用，应说“我昨天买了这本书”。"}, {"text": "这双鞋正在合适。", "explanation": "这里应该用〈正好〉。表示“恰好合适”时用“正好”，“正在”只表示动作或变化的进行，不能用来形容鞋子合适。"}, {"text": "他正在是老师。", "explanation": "“正在”表示动作进行，不能用于“是”字判断句，应直接说“他是老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表哥正在在修车。", "corrected_sentence": "表哥正在修车。", "error_description": "错误：“正在”后面多加了一个“在”，写成了“正在在”。正确形式是“正在修车”，“正在”本身已含“在”，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷正在打过太极拳。", "corrected_sentence": "爷爷正在打太极拳。", "error_description": "错误：“正在”后面接了表示经历的“过”，写成了“正在打过”。“正在”表示动作正在进行，“过”表示曾经做过，二者冲突。应去掉“过”，说“爷爷正在打太极拳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
