INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古人；以前的人。", "primary_collocate": null, "pronunciation": "qián rén", "ipa": "tɕʰjɛn˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "前人说过，路是走出来的。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前人用石头做工具。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该尊敬前人。", "target_word": "前人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "前人没有电灯，晚上用油灯。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首诗是前人写给朋友的。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前人的办法有时候也很好用。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，前人的智慧值得我们学习。", "target_word": "前人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前人怎么过节，我们也怎么过。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里放着前人用过的东西。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前人看着月亮，写下了很多诗。", "target_word": "前人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "古人，过去时代的人，常与今人、后人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：古人，过去时代的人，是本题要辨认的词。"}, {"text": "前任", "is_correct": false, "explanation": "qián rèn：rèn 为第四声，与 rén 第二声声调不同，意思是职位上的前一任。"}, {"text": "千人", "is_correct": false, "explanation": "qiān rén：qiān 为第一声，与 qián 第二声声调不同，意思是一千个人。"}, {"text": "强人", "is_correct": false, "explanation": "qiáng rén：qiáng 与 qián 韵母不同（ang 与 an），意思是强有力的人。"}, {"text": "闲人", "is_correct": false, "explanation": "xián rén：xián 与 qián 声母不同（x 与 q），意思是没有事情做的人。"}], "explanations": {"前人": "前人：古人，过去时代的人，是本题要辨认的词。", "前任": "qián rèn：rèn 为第四声，与 rén 第二声声调不同，意思是职位上的前一任。", "千人": "qiān rén：qiān 为第一声，与 qián 第二声声调不同，意思是一千个人。", "强人": "qiáng rén：qiáng 与 qián 韵母不同（ang 与 an），意思是强有力的人。", "闲人": "xián rén：xián 与 qián 声母不同（x 与 q），意思是没有事情做的人。"}, "sentence_index": null, "correct_answer": "前人"}, "level_3": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：古人，这句是流传下来的道理，句中“说过”的主体应是前代的人。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”是乘车、船的人，不会说这种道理。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指生病的人，这句是古代流传下来的道理，说话的应是前代的人。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不会说话，不能说房子说过道理。"}], "explanations": {"前人": "前人：古人，这句是流传下来的道理，句中“说过”的主体应是前代的人。", "乘客": "语义：“乘客”是乘车、船的人，不会说这种道理。", "病人": "语义：“病人”指生病的人，这句是古代流传下来的道理，说话的应是前代的人。", "房子": "语义：“房子”不会说话，不能说房子说过道理。"}, "sentence_index": 0, "correct_answer": "前人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的前人今天上午来我家做客了。", "explanation": "这里应该用〈朋友〉。前人指古代或过去时代的人，不会今天来我家做客。"}, {"text": "楼上的前人经常弹钢琴。", "explanation": "这里应该用〈邻居〉。前人指古代的人，住在隔壁或楼上的人要用“邻居”。"}, {"text": "前人每天开车送我上班。", "explanation": "这里应该用〈司机〉。前人指古代的人，每天开车工作的人要用“司机”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前人", "is_correct": true, "explanation": "前人：古人，其智慧值得学习，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有智慧，不能说石头的智慧。"}, {"text": "门", "is_correct": false, "explanation": "搭配：“智慧”一般不与“门”搭配。"}, {"text": "工具", "is_correct": false, "explanation": "语义：“工具”本身没有智慧，不能说工具的智慧值得学习。"}], "explanations": {"前人": "前人：古人，其智慧值得学习，符合句意。", "石头": "语义：“石头”没有智慧，不能说石头的智慧。", "门": "搭配：“智慧”一般不与“门”搭配。", "工具": "语义：“工具”本身没有智慧，不能说工具的智慧值得学习。"}, "sentence_index": 6, "correct_answer": "前人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的前人今天上午去超市买菜了。", "explanation": "这里应该用〈邻居〉。前人指古代或过去时代的人，不会今天去超市买菜。"}, {"text": "教室里的前人在认真听讲。", "explanation": "这里应该用〈学生〉。前人指古代的人，在教室里听课的人要用“学生”。"}, {"text": "医院里的前人在输液。", "explanation": "这里应该用〈病人〉。前人指古代的人，在医院输液的人要用“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只前人写的诗很有名。", "corrected_sentence": "这位前人写的诗很有名。", "error_description": "“这只前人”量词错误：前人指人，应用“位”，不能用“只”，应为“这位前人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该在前人学习。", "corrected_sentence": "我们应该向前人学习。", "error_description": "“在前人学习”介词错误：表示学习的对象要用“向”，不能用“在”，应为“向前人学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
