INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86173, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“一下”是说做一会儿，或者很快做一次。", "primary_collocate": null, "pronunciation": "yí xià", "ipa": "i˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "他敲了一下门。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑了一下。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他点了一下头。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在这里坐一下就走。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他拍了一下我的肩。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈摸了一下孩子的头。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯闪了一下，又亮了。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了一下手表，说该走了。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我睡一下，十分钟后叫我。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他轻轻碰了一下桌子，杯子就倒了。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一下子", "label": "复合"}], "register": "口语", "sense_fingerprint": "动作很快做一次，或做一小会儿：敲一下、坐一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一下", "is_correct": true, "explanation": "正确答案：一下（yí xià），表示动作很快做一次或做一小会儿。"}, {"text": "以下", "is_correct": false, "explanation": "yǐxià（第三声）与 yíxià（第二声）声调不同，意思是以下、下面。"}, {"text": "一向", "is_correct": false, "explanation": "xiàng 与 xià 韵母不同（ang 与 a），意思是一直、一向。"}, {"text": "一线", "is_correct": false, "explanation": "xiàn 与 xià 韵母不同（an 与 a），意思是一条线、一线希望。"}, {"text": "一笑", "is_correct": false, "explanation": "xiào 与 xià 韵母不同（ao 与 ia），意思是笑一下。"}], "explanations": {"一下": "正确答案：一下（yí xià），表示动作很快做一次或做一小会儿。", "以下": "yǐxià（第三声）与 yíxià（第二声）声调不同，意思是以下、下面。", "一向": "xiàng 与 xià 韵母不同（ang 与 a），意思是一直、一向。", "一线": "xiàn 与 xià 韵母不同（an 与 a），意思是一条线、一线希望。", "一笑": "xiào 与 xià 韵母不同（ao 与 ia），意思是笑一下。"}, "sentence_index": null, "correct_answer": "一下"}, "level_3": {"options": [{"text": "一下", "is_correct": true, "explanation": "“他敲了”后接“一下门”，表示用手轻轻敲一次，只有“一下”合适。"}, {"text": "一趟", "is_correct": false, "explanation": "搭配：“趟”指往返来去的动作，“敲一趟门”不能成立。"}, {"text": "一场", "is_correct": false, "explanation": "搭配：“场”用于比赛、演出等活动，不用于敲门。"}, {"text": "一番", "is_correct": false, "explanation": "语义：“一番”指一番努力或经过，不表示轻敲一次。"}], "explanations": {"一下": "“他敲了”后接“一下门”，表示用手轻轻敲一次，只有“一下”合适。", "一趟": "搭配：“趟”指往返来去的动作，“敲一趟门”不能成立。", "一场": "搭配：“场”用于比赛、演出等活动，不用于敲门。", "一番": "语义：“一番”指一番努力或经过，不表示轻敲一次。"}, "sentence_index": 0, "correct_answer": "一下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃过一下这种水果。", "explanation": "这里应该用〈一次〉。“吃过”表示有过的经历，“一下”表示短时或尝试，不能用于经历。"}, {"text": "我在这里坐了一下三个小时就走。", "explanation": "“一下”表示时间很短，与“三个小时”的长时间矛盾，这里不能用“一下”。"}, {"text": "他一下看了十次报纸。", "explanation": "这里应该用〈一共〉。“一下”表示动作时间短或一次，不能用于多次的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一下", "is_correct": true, "explanation": "“灯闪了”后接“一下”，表示瞬间闪动一次，只有“一下”合适。"}, {"text": "一遍", "is_correct": false, "explanation": "搭配：“遍”表示从头到尾完整做一次，灯闪不用此量词。"}, {"text": "一圈", "is_correct": false, "explanation": "搭配：“圈”指环绕一周的动作，不用于灯闪。"}, {"text": "一口", "is_correct": false, "explanation": "搭配：“口”用于嘴的动作（如“喝一口”），不用于灯的闪动。"}], "explanations": {"一下": "“灯闪了”后接“一下”，表示瞬间闪动一次，只有“一下”合适。", "一遍": "搭配：“遍”表示从头到尾完整做一次，灯闪不用此量词。", "一圈": "搭配：“圈”指环绕一周的动作，不用于灯闪。", "一口": "搭配：“口”用于嘴的动作（如“喝一口”），不用于灯的闪动。"}, "sentence_index": 6, "correct_answer": "一下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一下交了十次作业。", "explanation": "这里应该用〈一共〉。“一下”表示动作时间短或一次，不能用于多个数量。"}, {"text": "他一下碰了桌子一个小时。", "explanation": "“一下”表示动作时间很短，与“一个小时”的长时间矛盾，这里不能用“一下”。"}, {"text": "他轻轻一下碰了桌子三次，杯子就倒了。", "explanation": "“一下”表示一次，与“三次”的次数矛盾，这里不能用“一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他按了一下了铃。", "corrected_sentence": "他按了一下铃。", "error_description": "错误：“按了一下了铃”。正确：“按了一下铃”。“了”已用在“按”后，不能在“一下”后再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹碰了一下的门。", "corrected_sentence": "妹妹碰了一下门。", "error_description": "错误：“一下”是动量词，修饰动词“碰”，后面的名词“门”前不能加“的”，应说“碰了一下门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
