INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86174, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示动作时间短或尝试。", "primary_collocate": null, "pronunciation": "yí xià", "ipa": "i˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "请你等一下。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我看一下。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "让我想一下。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以介绍一下自己吗？", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们休息一下吧。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请帮我看一下这个句子。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你先试一下这件衣服。", "target_word": "一下", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想问一下，这里有人吗？", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我们先复习一下昨天的课。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起讨论一下这个问题吧。", "target_word": "一下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一下子", "label": "复合"}], "register": "口语", "sense_fingerprint": "动词后，表示短时或尝试：等一下、看一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53b78f9d-f217-4af1-8d7e-8b11ddac9746') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一下", "is_correct": true, "explanation": "正确答案：一下（yí xià），表示动作时间短或尝试。"}, {"text": "以下", "is_correct": false, "explanation": "yǐxià（第三声）与 yíxià（第二声）声调不同，意思是以下、下面。"}, {"text": "一向", "is_correct": false, "explanation": "xiàng 与 xià 韵母不同（ang 与 a），意思是一直、一向。"}, {"text": "一线", "is_correct": false, "explanation": "xiàn 与 xià 韵母不同（an 与 a），意思是一条线、一线希望。"}, {"text": "一笑", "is_correct": false, "explanation": "xiào 与 xià 韵母不同（ao 与 ia），意思是笑一下。"}], "explanations": {"一下": "正确答案：一下（yí xià），表示动作时间短或尝试。", "以下": "yǐxià（第三声）与 yíxià（第二声）声调不同，意思是以下、下面。", "一向": "xiàng 与 xià 韵母不同（ang 与 a），意思是一直、一向。", "一线": "xiàn 与 xià 韵母不同（an 与 a），意思是一条线、一线希望。", "一笑": "xiào 与 xià 韵母不同（ao 与 ia），意思是笑一下。"}, "sentence_index": null, "correct_answer": "一下"}, "level_3": {"options": [{"text": "一下", "is_correct": true, "explanation": "“请你等”后接“一下”，表示稍微等一会儿，语气委婉，只有“一下”合适。"}, {"text": "一次", "is_correct": false, "explanation": "语义：“一次”只表示次数，不表示短时或委婉的语气。"}, {"text": "一遍", "is_correct": false, "explanation": "搭配：“遍”表示从头到尾完整做一次，“等一遍”不搭配。"}, {"text": "一趟", "is_correct": false, "explanation": "搭配：“趟”用于往返来去的动作，“等一趟”不搭配。"}], "explanations": {"一下": "“请你等”后接“一下”，表示稍微等一会儿，语气委婉，只有“一下”合适。", "一次": "语义：“一次”只表示次数，不表示短时或委婉的语气。", "一遍": "搭配：“遍”表示从头到尾完整做一次，“等一遍”不搭配。", "一趟": "搭配：“趟”用于往返来去的动作，“等一趟”不搭配。"}, "sentence_index": 0, "correct_answer": "一下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去过一下北京。", "explanation": "这里应该用〈一次〉。“去过”表示有过的经历，“一下”表示短时或尝试，不能用于经历。"}, {"text": "你可以介绍一下自己三个小时吗？", "explanation": "“一下”表示时间很短，与“三个小时”的长时间矛盾，这里不能用“一下”。"}, {"text": "他一下参加了十次比赛。", "explanation": "这里应该用〈一共〉。“一下”表示动作时间短或一次，不能用于多次的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一下", "is_correct": true, "explanation": "“你先试”后接“一下这件衣服”，表示试一试，只有“一下”合适。"}, {"text": "一口", "is_correct": false, "explanation": "搭配：“口”用于嘴的动作（如“喝一口”），不用于试穿衣服。"}, {"text": "一场", "is_correct": false, "explanation": "搭配：“场”用于比赛、演出等活动，不用于试穿衣服。"}, {"text": "一个", "is_correct": false, "explanation": "搭配：“个”不能修饰“这件衣服”，此处需用“件”。"}], "explanations": {"一下": "“你先试”后接“一下这件衣服”，表示试一试，只有“一下”合适。", "一口": "搭配：“口”用于嘴的动作（如“喝一口”），不用于试穿衣服。", "一场": "搭配：“场”用于比赛、演出等活动，不用于试穿衣服。", "一个": "搭配：“个”不能修饰“这件衣服”，此处需用“件”。"}, "sentence_index": 6, "correct_answer": "一下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一下讨论了十次这个问题。", "explanation": "这里应该用〈一共〉。“一下”表示动作时间短或一次，不能用于很多个数量。"}, {"text": "我们一下讨论了三天这个问题。", "explanation": "“一下”表示时间很短，与“三天”的长时间矛盾，这里不能用“一下”。"}, {"text": "我很喜欢一下这件事。", "explanation": "“一下”表示动作短时或尝试，不能用在“喜欢”这种表示心理状态的词后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你看一下了这份报告。", "corrected_sentence": "请你看一下这份报告。", "error_description": "错误：“看一下了这份报告”。正确：“看一下这份报告”。“一下”后面不能直接加“了”，这里是请求句，不用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们试试一下这个方法吧。", "corrected_sentence": "我们试一下这个方法吧。", "error_description": "错误：“试试一下”。正确：“试一下”。动词重叠和“一下”都表示短时，不能同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19982622-4eaa-4bdf-924f-bf0b3883e97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。"}, {"text": "中午", "is_correct": false, "explanation": "无关：“中午”是时段名称，与“将来”没有反义关系。"}, {"text": "晚上", "is_correct": false, "explanation": "无关：“晚上”是时段名称，不是反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "无关：“早晨”是时段名称，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。", "中午": "无关：“中午”是时段名称，与“将来”没有反义关系。", "晚上": "无关：“晚上”是时段名称，不是反义词。", "早晨": "无关：“早晨”是时段名称，与“将来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。"}, {"text": "白天", "is_correct": false, "explanation": "无关：“白天”是时段名称，与“将来”没有反义关系。"}, {"text": "凌晨", "is_correct": false, "explanation": "无关：“凌晨”是时段名称，不是反义词。"}, {"text": "黎明", "is_correct": false, "explanation": "无关：“黎明”是时段名称，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "反义：“过去”与“将来”相对，是“以后”表示将来这一义项的反义词。", "白天": "无关：“白天”是时段名称，与“将来”没有反义关系。", "凌晨": "无关：“凌晨”是时段名称，不是反义词。", "黎明": "无关：“黎明”是时段名称，与“将来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“以后”指从现在往后的时间，即将来。", "primary_collocate": null, "pronunciation": "yǐ hòu", "ipa": "i˨˩˦ xou̯˥˩", "syllable_count": 2, "sentences": [{"text": "以后我每天早上跑步。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你以后别再迟到了。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后有问题，可以问我。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我以后想当医生。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在先别说，以后再告诉你。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说以后不会再抽烟了。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事以后再说吧，我现在很忙。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后你来北京，一定要找我。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以后的日子里，我会更努力地学习。", "target_word": "以后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以后每个周末都去看奶奶。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "单独使用，指从现在往后的时间，将来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”表示从现在往后，放在句首作时间状语，句意通顺。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：“夜里”与“每天早上”时间相互矛盾，不能同作时间状语。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”与“每天早上跑步”的时间相互矛盾。"}, {"text": "翌日", "is_correct": false, "explanation": "语域：“翌日”是书面语，与口语化的句子语域不合，且与“每天”冲突。"}], "explanations": {"以后": "正确：“以后”表示从现在往后，放在句首作时间状语，句意通顺。", "夜里": "语义：“夜里”与“每天早上”时间相互矛盾，不能同作时间状语。", "下午": "语义：“下午”与“每天早上跑步”的时间相互矛盾。", "翌日": "语域：“翌日”是书面语，与口语化的句子语域不合，且与“每天”冲突。"}, "sentence_index": 0, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我以后去过上海，那时候还很小。", "explanation": "这里应该用〈以前〉。“以后”指将来，不能和“去过”“那时候”这样的过去经历一起用，应说“以前”。"}, {"text": "他以后是老师，现在已经退休了。", "explanation": "这里应该用〈以前〉。“以后”指将来，而“现在已经退休”说明当老师是过去的事，应说“以前”。"}, {"text": "我以后住在农村，现在住在城里。", "explanation": "这里应该用〈以前〉。“以后”指将来，与“现在住在城里”对比的应是过去，应说“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”表示从现在往后，句意是“这件事以后再说”，通顺。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，与“再说吧”的将来含义相冲突。"}, {"text": "当时", "is_correct": false, "explanation": "语义：“当时”指过去的某一刻，与句中的“现在很忙”相冲突。"}, {"text": "上个月", "is_correct": false, "explanation": "语义：“上个月”指过去，与“再说吧”的将来含义和“现在很忙”的语境相冲突。"}], "explanations": {"以后": "正确：“以后”表示从现在往后，句意是“这件事以后再说”，通顺。", "昨天": "语义：“昨天”指过去，与“再说吧”的将来含义相冲突。", "当时": "语义：“当时”指过去的某一刻，与句中的“现在很忙”相冲突。", "上个月": "语义：“上个月”指过去，与“再说吧”的将来含义和“现在很忙”的语境相冲突。"}, "sentence_index": 6, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以后曾经住在上海。", "explanation": "这里应该用〈以前〉。“以后”指将来，不能和“曾经住过”这种过去的经历一起用，说过去要用“以前”。"}, {"text": "我以后很害怕狗，现在不怕了。", "explanation": "这里应该用〈以前〉。“以后”指将来，与“现在不怕了”对比的应是过去，应说“以前”。"}, {"text": "我以后在这家公司工作过两年。", "explanation": "这里应该用〈以前〉。“以后”指将来，不能和表示过去经历的“工作过”一起用，应说“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以后了每天下午散步。", "corrected_sentence": "我以后每天下午散步。", "error_description": "“以后”是时间名词，不能带“了”，应说“我以后每天下午散步”；错误在于目标词后多加了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "之以后有空，我们一起吃饭。", "corrected_sentence": "以后有空，我们一起吃饭。", "error_description": "句首的“以后”前面不能加“之”，应为“以后有空”；错误在于目标词前多出了“之”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
