INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指某一时间或动作之后的时间。", "primary_collocate": null, "pronunciation": "yǐ hòu", "ipa": "i˨˩˦ xou̯˥˩", "syllable_count": 2, "sentences": [{"text": "下课以后，我们去吃饭。", "target_word": "以后", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "三年以后，这里会有一条地铁。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到家以后，请给我打电话。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业以后，在北京工作了两年。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃了晚饭以后，我常常出去走走。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我到了公司以后才发现，忘带手机了。", "target_word": "以后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，路上的人一下子少了。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡着以后，妈妈才开始做自己的事。", "target_word": "以后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以后，他每天都练习写汉字。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开完会以后，大家一起去了咖啡店。", "target_word": "以后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以後", "label": "繁体"}], "register": "中性", "sense_fingerprint": "放在某个动作或时间后面，指那个时间之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”指下课之后，符合先下课、再去吃饭的先后顺序。"}, {"text": "以上", "is_correct": false, "explanation": "搭配：“以上”多接数量或范围，“下课以上”说不通。"}, {"text": "以来", "is_correct": false, "explanation": "搭配：“以来”多接“自……以来”，表示持续到现在，不用于一次性的“下课”之后。"}, {"text": "以内", "is_correct": false, "explanation": "搭配：“以内”前面要接数量或时段，不能接“下课”这样的事件。"}], "explanations": {"以后": "正确：“以后”指下课之后，符合先下课、再去吃饭的先后顺序。", "以上": "搭配：“以上”多接数量或范围，“下课以上”说不通。", "以来": "搭配：“以来”多接“自……以来”，表示持续到现在，不用于一次性的“下课”之后。", "以内": "搭配：“以内”前面要接数量或时段，不能接“下课”这样的事件。"}, "sentence_index": 0, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门以后要关灯。", "explanation": "这里应该用〈以前〉。“以后”指某时之后，关灯应在出门之前，此处的时间顺序与“以后”相反。"}, {"text": "出发以后要检查行李。", "explanation": "这里应该用〈之前〉。“以后”指某时之后，检查行李应在出发之前，说“以后”则时间顺序颠倒。"}, {"text": "我以后去过北京。", "explanation": "这里应该用〈以前〉。此句没有参照的时间或动作，“以后”无所指，应说“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以后", "is_correct": true, "explanation": "正确：“以后”指下雨之后，符合先下雨、后人变少的先后关系。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”表示“除了……之外”，与句中的因果和先后关系不合。"}, {"text": "以上", "is_correct": false, "explanation": "搭配：“以上”多接数量或范围，“下雨以上”说不通。"}, {"text": "以下", "is_correct": false, "explanation": "语义：“以下”表示位置在……之下，与“下雨之后人少了”的时间先后不符。"}], "explanations": {"以后": "正确：“以后”指下雨之后，符合先下雨、后人变少的先后关系。", "以外": "语义：“以外”表示“除了……之外”，与句中的因果和先后关系不合。", "以上": "搭配：“以上”多接数量或范围，“下雨以上”说不通。", "以下": "语义：“以下”表示位置在……之下，与“下雨之后人少了”的时间先后不符。"}, "sentence_index": 6, "correct_answer": "以后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去咖啡店以后，先吃了晚饭。", "explanation": "这里应该用〈以前〉。“以后”表示某时之后，句中“先吃了晚饭”与“去咖啡店以后”的先后顺序矛盾，应说“以前”。"}, {"text": "进咖啡店以后，我们在门外等了朋友十分钟。", "explanation": "这里应该用〈以前〉。“在门外等”发生在进店之前，用“以后”时间顺序颠倒，应说“以前”。"}, {"text": "他以后来过这家咖啡店。", "explanation": "这里应该用〈以前〉。此句没有参照的时间或动作，“以后”无所指，应说“以前”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃完午饭以后了，我们去图书馆。", "corrected_sentence": "吃完午饭以后，我们去图书馆。", "error_description": "“以后”后面不能直接加“了”，应为“吃完午饭以后，我们去图书馆”；错误在于目标词“以后”后多出了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下班之以后，我们一起吃晚饭。", "corrected_sentence": "下班以后，我们一起吃晚饭。", "error_description": "“以后”前面不能加“之”，应为“下班以后”；错误在于目标词“以后”前多出了“之”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
