INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "势力是一群人手里有的力量和地位。", "primary_collocate": null, "pronunciation": "shì lì", "ipa": "ʂɨ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个家族在城里很有势力。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠家里的势力找到了工作。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板的势力很大，没有人敢说话。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个大家族的势力一直很大。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有钱有势力，很多人怕他。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里有两股势力，常常吵架。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人没有势力，也没有朋友。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想用自己的势力帮朋友。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去，这位老人在村里很有势力。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人的势力差不多，谁也不让谁。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勢力", "label": "繁体"}, {"form": "势力范围", "label": "复合词"}, {"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "抽象名词：一群人拥有的力量和地位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86177, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "势力", "is_correct": true, "explanation": "正确答案：势力（shì lì），指一群人手里有的力量和地位。"}, {"text": "事理", "is_correct": false, "explanation": "声调不同：事理是 shìlǐ（第二字为第三声），势力是 shìlì（第二字为第四声），意思是道理。"}, {"text": "失礼", "is_correct": false, "explanation": "声调不同：失礼是 shīlǐ，第一、二音节声调都与势力不同，意思是不礼貌。"}, {"text": "市里", "is_correct": false, "explanation": "声调不同：市里是 shìlǐ，第二个音节为第三声，意思是城市里面。"}, {"text": "十里", "is_correct": false, "explanation": "声调不同：十里是 shílǐ，两个音节声调都与势力不同，意思是十里路程。"}], "explanations": {"势力": "正确答案：势力（shì lì），指一群人手里有的力量和地位。", "事理": "声调不同：事理是 shìlǐ（第二字为第三声），势力是 shìlì（第二字为第四声），意思是道理。", "失礼": "声调不同：失礼是 shīlǐ，第一、二音节声调都与势力不同，意思是不礼貌。", "市里": "声调不同：市里是 shìlǐ，第二个音节为第三声，意思是城市里面。", "十里": "声调不同：十里是 shílǐ，两个音节声调都与势力不同，意思是十里路程。"}, "sentence_index": null, "correct_answer": "势力"}, "level_3": {"options": [{"text": "势力", "is_correct": true, "explanation": "正确答案：势力。句意是这个家族在城里有力量和地位，势力指一群人的力量。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的温度，“很有体温”不成立，与句意无关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，“很有身高”不能表示家族的地位。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：长度一般说“长”或“短”，不说“很有长度”。"}], "explanations": {"势力": "正确答案：势力。句意是这个家族在城里有力量和地位，势力指一群人的力量。", "体温": "语义：体温指身体的温度，“很有体温”不成立，与句意无关。", "身高": "语义：身高指身体的高矮，“很有身高”不能表示家族的地位。", "长度": "搭配：长度一般说“长”或“短”，不说“很有长度”。"}, "sentence_index": 0, "correct_answer": "势力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完马拉松，势力已经耗尽了。", "explanation": "这里应该用〈体力〉。势力指群体的力量，不能指人的体力，说跑步后的力气要用体力。"}, {"text": "他搬起那箱书，全靠势力。", "explanation": "这里应该用〈力气〉。势力不能用来指人的体力或力气，搬东西靠的是力气。"}, {"text": "他工作起来很有势力，从早忙到晚。", "explanation": "这里应该用〈精力〉。势力指群体的力量和地位，不能用来说一个人工作时的活力，说精力充沛要用精力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "势力", "is_correct": true, "explanation": "正确答案：势力。句意是那个人没有力量和地位，也没有朋友，势力指一个人或一群人的力量。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄表示岁数，与“没有力量和地位”的句意不合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度表示冷热程度，不能用来说一个人没有力量和地位。"}, {"text": "食量", "is_correct": false, "explanation": "搭配：食量一般说“大”或“小”，不说“没有食量”。"}], "explanations": {"势力": "正确答案：势力。句意是那个人没有力量和地位，也没有朋友，势力指一个人或一群人的力量。", "年龄": "语义：年龄表示岁数，与“没有力量和地位”的句意不合。", "温度": "语义：温度表示冷热程度，不能用来说一个人没有力量和地位。", "食量": "搭配：食量一般说“大”或“小”，不说“没有食量”。"}, "sentence_index": 6, "correct_answer": "势力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的势力很紧张，大家都很担心。", "explanation": "这里应该用〈形势〉。势力指某方的力量，不能说“势力很紧张”，说比赛的情况要用形势。"}, {"text": "他发烧了，势力很高，得去看医生。", "explanation": "这里应该用〈体温〉。势力不能用来说身体的温度高低，说发烧的温度要用体温。"}, {"text": "会场的势力很热烈，大家都很兴奋。", "explanation": "这里应该用〈气氛〉。势力指力量，不能用来形容场面热烈，说气氛热烈要用气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的势力扩大了到邻村。", "corrected_sentence": "他们的势力扩大到了邻村。", "error_description": "“到”与“了”的位置错误：“扩大到”是动补结构，“了”应放在补语“到”之后，应说“扩大到了邻村”，不说“扩大了到邻村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想凭借这条势力，扩大地盘。", "corrected_sentence": "他想凭借这股势力，扩大地盘。", "error_description": "量词错误：势力用“股”来数，不能用“条”，应说“这股势力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
