INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政治、经济、军事等方面的力量。", "primary_collocate": null, "pronunciation": "shì lì", "ipa": "ʂɨ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的政治势力越来越大。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家公司的经济势力很强。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个大国都想扩大在这个地区的势力。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，这个国家的军事势力很大。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家大公司想扩大它在东南亚的势力。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区有好几种不同的势力。", "target_word": "势力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战争以后，旧的势力慢慢变小了。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想进入这个市场，但那里已有别人的势力。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家想减少外国势力的影响。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个时代，北方的势力比南方大。", "target_word": "势力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勢力", "label": "繁体"}, {"form": "势力范围", "label": "复合词"}, {"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "抽象名词：政治、经济、军事等方面的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c500fdf8-63d3-43a2-81b5-b65303588367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86178, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "势力", "is_correct": true, "explanation": "正确答案：势力（shì lì），指政治、经济、军事等方面的力量。"}, {"text": "事理", "is_correct": false, "explanation": "声调不同：事理是 shìlǐ（第二字为第三声），势力是 shìlì（第二字为第四声），意思是道理。"}, {"text": "失礼", "is_correct": false, "explanation": "声调不同：失礼是 shīlǐ，第一、二音节声调都与势力不同，意思是不礼貌。"}, {"text": "市里", "is_correct": false, "explanation": "声调不同：市里是 shìlǐ，第二个音节为第三声，意思是城市里面。"}, {"text": "十里", "is_correct": false, "explanation": "声调不同：十里是 shílǐ，两个音节声调都与势力不同，意思是十里路程。"}], "explanations": {"势力": "正确答案：势力（shì lì），指政治、经济、军事等方面的力量。", "事理": "声调不同：事理是 shìlǐ（第二字为第三声），势力是 shìlì（第二字为第四声），意思是道理。", "失礼": "声调不同：失礼是 shīlǐ，第一、二音节声调都与势力不同，意思是不礼貌。", "市里": "声调不同：市里是 shìlǐ，第二个音节为第三声，意思是城市里面。", "十里": "声调不同：十里是 shílǐ，两个音节声调都与势力不同，意思是十里路程。"}, "sentence_index": null, "correct_answer": "势力"}, "level_3": {"options": [{"text": "势力", "is_correct": true, "explanation": "正确答案：势力。句意是这个国家的政治力量越来越大，势力指政治方面的力量。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度表示冷热程度，“政治温度”不成立，与句意无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格表示商品的价值，“政治价格”不能指国家的力量。"}, {"text": "体制", "is_correct": false, "explanation": "搭配：体制不能说“越来越大”，说体制要用改革、完善等。"}], "explanations": {"势力": "正确答案：势力。句意是这个国家的政治力量越来越大，势力指政治方面的力量。", "温度": "语义：温度表示冷热程度，“政治温度”不成立，与句意无关。", "价格": "语义：价格表示商品的价值，“政治价格”不能指国家的力量。", "体制": "搭配：体制不能说“越来越大”，说体制要用改革、完善等。"}, "sentence_index": 0, "correct_answer": "势力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当前的势力很紧张，大家都很担心。", "explanation": "这里应该用〈形势〉。势力指某方的力量，不能说“势力很紧张”，说局面、情况要用形势。"}, {"text": "今天势力很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。势力是力量，不能用来说天气好坏。"}, {"text": "这台机器的势力很强，一天能生产上千个零件。", "explanation": "这里应该用〈功率〉。势力指群体或国家的力量，不能用来说机器的动力，机器的动力强弱要用功率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "势力", "is_correct": true, "explanation": "正确答案：势力。句意是战争以后旧的力量慢慢变小，势力指一方的力量。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色可以变淡，但不说“慢慢变小”，与句中“力量变小”的意思不合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会“变小”，与句中“力量变小”的意思不合。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道一般说“变淡”，不说“慢慢变小”。"}], "explanations": {"势力": "正确答案：势力。句意是战争以后旧的力量慢慢变小，势力指一方的力量。", "颜色": "语义：颜色可以变淡，但不说“慢慢变小”，与句中“力量变小”的意思不合。", "年龄": "语义：年龄不会“变小”，与句中“力量变小”的意思不合。", "味道": "搭配：味道一般说“变淡”，不说“慢慢变小”。"}, "sentence_index": 6, "correct_answer": "势力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他解题全靠势力，不靠运气。", "explanation": "这里应该用〈脑力〉。势力指群体或国家的力量，不能指智力，说靠智力要用脑力。"}, {"text": "今年的势力很高，大家都热得难受。", "explanation": "这里应该用〈气温〉。势力不能用来说温度高低，说天气冷热要用气温。"}, {"text": "会场的势力很热烈，大家都很兴奋。", "explanation": "这里应该用〈气氛〉。势力指力量，不能用来形容场面热烈，说气氛热烈要用气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的势力扩大了很快。", "corrected_sentence": "这个国家的势力扩大得很快。", "error_description": "错误：“扩大”后应用补语“得”引出程度，说“扩大得很快”，不说“扩大了很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那里出现了一条新势力。", "corrected_sentence": "那里出现了一股新势力。", "error_description": "量词错误：势力用“股”来数，不能用“条”，应说“一股新势力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ad303e-35a0-4892-9428-bbddb50ced1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
