INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "导演是拍电影时，告诉大家怎么演的人。", "primary_collocate": null, "pronunciation": "dǎo yǎn", "ipa": "tɑʊ̯˨˩˦ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "导演告诉演员怎么走路。", "target_word": "导演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影的导演是一位女士。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演让大家再演一次。", "target_word": "导演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想当导演，所以天天看电影。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演在拍电影的时候很认真。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演对演员说：“请笑一笑。”", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我认识一位年轻的导演。", "target_word": "导演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "导演说今天的戏拍完了。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明长大后想做导演。", "target_word": "导演", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "导演把演员叫到桌子前。", "target_word": "导演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副导演", "label": "复合"}, {"form": "導演", "label": "繁体"}], "register": "中性", "sense_fingerprint": "拍电影时指挥演员怎么演的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导演", "is_correct": true, "explanation": "“导演”是拍电影时指导表演的人，符合“导演告诉演员怎么走路”的句意。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”不会说话，不能告诉演员怎么走路。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不负责指导拍摄，“告诉演员怎么走路”与厨师的工作不符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机与表演和拍摄无关，句子说的是指导演员表演。"}], "explanations": {"导演": "“导演”是拍电影时指导表演的人，符合“导演告诉演员怎么走路”的句意。", "椅子": "语义：“椅子”不会说话，不能告诉演员怎么走路。", "厨师": "语义：厨师不负责指导拍摄，“告诉演员怎么走路”与厨师的工作不符。", "司机": "语义：司机与表演和拍摄无关，句子说的是指导演员表演。"}, "sentence_index": 0, "correct_answer": "导演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位导演在医院里给病人做手术。", "explanation": "这里应该用〈医生〉。导演负责指导拍摄，不做手术。"}, {"text": "这位导演在比赛中判定了犯规。", "explanation": "这里应该用〈裁判〉。导演负责指导拍摄，不负责判罚比赛。"}, {"text": "这位导演在银行里负责存款。", "explanation": "这里应该用〈银行职员〉。导演负责指导拍摄，不负责银行业务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导演", "is_correct": true, "explanation": "“导演”是拍电影的指导者，“一位年轻的导演”符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“一位……的”修饰人，“花园”不是人，句子不成立。"}, {"text": "词典", "is_correct": false, "explanation": "语义：“词典”是书，不是人，“一位年轻的词典”不通。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“一位……的”只修饰人，“工厂”不能与“年轻的”搭配。"}], "explanations": {"导演": "“导演”是拍电影的指导者，“一位年轻的导演”符合句意。", "花园": "语义：“一位……的”修饰人，“花园”不是人，句子不成立。", "词典": "语义：“词典”是书，不是人，“一位年轻的词典”不通。", "工厂": "搭配：“一位……的”只修饰人，“工厂”不能与“年轻的”搭配。"}, "sentence_index": 6, "correct_answer": "导演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位导演在法庭上判案。", "explanation": "这里应该用〈法官〉。导演负责指导拍摄，不在法庭上判案。"}, {"text": "这位导演替主角完成了危险动作。", "explanation": "这里应该用〈替身演员〉。导演负责指导拍摄，不替主角做危险动作。"}, {"text": "这位导演在工厂里焊接钢架。", "explanation": "这里应该用〈焊工〉。导演负责指导拍摄，不做焊接工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部纪录片的一座导演很年轻。", "corrected_sentence": "这部纪录片的一位导演很年轻。", "error_description": "错误：量词“座”；正确：“位”。“座”用于山、房屋等大型物体，指人要用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位年轻的导演们很有才华。", "corrected_sentence": "那位年轻的导演很有才华。", "error_description": "错误：“导演”后多加了“们”；正确：去掉“们”。“那位”指一个人，不能和表示复数的“们”同时出现。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
