INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责指导戏剧、电影演出的人。", "primary_collocate": null, "pronunciation": "dǎo yǎn", "ipa": "tɑʊ̯˨˩˦ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这位导演拍过很多好电影。", "target_word": "导演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话剧的导演在舞台上给演员讲戏。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的导演得了大奖。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演选了一个新演员。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场演出的导演是他的老师。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演要求每个演员都记住台词。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众很喜欢这位导演的新电影。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演看着演员，一直没有说话。", "target_word": "导演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是电影学院的老师，也是导演。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好导演会让演员演得更自然。", "target_word": "导演", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副导演", "label": "复合"}, {"form": "導演", "label": "繁体"}], "register": "中性", "sense_fingerprint": "负责指导戏剧、电影演出的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5929168-3d77-4b29-8202-61f2e45ccbc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导演", "is_correct": true, "explanation": "“导演”负责拍电影，“这位导演拍过很多好电影”符合句意。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不拍电影，“拍过很多好电影”与厨师的职业不符。"}, {"text": "邮递员", "is_correct": false, "explanation": "语义：邮递员负责送信，不拍电影，句子说的是拍电影的人。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不拍电影，句子说的是拍电影的人。"}], "explanations": {"导演": "“导演”负责拍电影，“这位导演拍过很多好电影”符合句意。", "厨师": "语义：厨师不拍电影，“拍过很多好电影”与厨师的职业不符。", "邮递员": "语义：邮递员负责送信，不拍电影，句子说的是拍电影的人。", "农民": "语义：农民不拍电影，句子说的是拍电影的人。"}, "sentence_index": 0, "correct_answer": "导演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位导演在建筑工地上砌墙。", "explanation": "这里应该用〈泥瓦工〉。导演负责指导演出，不做砌墙工作。"}, {"text": "这位导演给演员化妆。", "explanation": "这里应该用〈化妆师〉。导演负责指导拍摄，不负责给演员化妆。"}, {"text": "这位导演在医院里给病人看病。", "explanation": "这里应该用〈医生〉。导演负责指导演出，不负责给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导演", "is_correct": true, "explanation": "“导演”是电影的制作者，“观众很喜欢这位导演的新电影”符合句意。"}, {"text": "售票员", "is_correct": false, "explanation": "语义：售票员不拍新电影，句子说的是导演的作品。"}, {"text": "服务员", "is_correct": false, "explanation": "搭配：“……的新电影”要求是电影的制作者，不说“服务员的新电影”。"}, {"text": "饲养员", "is_correct": false, "explanation": "语义：饲养员与电影无关，句子说的是拍电影的人。"}], "explanations": {"导演": "“导演”是电影的制作者，“观众很喜欢这位导演的新电影”符合句意。", "售票员": "语义：售票员不拍新电影，句子说的是导演的作品。", "服务员": "搭配：“……的新电影”要求是电影的制作者，不说“服务员的新电影”。", "饲养员": "语义：饲养员与电影无关，句子说的是拍电影的人。"}, "sentence_index": 6, "correct_answer": "导演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位导演在电影里替主角完成了危险动作。", "explanation": "这里应该用〈替身演员〉。导演负责指导拍摄，不替主角做危险动作。"}, {"text": "这位导演在剧场门口负责检票。", "explanation": "这里应该用〈检票员〉。导演负责指导演出，不负责检票。"}, {"text": "这位导演在超市里负责收银。", "explanation": "这里应该用〈收银员〉。导演负责指导演出，不负责收银。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部导演的新戏很受欢迎。", "corrected_sentence": "这位导演的新戏很受欢迎。", "error_description": "错误：量词“部”；正确：“位”。“部”用于作品，指人要用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老导演们很有才华。", "corrected_sentence": "那位老导演很有才华。", "error_description": "错误：“导演”后多加了“们”；正确：去掉“们”。“那位”指一个人，不能和表示复数的“们”同时出现。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf63402e-b0a6-4bb5-92d4-c4b877c967f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
