INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86181, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“位”是数人的时候用的字，说得很有礼貌。", "primary_collocate": null, "pronunciation": "wèi", "ipa": "wei˥˩", "syllable_count": 1, "sentences": [{"text": "请问，你们一共几位？", "target_word": "位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那三位客人想要一张大桌子。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭馆里来了五位客人。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两位先生，这边请。", "target_word": "位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司有三位新同事。", "target_word": "位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位老师教了我们三年汉语。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天来了很多客人，一共有二十位。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家来了四位客人，妈妈忙着做饭。", "target_word": "位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女士想要一杯热茶。", "target_word": "位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请问，那位穿红衣服的先生是谁？", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "各位", "label": "复合词"}], "register": "礼貌", "sense_fingerprint": "位：数人时用的礼貌量词（几位、三位）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86181, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "位", "is_correct": true, "explanation": "位是数人时用的礼貌量词，读 wèi（第四声）。"}, {"text": "外", "is_correct": false, "explanation": "wài（第四声）与 wèi（第四声）韵母不同（ai 与 ei），意思是外面。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是尾巴。"}, {"text": "威", "is_correct": false, "explanation": "wēi（第一声）与 wèi（第四声）声调不同，意思是威力。"}, {"text": "围", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是包围。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wèi（第四声）韵母不同（en 与 ei），意思是提问。"}], "explanations": {"位": "位是数人时用的礼貌量词，读 wèi（第四声）。", "外": "wài（第四声）与 wèi（第四声）韵母不同（ai 与 ei），意思是外面。", "尾": "wěi（第三声）与 wèi（第四声）声调不同，意思是尾巴。", "威": "wēi（第一声）与 wèi（第四声）声调不同，意思是威力。", "围": "wéi（第二声）与 wèi（第四声）声调不同，意思是包围。", "问": "wèn（第四声）与 wèi（第四声）韵母不同（en 与 ei），意思是提问。"}, "sentence_index": null, "correct_answer": "位"}, "level_3": {"options": [{"text": "位", "is_correct": true, "explanation": "“位”是数人的礼貌量词，与“你们”相符，可以填入空格。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”多用于动物，不用于数人。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”只用于车，不能用来数人。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”多用于纸、桌子等平面的东西，不能用来数“你们”这样的人。"}], "explanations": {"位": "“位”是数人的礼貌量词，与“你们”相符，可以填入空格。", "只": "语义：“只”多用于动物，不用于数人。", "辆": "语义：“辆”只用于车，不能用来数人。", "张": "搭配：“张”多用于纸、桌子等平面的东西，不能用来数“你们”这样的人。"}, "sentence_index": 0, "correct_answer": "位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一位书。", "explanation": "这里应该用〈本〉。“位”只用于人，书要用“本”。"}, {"text": "教室里有一位桌子。", "explanation": "这里应该用〈张〉。“位”只用于人，桌子要用“张”。"}, {"text": "门口跑来一位小猫。", "explanation": "这里应该用〈只〉。“位”只用于人，小猫要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET