INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86182, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于人，表示尊敬。", "primary_collocate": null, "pronunciation": "wèi", "ipa": "wei˥˩", "syllable_count": 1, "sentences": [{"text": "门口站着一位老人。", "target_word": "位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位很有名的医生。", "target_word": "位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天有一位老师来我家看我。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生很好，对病人很耐心。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很尊敬这位帮助过我的老师。", "target_word": "位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上，一位专家介绍了新的方法。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老奶奶每天早上都在公园里散步。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长请那位老教授先发言。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我最尊敬的一位老师。", "target_word": "位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，您是哪一位？", "target_word": "位", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "各位", "label": "复合词"}], "register": "礼貌", "sense_fingerprint": "位：用于受尊敬的人的量词（一位老师、一位专家）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86182, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "位", "is_correct": true, "explanation": "位是用于受尊敬的人的量词，读 wèi（第四声）。"}, {"text": "外", "is_correct": false, "explanation": "wài（第四声）与 wèi（第四声）韵母不同（ai 与 ei），意思是外面。"}, {"text": "伟", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是伟大。"}, {"text": "威", "is_correct": false, "explanation": "wēi（第一声）与 wèi（第四声）声调不同，意思是威力。"}, {"text": "为", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是为了。"}, {"text": "问", "is_correct": false, "explanation": "wèn（第四声）与 wèi（第四声）韵母不同（en 与 ei），意思是提问。"}], "explanations": {"位": "位是用于受尊敬的人的量词，读 wèi（第四声）。", "外": "wài（第四声）与 wèi（第四声）韵母不同（ai 与 ei），意思是外面。", "伟": "wěi（第三声）与 wèi（第四声）声调不同，意思是伟大。", "威": "wēi（第一声）与 wèi（第四声）声调不同，意思是威力。", "为": "wéi（第二声）与 wèi（第四声）声调不同，意思是为了。", "问": "wèn（第四声）与 wèi（第四声）韵母不同（en 与 ei），意思是提问。"}, "sentence_index": null, "correct_answer": "位"}, "level_3": {"options": [{"text": "位", "is_correct": true, "explanation": "“位”是用于受尊敬的人的量词，与“老人”相符，可以填入空格。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”多用于动物，不用于老人。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”多用于长条形的东西，不能用来数老人。"}, {"text": "头", "is_correct": false, "explanation": "语义：“头”多用于牲畜，不能用来数老人。"}], "explanations": {"位": "“位”是用于受尊敬的人的量词，与“老人”相符，可以填入空格。", "只": "语义：“只”多用于动物，不用于老人。", "条": "搭配：“条”多用于长条形的东西，不能用来数老人。", "头": "语义：“头”多用于牲畜，不能用来数老人。"}, "sentence_index": 0, "correct_answer": "位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口停着一位汽车。", "explanation": "这里应该用〈辆〉。“位”用于受尊敬的人，汽车要用“辆”。"}, {"text": "他买了一位椅子。", "explanation": "这里应该用〈把〉。“位”用于受尊敬的人，椅子要用“把”。"}, {"text": "村口有一位房子。", "explanation": "这里应该用〈座〉。“位”用于受尊敬的人，房子要用“座”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86182, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "位", "is_correct": true, "explanation": "位是用于受尊敬的人的量词，读 wèi（第四声）。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是尾巴。"}, {"text": "围", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是包围。"}, {"text": "微", "is_correct": false, "explanation": "wēi（第一声）与 wèi（第四声）声调不同，意思是微小。"}, {"text": "危", "is_correct": false, "explanation": "wēi（第一声）与 wèi（第四声）声调不同，意思是危险。"}, {"text": "违", "is_correct": false, "explanation": "wéi（第二声）与 wèi（第四声）声调不同，意思是违反。"}], "explanations": {"位": "位是用于受尊敬的人的量词，读 wèi（第四声）。", "尾": "wěi（第三声）与 wèi（第四声）声调不同，意思是尾巴。", "围": "wéi（第二声）与 wèi（第四声）声调不同，意思是包围。", "微": "wēi（第一声）与 wèi（第四声）声调不同，意思是微小。", "危": "wēi（第一声）与 wèi（第四声）声调不同，意思是危险。", "违": "wéi（第二声）与 wèi（第四声）声调不同，意思是违反。"}, "sentence_index": null, "correct_answer": "位"}, "level_3": {"options": [{"text": "位", "is_correct": true, "explanation": "“位”是用于受尊敬的人的量词，与“老奶奶”相符，可以填入空格。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”只用于车，不能用来数老奶奶。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”多用于平面的东西，不能用来数老奶奶。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”多用于山、房屋等大型固定的东西，不能用来数人。"}], "explanations": {"位": "“位”是用于受尊敬的人的量词，与“老奶奶”相符，可以填入空格。", "辆": "语义：“辆”只用于车，不能用来数老奶奶。", "张": "搭配：“张”多用于平面的东西，不能用来数老奶奶。", "座": "语义：“座”多用于山、房屋等大型固定的东西，不能用来数人。"}, "sentence_index": 6, "correct_answer": "位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的位排得很靠前。", "explanation": "这里应该用〈排名〉。“位”不单独表示名次，要说“排名”。"}, {"text": "门口新摆着一位花。", "explanation": "这里应该用〈朵〉。“位”只用于人，花要用“朵”。"}, {"text": "我们学校的位在城市东边。", "explanation": "这里应该用〈位置〉。“位”不单独表示地点，要说“位置”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口站着位一老爷爷。", "corrected_sentence": "门口站着一位老爷爷。", "error_description": "语序错误：数词“一”应放在量词“位”之前，应说“一位”，不能说“位一”。正确：门口站着一位老爷爷。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很敬佩位那老师。", "corrected_sentence": "我很敬佩那位老师。", "error_description": "语序错误：指示词“那”应放在量词“位”之前，应说“那位”，不能说“位那”。正确：我很敬佩那位老师。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
