INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小组是几个人在一起，做同一件事。", "primary_collocate": null, "pronunciation": "xiǎo zǔ", "ipa": "ɕjɑʊ˨˩ tsu˨˩", "syllable_count": 2, "sentences": [{"text": "我们小组有四个人。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把我分到了第三小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组每天一起做作业。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组今天要做一个小实验。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组里的同学都很热情。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和小组的朋友一起打扫教室。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组的人在图书馆等你。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，小组一起讨论问题。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们小组里年纪最小的同学。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们小组正在练习唱歌。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小組", "label": "繁体"}, {"form": "学习小组", "label": "复合"}], "register": "中性", "sense_fingerprint": "几个人在一起做同一件事的一小群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为同一件事而聚在一起的一小群人。"}, {"text": "小虎", "is_correct": false, "explanation": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。"}, {"text": "小鼠", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。"}, {"text": "小暑", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。"}, {"text": "小坐", "is_correct": false, "explanation": "zuò（第四声）与 zǔ（第三声）声母相同，但韵母（uo 与 u）和声调都不同。小坐指坐一会儿，意思不同。"}, {"text": "小赌", "is_correct": false, "explanation": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。"}], "explanations": {"小组": "正确答案。小组指为同一件事而聚在一起的一小群人。", "小虎": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。", "小鼠": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。", "小暑": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。", "小坐": "zuò（第四声）与 zǔ（第三声）声母相同，但韵母（uo 与 u）和声调都不同。小坐指坐一会儿，意思不同。", "小赌": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“我们”之后指人的集体，并且可以说“有四个人”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是人的集体，不能说“我们手机有四个人”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指一个人的体形，不能指一群人，“我们身材有四个人”说不通。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子是语言单位，没有人数，不能说“我们句子有四个人”。"}], "explanations": {"小组": "正确答案。“我们”之后指人的集体，并且可以说“有四个人”。", "手机": "语义：手机是电子设备，不是人的集体，不能说“我们手机有四个人”。", "身材": "体貌：身材指一个人的体形，不能指一群人，“我们身材有四个人”说不通。", "句子": "语义：句子是语言单位，没有人数，不能说“我们句子有四个人”。"}, "sentence_index": 0, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的小组很重，一个人搬不动。", "explanation": "这里应该用〈物体〉。小组是一群人，不是有重量、能被搬动的东西，说它“很重”是错的。"}, {"text": "我们国家的小组有一亿人。", "explanation": "这里应该用〈群体〉。小组指几个人一起做事的小集体，一亿人的群体不能叫小组。"}, {"text": "他把小组放进了书包。", "explanation": "这里应该用〈物品〉。小组是一群人，不是可以装进书包的东西，把它当成〈物品〉来放是错的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为同一件事而聚在一起的一小群人。"}, {"text": "小卒", "is_correct": false, "explanation": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。"}, {"text": "小补", "is_correct": false, "explanation": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。"}, {"text": "小主", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。"}, {"text": "小渚", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}], "explanations": {"小组": "正确答案。小组指为同一件事而聚在一起的一小群人。", "小卒": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。", "小补": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。", "小主": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。", "小渚": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“我们”和“的人”之间需要一个人群的名称。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是人群，“我们课本的人”说不通。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是书面谦称，指自己的住所，不能指一群人。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的颜色，不能指一群人，“我们脸色的人”说不通。"}], "explanations": {"小组": "正确答案。“我们”和“的人”之间需要一个人群的名称。", "课本": "语义：课本是书，不是人群，“我们课本的人”说不通。", "寒舍": "语域：“寒舍”是书面谦称，指自己的住所，不能指一群人。", "脸色": "体貌：脸色指面部的颜色，不能指一群人，“我们脸色的人”说不通。"}, "sentence_index": 6, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她们小组昨天结婚了。", "explanation": "这里应该用〈个人〉。小组是为同一件事聚在一起的一群人，结婚的是个人，不能说“小组结婚”。"}, {"text": "她们小组是一家餐厅。", "explanation": "这里把〈营业场所〉的意思用到了小组上。小组是为同一件事而组成的一群人，不是经营的店铺，不能说成餐厅。"}, {"text": "她们小组是一把椅子。", "explanation": "这里把〈家具〉的意思用到了小组上。小组是一群人，不是可以坐的物品，不能说成“一把椅子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班分成了好几只小组。", "corrected_sentence": "我们班分成了好几个小组。", "error_description": "错误形式：好几只小组；正确形式：好几个小组。“小组”是人的集体，计量词要用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校里有三条小组在比赛。", "corrected_sentence": "学校里有三个小组在比赛。", "error_description": "错误形式：三条小组；正确形式：三个小组。“条”用于细长的东西，“小组”是人的集体，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为工作、学习而组成的少数人的集体。", "primary_collocate": null, "pronunciation": "xiǎo zǔ", "ipa": "ɕjɑʊ˨˩ tsu˨˩", "syllable_count": 2, "sentences": [{"text": "公司成立了一个新小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学习小组里认识了很多朋友。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的任务是研究新产品。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理让我加入项目小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组每周开一次会。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在数学小组工作了三年。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的成员都是老师。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师组织了一个读书小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组今天要交报告。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想退出这个小组。", "target_word": "小组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小組", "label": "繁体"}, {"form": "项目小组", "label": "复合"}], "register": "中性", "sense_fingerprint": "为工作或学习而组成的少数人的集体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为工作或学习而组成的少数人的集体。"}, {"text": "小虎", "is_correct": false, "explanation": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。"}, {"text": "小鼠", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。"}, {"text": "小暑", "is_correct": false, "explanation": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。"}, {"text": "小赌", "is_correct": false, "explanation": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。"}, {"text": "小坐", "is_correct": false, "explanation": "zuò（第四声）与 zǔ（第三声）声母相同，但韵母（uo 与 u）和声调都不同。小坐指坐一会儿，意思不同。"}], "explanations": {"小组": "正确答案。小组指为工作或学习而组成的少数人的集体。", "小虎": "hǔ（第三声）与 zǔ 声调相同，声母不同（h 与 z），小虎指小老虎。", "小鼠": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小鼠指老鼠。", "小暑": "shǔ（第三声）与 zǔ 声调相同，声母不同（sh 与 z），小暑是二十四节气之一。", "小赌": "dǔ（第三声）与 zǔ 声调相同，声母不同（d 与 z），小赌指小额赌博。", "小坐": "zuò（第四声）与 zǔ（第三声）声母相同，但韵母（uo 与 u）和声调都不同。小坐指坐一会儿，意思不同。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“成立”后面可以接机构或团体。"}, {"text": "汽水", "is_correct": false, "explanation": "搭配：“成立”搭配机构或团体，不搭配饮料，“成立了一个新汽水”说不通。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子是语言单位，不是机构，不能被成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能被成立。"}], "explanations": {"小组": "正确答案。“成立”后面可以接机构或团体。", "汽水": "搭配：“成立”搭配机构或团体，不搭配饮料，“成立了一个新汽水”说不通。", "句子": "语义：句子是语言单位，不是机构，不能被成立。", "身材": "体貌：身材指人的体形，不能被成立。"}, "sentence_index": 0, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们公司的项目小组有一万人。", "explanation": "这里应该用〈团体〉。小组指少数人为工作组成的集体，一万人的规模不能叫小组。"}, {"text": "经理的小组是项目负责人。", "explanation": "这里应该用〈职位〉。“项目负责人”是职位，小组是人的集体，不能充当职务。"}, {"text": "她把这个小组装进了行李箱。", "explanation": "这里应该用〈物品〉。小组是为工作或学习而组成的一群人，不是可以装进行李箱的东西，把它当成〈物品〉来装是错的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。小组指为工作或学习而组成的少数人的集体。"}, {"text": "小卒", "is_correct": false, "explanation": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。"}, {"text": "小补", "is_correct": false, "explanation": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。"}, {"text": "小主", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。"}, {"text": "小渚", "is_correct": false, "explanation": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}], "explanations": {"小组": "正确答案。小组指为工作或学习而组成的少数人的集体。", "小卒": "zú（第二声）与 zǔ（第三声）只有声调不同，小卒指地位低的士兵，意思不同。", "小补": "bǔ（第三声）与 zǔ 声调相同，声母不同（b 与 z），小补指稍加补益，意思不同。", "小主": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小主是旧时对低位妃嫔的称呼。", "小渚": "zhǔ（第三声）与 zǔ 声调相同，声母不同（zh 与 z），小渚指小块的水中陆地，意思不同。"}, "sentence_index": null, "correct_answer": "小组"}, "level_3": {"options": [{"text": "小组", "is_correct": true, "explanation": "正确答案。“这个”和“的成员”之间需要一个团体的名称。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，没有“成员”，“这个汽车的成员”说不通。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：“寒舍”是书面谦称，指自己的住所，不能指一个团体。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的颜色，不能指团体的成员。"}], "explanations": {"小组": "正确答案。“这个”和“的成员”之间需要一个团体的名称。", "汽车": "语义：汽车是交通工具，没有“成员”，“这个汽车的成员”说不通。", "寒舍": "语域：“寒舍”是书面谦称，指自己的住所，不能指一个团体。", "脸色": "体貌：脸色指面部的颜色，不能指团体的成员。"}, "sentence_index": 6, "correct_answer": "小组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的小组是一本词典。", "explanation": "这里应该用〈物品〉。小组是一群人，不是书，不能说它“是一本词典”，把它当成〈物品〉是错的。"}, {"text": "这个小组的价格很便宜。", "explanation": "这里应该用〈商品〉。小组是为工作或学习而组成的一群人，不是可以标价出售的东西，说它“价格很便宜”是错的。"}, {"text": "这个小组昨天生病了。", "explanation": "这里应该用〈个人〉。生病的是个人，小组是为工作或学习而组成的一群人，不能说“小组生病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司刚成立了一台新小组。", "corrected_sentence": "公司刚成立了一个新小组。", "error_description": "错误形式：一台新小组；正确形式：一个新小组。“小组”是人的集体，计量词要用“个”，“台”用于机器等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块小组的任务很重要。", "corrected_sentence": "这个小组的任务很重要。", "error_description": "错误形式：这块小组；正确形式：这个小组。“块”用于成块的东西，“小组”是人的集体，应该用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
