INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86187, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就要是说马上要发生了。", "primary_collocate": null, "pronunciation": "jiù yào", "ipa": "tɕjoʊ˥˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "火车就要开了，快上车吧。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天就要黑了，我们回家吧。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节就要到了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影就要开始了，请安静。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他就要毕业了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们就要出发了，你准备好了吗？", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳就要下山了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期就要结束了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，天上的云很黑，雨就要下了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹就要过生日了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词，事情马上就要发生，常与句尾的了连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就要", "is_correct": true, "explanation": "正确答案。“就要……了”表示火车马上要开。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚刚发生，与“快上车吧”的意思矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的事，与“快上车吧”的意思矛盾。"}, {"text": "业已", "is_correct": false, "explanation": "语义：“业已”表示已经，与“就要”的将要相反，“火车业已开了”说的是已经发生。"}], "explanations": {"就要": "正确答案。“就要……了”表示火车马上要开。", "刚": "语义：“刚”表示刚刚发生，与“快上车吧”的意思矛盾。", "曾经": "语义：“曾经”指过去的事，与“快上车吧”的意思矛盾。", "业已": "语义：“业已”表示已经，与“就要”的将要相反，“火车业已开了”说的是已经发生。"}, "sentence_index": 0, "correct_answer": "就要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小时候就要毕业了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“小时候”已经过去，不能用“就要”。"}, {"text": "昨天的比赛就要结束了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“昨天”的比赛已经过去，不能用“就要”。"}, {"text": "电影已经演完了，现在就要开始了。", "explanation": "这里应该用〈已经发生〉。电影已经演完，不会马上开始，“就要”表示即将发生，与“已经演完了”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就要", "is_correct": true, "explanation": "正确答案。“就要……了”表示太阳马上要落下。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常，与“下山了”这种一次性的变化矛盾。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多个主体，“太阳”只有一个，“太阳一起下山了”说不通。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与“下山了”的完成意思矛盾。"}], "explanations": {"就要": "正确答案。“就要……了”表示太阳马上要落下。", "总是": "语义：“总是”表示经常，与“下山了”这种一次性的变化矛盾。", "一起": "搭配：“一起”需要多个主体，“太阳”只有一个，“太阳一起下山了”说不通。", "永远": "语义：“永远”表示持续不变，与“下山了”的完成意思矛盾。"}, "sentence_index": 6, "correct_answer": "就要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐小时候就要结婚了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“小时候”已经过去，不能用“就要”。"}, {"text": "去年冬天就要下雪了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“去年冬天”已经过去，不能用“就要”。"}, {"text": "她的生日上个月已经过完了，现在就要过生日了。", "explanation": "这里应该用〈已经发生〉。生日已经过完，“就要”表示即将发生，与“已经过完了”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛就要结束着。", "corrected_sentence": "这场比赛就要结束了。", "error_description": "错误形式：这场比赛就要结束着；正确形式：这场比赛就要结束了。“就要”表示即将发生，句末应用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨就要停过。", "corrected_sentence": "雨就要停了。", "error_description": "错误形式：雨就要停过；正确形式：雨就要停了。“就要”表示尚未发生，句末应使用“了”，不能与表示完成的“过”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
