INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86188, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示将要，很快。", "primary_collocate": null, "pronunciation": "jiù yào", "ipa": "tɕjoʊ˥˩ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "飞机就要起飞了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试就要开始了，别说话。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天就要来了，多穿点儿衣服。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们就要见面了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师就要进教室了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们就要结婚了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间就要到了，快写吧。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我就要看完了。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车就要来了，别着急。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子就要睡着了，小声点儿。", "target_word": "就要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "副词，表示将要，很快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da3fe4f3-6505-4386-9195-0de57bfd5131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就要", "is_correct": true, "explanation": "正确答案。“就要……了”表示飞机马上要起飞。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与“起飞了”的完成意思矛盾。"}, {"text": "业已", "is_correct": false, "explanation": "语义：“业已”表示已经，与“就要”的将要相反，“飞机业已起飞了”说的是已经发生。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常，与“起飞了”这种一次性的动作矛盾。"}], "explanations": {"就要": "正确答案。“就要……了”表示飞机马上要起飞。", "永远": "语义：“永远”表示持续不变，与“起飞了”的完成意思矛盾。", "业已": "语义：“业已”表示已经，与“就要”的将要相反，“飞机业已起飞了”说的是已经发生。", "总是": "语义：“总是”表示经常，与“起飞了”这种一次性的动作矛盾。"}, "sentence_index": 0, "correct_answer": "就要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小时候就要见面了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“小时候”已经过去，不能用“就要”。"}, {"text": "上个星期我们就要见面了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“上个星期”已经过去，不能用“就要”。"}, {"text": "他们三岁时就要结婚了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“三岁时”已经过去，不能用“就要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "就要", "is_correct": true, "explanation": "正确答案。“就要……了”表示时间马上要到了。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多个主体，“时间”是单一的，“时间一起到了”说不通。"}, {"text": "尚未", "is_correct": false, "explanation": "语义：“尚未”表示还没有，与“到了”的完成意思矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“到了”这样的变化矛盾，不符合“快写吧”的语境。"}], "explanations": {"就要": "正确答案。“就要……了”表示时间马上要到了。", "一起": "搭配：“一起”需要多个主体，“时间”是单一的，“时间一起到了”说不通。", "尚未": "语义：“尚未”表示还没有，与“到了”的完成意思矛盾。", "一直": "语义：“一直”表示持续，与“到了”这样的变化矛盾，不符合“快写吧”的语境。"}, "sentence_index": 6, "correct_answer": "就要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师已经在教室里上了一个小时课，现在就要进教室了。", "explanation": "这里应该用〈已经发生〉。老师早已在教室里，“就要进教室”表示即将发生，与已发生的事实矛盾。"}, {"text": "上个星期孩子就要睡着了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“上个星期”已经过去，不能用“就要”。"}, {"text": "孩子半年前就要睡着了。", "explanation": "这里应该用〈已经发生〉。“就要”指马上将要发生，“半年前”已经过去，不能用“就要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的会议就要开始过了。", "corrected_sentence": "我们的会议就要开始了。", "error_description": "错误形式：就要开始过了；正确形式：就要开始了。“就要”表示尚未发生，不能与表示完成的“过”连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '480acb91-1753-4985-8468-05637698b89c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
