INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "广播是用声音把话传给很多人听的方式，也指所播送的内容。", "primary_collocate": null, "pronunciation": "guǎng bō", "ipa": "kwɑŋ˨˩˦ pwɔ˥", "syllable_count": 2, "sentences": [{"text": "车站的广播说火车晚点了。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的广播请同学们去操场。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听见广播里在找一个小孩。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场广播说八点的飞机不飞了。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的广播说今天打折。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广播里一直在说同一句话。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到广播，大家都走出了教室。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们听完这段广播。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁里的广播声音很清楚。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广播说，请大家不要站在门口。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "廣播", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用声音把话传给很多人听", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d125fbf-5287-4485-9a68-7d0834fbb130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86189, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会说话，“说火车晚点了”的主语必须能发出声音。"}, {"text": "广播", "is_correct": true, "explanation": "正确：广播能把声音传给很多人，车站的广播可以告知火车晚点的消息。"}, {"text": "站台", "is_correct": false, "explanation": "语义：站台是候车的地方，本身不会说话，与“说火车晚点了”不合。"}, {"text": "信号灯", "is_correct": false, "explanation": "搭配：“说”要求会发声的主语，信号灯只会亮灭，与“说”不搭配。"}], "explanations": {"椅子": "语义：椅子不会说话，“说火车晚点了”的主语必须能发出声音。", "广播": "正确：广播能把声音传给很多人，车站的广播可以告知火车晚点的消息。", "站台": "语义：站台是候车的地方，本身不会说话，与“说火车晚点了”不合。", "信号灯": "搭配：“说”要求会发声的主语，信号灯只会亮灭，与“说”不搭配。"}, "sentence_index": 0, "correct_answer": "广播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是学校的广播，每天早上播报新闻。", "explanation": "这里应该用〈播音员〉。广播指声音传播或播送的内容，不指人；说播报新闻的人要用“播音员”。"}, {"text": "学校在门口贴出一份书面广播。", "explanation": "这里应该用〈通告〉。通告是写在纸上贴出来的，广播靠声音传播，不能说书面的。"}, {"text": "我在信里给朋友写了一段广播。", "explanation": "这里应该用〈话〉。广播是用声音传给很多人听的，不能写在信里给一个朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": false, "explanation": "语义：镜子是用来照的，不发出声音，不可能被“听到”。"}, {"text": "广播", "is_correct": true, "explanation": "正确：广播是通过声音传出的通知，大家听到后才会走出教室。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“听到”要配声音，气味应该说“闻到”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会发出声音，与“听到”和句义都不合。"}], "explanations": {"镜子": "语义：镜子是用来照的，不发出声音，不可能被“听到”。", "广播": "正确：广播是通过声音传出的通知，大家听到后才会走出教室。", "气味": "搭配：“听到”要配声音，气味应该说“闻到”。", "桌子": "语义：桌子是家具，不会发出声音，与“听到”和句义都不合。"}, "sentence_index": 6, "correct_answer": "广播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口贴着一段广播，请大家别在这里停车。", "explanation": "这里应该用〈告示〉。告示是写出来贴在门口的，广播是声音，不能贴。"}, {"text": "他悄悄地广播，只告诉了我一个人。", "explanation": "这里应该用〈说〉。广播是把话传给很多人听，只告诉一个人不能用广播。"}, {"text": "我在书上看到了一段广播。", "explanation": "这里应该用〈文章〉。广播是用声音传播的，只能听，不能在书上看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我听到了一只广播，说明天会停水。", "corrected_sentence": "我听到了一段广播，说明天会停水。", "error_description": "错误：“一只广播”；正确：“一段广播”。播送的一段内容要用量词“段”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站的广播了说明天有雨。", "corrected_sentence": "车站的广播说明天有雨。", "error_description": "错误：「广播了说」，名词「广播」后不能加动态助词「了」。正确说法是「车站的广播说明天有雨」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过无线电波或有线线路传播声音节目。", "primary_collocate": null, "pronunciation": "guǎng bō", "ipa": "kwɑŋ˨˩˦ pwɔ˥", "syllable_count": 2, "sentences": [{"text": "爷爷每天早上都听广播。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个广播节目很有意思。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在车里听着广播回家。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里有音乐，也有新闻。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在广播里讲了一个故事。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多人不听广播，只看手机。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他晚上十点听广播学汉语。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段广播是昨天播的。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的收音机里总有广播。", "target_word": "广播", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢听早上的广播新闻。", "target_word": "广播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "廣播", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通过电波或线路传播的声音节目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d125fbf-5287-4485-9a68-7d0834fbb130') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "搭配：“听”的对象要能发出声音，报纸是用来看的，不说听报纸。"}, {"text": "广播", "is_correct": true, "explanation": "正确：广播指通过声音播送的节目，爷爷每天早上听的就是它。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁不会发声，无法被听，与句中“听”不合。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在脸上的东西，不发声，爷爷不会去听眼镜。"}], "explanations": {"报纸": "搭配：“听”的对象要能发出声音，报纸是用来看的，不说听报纸。", "广播": "正确：广播指通过声音播送的节目，爷爷每天早上听的就是它。", "墙壁": "语义：墙壁不会发声，无法被听，与句中“听”不合。", "眼镜": "语义：眼镜是戴在脸上的东西，不发声，爷爷不会去听眼镜。"}, "sentence_index": 0, "correct_answer": "广播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是电台的广播，每天晚上主持节目。", "explanation": "这里应该用〈主持人〉。广播指节目或播送，不指人；主持节目的人要说“主持人”。"}, {"text": "我每天晚上在电视上看广播。", "explanation": "这里应该用〈电视节目〉。广播是只有声音的节目，是用来听的，不是在电视上看的。"}, {"text": "这张广播很有意思。", "explanation": "量词错误：“张”用于纸、桌子等平面的东西。广播节目应用“段”，这里应该用〈段〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": false, "explanation": "语义：镜子不发声，他无法通过镜子学习汉语。"}, {"text": "广播", "is_correct": true, "explanation": "正确：广播是通过声音播放的节目，他晚上听着它学汉语。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不会说话，不能用来一边听一边学汉语。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“听”要配声音，气味应该说“闻”，不能说听气味学汉语。"}], "explanations": {"镜子": "语义：镜子不发声，他无法通过镜子学习汉语。", "广播": "正确：广播是通过声音播放的节目，他晚上听着它学汉语。", "饭菜": "语义：饭菜不会说话，不能用来一边听一边学汉语。", "气味": "搭配：“听”要配声音，气味应该说“闻”，不能说听气味学汉语。"}, "sentence_index": 6, "correct_answer": "广播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用手机广播一段话，留给妈妈听。", "explanation": "这里应该用〈录音〉。广播是向很多人传播声音，录给一个人留存要用“录音”，与节目义不符。"}, {"text": "这支广播我每天都听。", "explanation": "量词错误：“支”用于歌曲、笔等。广播节目应用“段”，这里应该用〈段〉。"}, {"text": "我和朋友在电话里广播，聊了一个小时。", "explanation": "这里应该用〈通话〉。广播是对很多人讲话，两人之间打电话聊天要用“通话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只广播很有意思，我常听。", "corrected_sentence": "这段广播很有意思，我常听。", "error_description": "错误：“这只广播”；正确：“这段广播”。“只”用于动物或成对的东西，广播节目应用量词“段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上得广播很好听，我常听。", "corrected_sentence": "晚上的广播很好听，我常听。", "error_description": "错误：“晚上得广播很好听”；正确：“晚上的广播很好听”。只改动一处：修饰“广播”的定语标记应为“的”，“得”用于动词后作补语，此处没有动词，应改为“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e113ab40-72ef-4d48-b9a6-c23d40f26edf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
