INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86195, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“次”用来数同一件事做了几回。", "primary_collocate": null, "pronunciation": "cì", "ipa": "tsʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "这首歌我听了五次。", "target_word": "次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一年回家两次。", "target_word": "次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你把这句话读三次。", "target_word": "次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一天刷三次牙。", "target_word": "次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字我写错了两次。", "target_word": "次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在北京只住过一次。", "target_word": "次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫我再试一次。", "target_word": "次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部电影我看过三次，每次都哭。", "target_word": "次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一个月出差两次。", "target_word": "次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你已经问了我三次，我不知道。", "target_word": "次", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "次数", "label": "复合"}, {"form": "每次", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词：数同一动作重复做了几回（听、写、试、读等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86195, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次", "is_correct": true, "explanation": "次：量词，用来数同一件事做了几回（cì）。"}, {"text": "此", "is_correct": false, "explanation": "此 cǐ（第三声）与 cì（第四声）声调不同，意思是“这”，不表示次数。"}, {"text": "词", "is_correct": false, "explanation": "词 cí（第二声）与 cì（第四声）声调不同，意思是词语。"}, {"text": "四", "is_correct": false, "explanation": "四 sì 与 cì 声母不同（s 与 c），意思是数字四。"}, {"text": "是", "is_correct": false, "explanation": "是 shì 与 cì 声母不同（sh 与 c），意思是“是”。"}, {"text": "字", "is_correct": false, "explanation": "字 zì 与 cì 声母不同（z 与 c），意思是文字。"}], "explanations": {"次": "次：量词，用来数同一件事做了几回（cì）。", "此": "此 cǐ（第三声）与 cì（第四声）声调不同，意思是“这”，不表示次数。", "词": "词 cí（第二声）与 cì（第四声）声调不同，意思是词语。", "四": "四 sì 与 cì 声母不同（s 与 c），意思是数字四。", "是": "是 shì 与 cì 声母不同（sh 与 c），意思是“是”。", "字": "字 zì 与 cì 声母不同（z 与 c），意思是文字。"}, "sentence_index": null, "correct_answer": "次"}, "level_3": {"options": [{"text": "次", "is_correct": true, "explanation": "次：量词，计数“听这首歌”这种反复发生的动作。"}, {"text": "下", "is_correct": false, "explanation": "语义：“下”用于短时间内的一次动作，不能表示长期反复听歌的次数。"}, {"text": "通", "is_correct": false, "explanation": "搭配：“通”用于电话、信件等，不能说“听了五通”。"}, {"text": "声", "is_correct": false, "explanation": "语义：“声”指声音或叫声，不用来计数“听”的次数。"}], "explanations": {"次": "次：量词，计数“听这首歌”这种反复发生的动作。", "下": "语义：“下”用于短时间内的一次动作，不能表示长期反复听歌的次数。", "通": "搭配：“通”用于电话、信件等，不能说“听了五通”。", "声": "语义：“声”指声音或叫声，不用来计数“听”的次数。"}, "sentence_index": 0, "correct_answer": "次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子有两次窗户。", "explanation": "这里应该用〈扇〉。“次”只计数动作或事件，窗户是实物，要用“扇”。"}, {"text": "院子里有两次树。", "explanation": "这里应该用〈棵〉。“次”只计数动作或事件，树是实物，要用“棵”。"}, {"text": "我们班有三次同学。", "explanation": "这里应该用〈名〉。“次”只计数动作或事件，同学是人，要用“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86195, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "次", "is_correct": true, "explanation": "次：量词，用来数同一件事做了几回（cì）。"}, {"text": "测", "is_correct": false, "explanation": "测 cè（第四声）与 cì 韵母不同（e 与 i），意思是测量、测试。"}, {"text": "瓷", "is_correct": false, "explanation": "瓷 cí（第二声）与 cì 声调不同，意思是瓷器。"}, {"text": "寺", "is_correct": false, "explanation": "寺 sì 与 cì 声母不同（s 与 c），意思是寺庙。"}, {"text": "自", "is_correct": false, "explanation": "自 zì 与 cì 声母不同（z 与 c），意思是自己。"}], "explanations": {"次": "次：量词，用来数同一件事做了几回（cì）。", "测": "测 cè（第四声）与 cì 韵母不同（e 与 i），意思是测量、测试。", "瓷": "瓷 cí（第二声）与 cì 声调不同，意思是瓷器。", "寺": "寺 sì 与 cì 声母不同（s 与 c），意思是寺庙。", "自": "自 zì 与 cì 声母不同（z 与 c），意思是自己。"}, "sentence_index": null, "correct_answer": "次"}, "level_3": {"options": [{"text": "次", "is_correct": true, "explanation": "次：量词，计数“再试”这一动作的次数。"}, {"text": "团", "is_correct": false, "explanation": "语义：“团”指成团的东西，“再试一团”没有意义。"}, {"text": "抹", "is_correct": false, "explanation": "语义：“抹”指涂抹的量，“再试一抹”说不通。"}, {"text": "幅", "is_correct": false, "explanation": "搭配：“幅”用于字画、布匹等，不能用于“试”。"}], "explanations": {"次": "次：量词，计数“再试”这一动作的次数。", "团": "语义：“团”指成团的东西，“再试一团”没有意义。", "抹": "语义：“抹”指涂抹的量，“再试一抹”说不通。", "幅": "搭配：“幅”用于字画、布匹等，不能用于“试”。"}, "sentence_index": 6, "correct_answer": "次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你这是两次事，别搞混了。", "explanation": "这里应该用〈回〉。“两回事”是固定说法，不说“两次事”。"}, {"text": "这套房子有三次房间。", "explanation": "这里应该用〈间〉。“次”只计数动作或事件，房间要用“间”。"}, {"text": "客厅里有三次沙发。", "explanation": "这里应该用〈张〉。“次”只计数动作或事件，沙发是实物，要用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影我看了一个次。", "corrected_sentence": "这部电影我看了一次。", "error_description": "“次”是量词，前面不能再加“个”。应说“看了一次”，“一个次”是重复了量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我去年跟他吵了次一架。", "corrected_sentence": "我去年跟他吵了一次架。", "error_description": "数词与量词语序颠倒：应为“一次”（数词＋量词），不能说“次一”。改正为“吵了一次架”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86197, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "闲", "is_correct": true, "explanation": "闲：没有事情做，与“忙”相反。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、不模糊，与“忙”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "结实：形容牢固、强壮，与“忙”没有关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：形容好看，与“忙”没有关系。"}], "correct_answer": "闲", "explanations": {"闲": "闲：没有事情做，与“忙”相反。", "清楚": "清楚：形容明白、不模糊，与“忙”没有反义关系。", "结实": "结实：形容牢固、强壮，与“忙”没有关系。", "漂亮": "漂亮：形容好看，与“忙”没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76e947d0-9fe6-4584-890c-3d3c79f35bff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
