INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集团是很多人或很多公司聚在一起做事的大组织。", "primary_collocate": null, "pronunciation": "jí tuán", "ipa": "tɕi˧˥ tʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "这个集团有很多分公司。", "target_word": "集团", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "警察抓到了这个犯罪集团的人。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几个小公司聚成了一个大集团。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个集团专门造汽车，在全国有十家工厂。", "target_word": "集团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个集团里有银行，也有工厂。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一个汽车集团工作了五年。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个集团决定一起建一座新城。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想进那个大集团工作，因为工资高。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个大集团是三家公司一起办的。", "target_word": "集团", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的小公司卖给了一个大集团。", "target_word": "集团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集團", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "家", "label": "量词"}, {"form": "犯罪集团", "label": "复合"}], "register": "中性", "sense_fingerprint": "集团：很多人或公司聚在一起做事的大组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86199, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集团", "is_correct": true, "explanation": "正确：“集团”可以拥有很多分公司。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，没有分公司。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不会有分公司。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“水”是物质名词，不能与“有很多分公司”搭配。"}], "explanations": {"集团": "正确：“集团”可以拥有很多分公司。", "学校": "语义：学校是教育机构，没有分公司。", "石头": "语义：石头是矿物，不会有分公司。", "水": "搭配：“水”是物质名词，不能与“有很多分公司”搭配。"}, "sentence_index": 0, "correct_answer": "集团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们球队是一个大集团，每场比赛都赢。", "explanation": "这里应该用〈团队〉。“集团”指企业或为共同目的组成的大组织，体育队伍不能说“集团”。"}, {"text": "河边有一个鸭子集团，在水里游来游去。", "explanation": "这里应该用〈群〉。“集团”指人或公司组成的组织，动物聚在一起要说“一群鸭子”。"}, {"text": "我们一家人组成了一个大集团，成员都很和睦。", "explanation": "这里应该用〈家庭〉。“集团”指企业或大型组织，一家人要说“家庭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集团", "is_correct": true, "explanation": "正确：“这两个集团”指两个大型组织，可以决定合作建城。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是组织，不会决定建城。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，不能决定建城。"}, {"text": "米", "is_correct": false, "explanation": "搭配：“米”是物质名词，不能说“这两个米”。"}], "explanations": {"集团": "正确：“这两个集团”指两个大型组织，可以决定合作建城。", "厨房": "语义：厨房不是组织，不会决定建城。", "玩具": "语义：玩具是物品，不能决定建城。", "米": "搭配：“米”是物质名词，不能说“这两个米”。"}, "sentence_index": 6, "correct_answer": "集团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我爸爸是一个大集团，每天都很忙。", "explanation": "这里应该用〈人〉。“集团”指组织，不能用来指一个人。"}, {"text": "这个学习小组是一个大集团，大家互相帮助。", "explanation": "这里应该用〈集体〉。“集团”指企业或大型组织，学习小组要说“集体”。"}, {"text": "他的小店只有两个人，却是一个大集团。", "explanation": "这里应该用〈公司〉。“集团”由多家公司联合而成，只有两个人的小店不能叫集团。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们组成了一只集团。", "corrected_sentence": "他们组成了一个集团。", "error_description": "错误：量词用错。“集团”应搭配“个”，不能用“只”（“只”用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一条大集团工作。", "corrected_sentence": "他在一家大集团工作。", "error_description": "错误：“集团”的量词用错。“集团”应搭配“家”或“个”，不能用“条”（条用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
