INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“外”是说不在一个东西的里面，在它的外边。", "primary_collocate": null, "pronunciation": "wài", "ipa": "wai˥˩", "syllable_count": 1, "sentences": [{"text": "他没有进屋，只在门外抽烟。", "target_word": "外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门是关着的，人在门外。", "target_word": "外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外雨很大，屋里很暖和。", "target_word": "外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你别进教室，在教室外等我。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫跑出来了，现在在笼子外。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车外很冷，车里很热。", "target_word": "外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "院子里有花，院子外有树。", "target_word": "外", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他忘了带钥匙，只好站在门外等。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙外有一棵很高的树，墙里是学校。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子里没有水，水都洒在杯子外了。", "target_word": "外", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "外边", "label": "复合"}, {"form": "外面", "label": "复合"}], "register": "中性", "sense_fingerprint": "外：某个东西的外边，与“里”相对；门外、窗外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 杯子 (Zipf 3.82), 洒 (Zipf 3.69), 杯子 (Zipf 3.82)']::text[], 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86203, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“外”（wài）指某个东西的外边，即本题的词。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 wài（第四声）声母不同，意思是“太”（很、过于）。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 wài（第四声）声母不同，意思是“菜”。"}, {"text": "卖", "is_correct": false, "explanation": "mài（第四声）与 wài（第四声）声母不同，意思是“卖”。"}, {"text": "歪", "is_correct": false, "explanation": "wāi（第一声）与 wài（第四声）声调不同，意思是“歪”，不正。"}], "explanations": {"外": "正确：“外”（wài）指某个东西的外边，即本题的词。", "太": "tài（第四声）与 wài（第四声）声母不同，意思是“太”（很、过于）。", "菜": "cài（第四声）与 wài（第四声）声母不同，意思是“菜”。", "卖": "mài（第四声）与 wài（第四声）声母不同，意思是“卖”。", "歪": "wāi（第一声）与 wài（第四声）声调不同，意思是“歪”，不正。"}, "sentence_index": null, "correct_answer": "外"}, "level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“门外”指门的外边，与“没有进屋”相符。"}, {"text": "里", "is_correct": false, "explanation": "语义：“门里”指屋内，与“没有进屋”矛盾。"}, {"text": "上", "is_correct": false, "explanation": "语义：“门上”指门的表面，人不会在门上抽烟。"}, {"text": "中", "is_correct": false, "explanation": "搭配：“门中”不是常用的方位说法，不说“在门中抽烟”。"}], "explanations": {"外": "正确：“门外”指门的外边，与“没有进屋”相符。", "里": "语义：“门里”指屋内，与“没有进屋”矛盾。", "上": "语义：“门上”指门的表面，人不会在门上抽烟。", "中": "搭配：“门中”不是常用的方位说法，不说“在门中抽烟”。"}, "sentence_index": 0, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙放进了包外。", "explanation": "这里应该用〈里〉。“放进”表示放到容器内部，说“包外”意思相反，应说“包里”。"}, {"text": "他把照片塞进了信封外。", "explanation": "这里应该用〈里〉。“塞进”表示放入容器内部，说“信封外”意思相反，应说“信封里”。"}, {"text": "他把牛奶倒进碗外了。", "explanation": "这里应该用〈里〉。“倒进”表示液体流入容器内部，说“碗外”意思相反，应说“碗里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86203, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“外”（wài）指某个东西的外边，即本题的词。"}, {"text": "再", "is_correct": false, "explanation": "zài（第四声）与 wài（第四声）声母不同，意思是“再”（又一次）。"}, {"text": "赛", "is_correct": false, "explanation": "sài（第四声）与 wài（第四声）声母不同，意思是“比赛”。"}, {"text": "派", "is_correct": false, "explanation": "pài（第四声）与 wài（第四声）声母不同，意思是“派别”。"}, {"text": "戴", "is_correct": false, "explanation": "dài（第四声）与 wài（第四声）声母不同，意思是“戴”（把东西套在身上）。"}], "explanations": {"外": "正确：“外”（wài）指某个东西的外边，即本题的词。", "再": "zài（第四声）与 wài（第四声）声母不同，意思是“再”（又一次）。", "赛": "sài（第四声）与 wài（第四声）声母不同，意思是“比赛”。", "派": "pài（第四声）与 wài（第四声）声母不同，意思是“派别”。", "戴": "dài（第四声）与 wài（第四声）声母不同，意思是“戴”（把东西套在身上）。"}, "sentence_index": null, "correct_answer": "外"}, "level_3": {"options": [{"text": "外", "is_correct": true, "explanation": "正确：“院子外”指院子的外边，与前一分句的“院子里”相对。"}, {"text": "上", "is_correct": false, "explanation": "搭配：“院子上”不是表示地点的常用说法。"}, {"text": "的", "is_correct": false, "explanation": "语法：“院子的有树”结构不通，“的”不能直接接动词“有”。"}, {"text": "去", "is_correct": false, "explanation": "语法：“去”是动词，“院子去有树”不成句。"}], "explanations": {"外": "正确：“院子外”指院子的外边，与前一分句的“院子里”相对。", "上": "搭配：“院子上”不是表示地点的常用说法。", "的": "语法：“院子的有树”结构不通，“的”不能直接接动词“有”。", "去": "语法：“去”是动词，“院子去有树”不成句。"}, "sentence_index": 6, "correct_answer": "外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身外穿着一件外套。", "explanation": "这里应该用〈上〉。“穿”表示衣物贴在身体上，要说“身上”，不能说“身外”。"}, {"text": "他把钥匙握在手外。", "explanation": "这里应该用〈中〉。“握”指东西在手掌之中，要说“手中”，不说“手外”。"}, {"text": "他把饼干藏进了抽屉外。", "explanation": "这里应该用〈里〉。“藏进”表示放到容器内部，说“抽屉外”意思相反，应说“抽屉里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他门外等我。", "corrected_sentence": "他在门外等我。", "error_description": "错误：漏掉了介词“在”。“门外”作地点状语时前面要加“在”，应说“他在门外等我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋外里停着一辆自行车。", "corrected_sentence": "屋外停着一辆自行车。", "error_description": "错误：“屋外”已经表示方位，后面不能再加“里”。应说“屋外停着一辆自行车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
