INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成年的女性。", "primary_collocate": null, "pronunciation": "nǚ rén", "ipa": "ny˨˩˦ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "办公室里有三个男人和两个女人。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女人是我们的新老师。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院门口有一个女人在打电话。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女人是一家公司的经理。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女人和男人都应该有自己的工作。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个爱笑的女人，大家都喜欢她。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车上坐着一个抱着孩子的女人。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板是一个四十岁的女人。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女人给我们做了一顿好吃的饭。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个女人走进来，问我们要找谁。", "target_word": "女人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "成年女性，与男人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女人", "is_correct": true, "explanation": "正确：“女人”指成年女性，与“男人”相对，符合句意。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：“两个”是人的量词，动物应说“两只”，不能说“两个狗”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是人，不能与“男人”并列。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：“两个”是人的量词，动物应说“两只”，不能说“两个猫”。"}], "explanations": {"女人": "正确：“女人”指成年女性，与“男人”相对，符合句意。", "狗": "搭配：“两个”是人的量词，动物应说“两只”，不能说“两个狗”。", "桌子": "语义：桌子不是人，不能与“男人”并列。", "猫": "搭配：“两个”是人的量词，动物应说“两只”，不能说“两个猫”。"}, "sentence_index": 0, "correct_answer": "女人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个十二三岁的女人刚进入初中。", "explanation": "这里应该用〈少女〉。“女人”指成年女性，十二三岁的女孩应说“少女”。"}, {"text": "这个三岁的女人很可爱。", "explanation": "这里应该用〈小女孩〉。“女人”指成年女性，三岁的孩子要说“小女孩”。"}, {"text": "这个十岁的女人在操场上踢足球。", "explanation": "这里应该用〈女孩〉。“女人”指成年女性，十岁的孩子要说“女孩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女人", "is_correct": true, "explanation": "正确：“女人”指成年女性，可以坐在车上抱着孩子。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会抱孩子，与“抱着孩子”矛盾。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶不会坐在车上，与“坐着”矛盾。"}, {"text": "树", "is_correct": false, "explanation": "配价：“坐着”的主语应是人或动物，树不能坐在车上。"}], "explanations": {"女人": "正确：“女人”指成年女性，可以坐在车上抱着孩子。", "椅子": "语义：椅子不会抱孩子，与“抱着孩子”矛盾。", "水壶": "语义：水壶不会坐在车上，与“坐着”矛盾。", "树": "配价：“坐着”的主语应是人或动物，树不能坐在车上。"}, "sentence_index": 6, "correct_answer": "女人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校门口站着一个八岁的女人，在等妈妈。", "explanation": "这里应该用〈小女孩〉。“女人”指成年女性，八岁的孩子要说“小女孩”。"}, {"text": "护士抱着刚出生的女人。", "explanation": "这里应该用〈婴儿〉。“女人”指成年女性，刚出生的孩子要说“婴儿”。"}, {"text": "她是我们小学的学生，是个女人。", "explanation": "这里应该用〈女生〉。在校读书的学生说“女生”，“女人”指已成年的女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个女人们在办公室里聊天。", "corrected_sentence": "两个女人在办公室里聊天。", "error_description": "错误：数量词“两个”后面的“女人”不能再加“们”。应说“两个女人”，去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只女人站在门口。", "corrected_sentence": "一个女人站在门口。", "error_description": "错误：“女人”指人，量词应用“个”，不能用“只”。应说“一个女人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
