INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86207, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“成立”是一个新的队伍或学校开始有了。", "primary_collocate": null, "pronunciation": "chéng lì", "ipa": "ʈʂʰɤŋ˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我们学校的足球队成立了。", "target_word": "成立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司是二十年前成立的。", "target_word": "成立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校打算明年成立一个新的音乐班。", "target_word": "成立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新中国是一九四九年成立的。", "target_word": "成立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们几个同学成立了一支小乐队。", "target_word": "成立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里成立了一个读书小组。", "target_word": "成立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个俱乐部成立很久了。", "target_word": "成立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的篮球队什么时候成立的？", "target_word": "成立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们成立了一个小小的画画队。", "target_word": "成立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学成立过一个中文社。", "target_word": "成立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成立了", "label": "体标"}, {"form": "成立过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，队伍、学校、公司等新的组织开始有了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '683cea7f-9faf-4ce5-be29-922b841282d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成立", "is_correct": true, "explanation": "正确。“成立”指足球队这样的新组织开始有了。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”用于冰、雪等，足球队不能融化。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”用于水、资金等，不能说足球队被冻结了。"}, {"text": "熄", "is_correct": false, "explanation": "搭配：“熄”多用于灯、火，不能用于足球队。"}], "explanations": {"成立": "正确。“成立”指足球队这样的新组织开始有了。", "融化": "语义：“融化”用于冰、雪等，足球队不能融化。", "冻结": "语义：“冻结”用于水、资金等，不能说足球队被冻结了。", "熄": "搭配：“熄”多用于灯、火，不能用于足球队。"}, "sentence_index": 0, "correct_answer": "成立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校每年都成立一次运动会。", "explanation": "这里应该用〈举办〉。“成立”指组织、机构开始存在；运动会要说“举办”。"}, {"text": "这座大楼是一九九〇年成立的。", "explanation": "这里应该用〈建成〉。“成立”用于组织、机构；建筑物完工要说“建成”。"}, {"text": "他和朋友成立了很深的友谊。", "explanation": "这里应该用〈建立〉。“成立”用于组织；抽象的关系要说“建立”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成立", "is_correct": true, "explanation": "正确。“成立”指俱乐部这样的组织已经存在，符合“很久了”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能用来说俱乐部。"}, {"text": "发笑", "is_correct": false, "explanation": "语义：俱乐部不会“发笑”，这句话说的是组织的存在时间。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是人生病，俱乐部不会发烧。"}], "explanations": {"成立": "正确。“成立”指俱乐部这样的组织已经存在，符合“很久了”。", "下雨": "语义：“下雨”是天气现象，不能用来说俱乐部。", "发笑": "语义：俱乐部不会“发笑”，这句话说的是组织的存在时间。", "发烧": "语义：“发烧”是人生病，俱乐部不会发烧。"}, "sentence_index": 6, "correct_answer": "成立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校昨天成立了一场开学典礼。", "explanation": "这里应该用〈举行〉。“成立”指组织、机构开始存在；典礼要说“举行”。"}, {"text": "这条生产线去年成立了。", "explanation": "这里应该用〈投产〉。“成立”指组织开始存在；生产线要说“投产”。"}, {"text": "学校成立了一张新证书。", "explanation": "这里应该用〈颁发〉。“成立”指组织开始存在；证书要说“颁发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个社团上个月成立着。", "corrected_sentence": "这个社团上个月成立了。", "error_description": "错误：体标“着”用错了。“成立”是一下子完成的动作，不能用表示持续的“着”；说上个月已经发生的事要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司成立了过一个研究所。", "corrected_sentence": "这家公司成立过一个研究所。", "error_description": "错误：“了”和“过”不能同时用在同一个动词后。“成立过”是正确的，不要再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '158ef2e8-ff9d-4e61-a90c-91f87e5405ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
