INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86209, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86209, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“有为”是说一个人很努力，能做成很多事。", "primary_collocate": null, "pronunciation": "yǒu wéi", "ipa": "jou̯˨˩ wei̯˧˥", "syllable_count": 2, "sentences": [{"text": "他每天努力工作，真是个有为的人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位有为的老板，十年里开了五家店。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要做有为的人，就要先学会坚持。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小林又努力又聪明，将来一定是个有为的人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻有为的小李，今年又拿了第一名。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常对我说，有为的人从不偷懒。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做成了很多事，大家都说他是个有为的人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个有为的学生，一年里写了三本书。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就努力读书，后来成了有为的医生。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事认真又肯吃苦的人，往往能成为有为的人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有為", "label": "繁体"}, {"form": "年轻有为", "label": "复合"}], "register": "书面", "sense_fingerprint": "有为：人努力肯干，能做成很多事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有为", "is_correct": true, "explanation": "有为：形容词，指人努力肯干、能做成很多事，与“每天努力工作”相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“每天努力工作”意思相反，句子的评价无法成立。"}, {"text": "拙劣", "is_correct": false, "explanation": "搭配：“拙劣”多用来形容作品或技艺，不能直接用来修饰人。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”指做事没有精神，与“每天努力工作”矛盾。"}], "explanations": {"有为": "有为：形容词，指人努力肯干、能做成很多事，与“每天努力工作”相符。", "懒惰": "语义：“懒惰”与“每天努力工作”意思相反，句子的评价无法成立。", "拙劣": "搭配：“拙劣”多用来形容作品或技艺，不能直接用来修饰人。", "懒散": "语义：“懒散”指做事没有精神，与“每天努力工作”矛盾。"}, "sentence_index": 0, "correct_answer": "有为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个药很有为，吃了两天就好了。", "explanation": "这里应该用〈有效〉。“有为”形容人的作为，药物起作用要说“有效”。"}, {"text": "他的字写得很有为。", "explanation": "“有为”形容人的作为，不能用来评价字迹，应说“写得很漂亮”。"}, {"text": "这只鹦鹉很有为，会说很多话。", "explanation": "“有为”只用于形容人有作为，不能用来说动物，应改用“很聪明”之类说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有为", "is_correct": true, "explanation": "有为：形容词，指能做成很多事，与“做成了很多事”的评价相符。"}, {"text": "窝囊", "is_correct": false, "explanation": "语义：“窝囊”指无能、受气，与“做成了很多事”大家称赞的语境矛盾。"}, {"text": "平庸", "is_correct": false, "explanation": "语义：“平庸”指不出色，与“做成了很多事”的评价相反。"}, {"text": "寒酸", "is_correct": false, "explanation": "体貌：“寒酸”形容穷困简陋的样子，不能用来评价一个人的成就。"}], "explanations": {"有为": "有为：形容词，指能做成很多事，与“做成了很多事”的评价相符。", "窝囊": "语义：“窝囊”指无能、受气，与“做成了很多事”大家称赞的语境矛盾。", "平庸": "语义：“平庸”指不出色，与“做成了很多事”的评价相反。", "寒酸": "体貌：“寒酸”形容穷困简陋的样子，不能用来评价一个人的成就。"}, "sentence_index": 6, "correct_answer": "有为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老板很有为，每天都在玩游戏。", "explanation": "这里应该用〈有钱〉。“有为”指人的作为，不指财富，形容有钱要说“有钱”。"}, {"text": "这张桌子很有为，用了十年也没坏。", "explanation": "“有为”形容人的作为与出息，不用于形容家具；形容桌子结实应说“结实”。"}, {"text": "有为的早晨，我们去爬山了。", "explanation": "“有为”形容人的作为，不能修饰“早晨”这类时间词，应说“美好的早晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个有为地老师，一年里带了五个班。", "corrected_sentence": "这个有为的老师，一年里带了五个班。", "error_description": "错误：“有为”修饰名词“老师”时应用“的”，写成了“地”。“地”用于修饰动词，应改为“这个有为的老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的父亲是个有为了的医生。", "corrected_sentence": "他的父亲是个有为的医生。", "error_description": "错误：“有为”后面加了“了”，写成了“有为了的医生”。“了”表示完成或变化，不能插在“有为”与“的”之间，应说“有为的医生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
