INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86210, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指有作为、有出息，多用于年轻人。", "primary_collocate": null, "pronunciation": "yǒu wéi", "ipa": "jou̯˨˩ wei̯˧˥", "syllable_count": 2, "sentences": [{"text": "他年纪不大，却是个有为的青年。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师常说，年轻有为不是靠运气。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸他是个有为的年轻人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业才三年，就成了有为的经理。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望儿子长大后做一个有为的人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位有为的青年办了一家小公司。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村出了几个有为的年轻人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻有为的他，已经买了自己的房子。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，有为的青年从不浪费时间。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司里，他是最有为的年轻人。", "target_word": "有为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有為", "label": "繁体"}, {"form": "年轻有为", "label": "复合"}], "register": "书面", "sense_fingerprint": "有为：年轻人有作为、有出息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有为", "is_correct": true, "explanation": "有为：形容词，指有作为、有出息，与“年纪不大”以及“青年”的语境相符。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“年纪不大”直接矛盾。"}, {"text": "衰老", "is_correct": false, "explanation": "搭配：“衰老”多用于形容身体或状态的老化，不能用来修饰“青年”。"}, {"text": "年长", "is_correct": false, "explanation": "语义：“年长”指岁数较大，与“年纪不大”相冲突。"}], "explanations": {"有为": "有为：形容词，指有作为、有出息，与“年纪不大”以及“青年”的语境相符。", "年迈": "语义：“年迈”指年纪很大，与“年纪不大”直接矛盾。", "衰老": "搭配：“衰老”多用于形容身体或状态的老化，不能用来修饰“青年”。", "年长": "语义：“年长”指岁数较大，与“年纪不大”相冲突。"}, "sentence_index": 0, "correct_answer": "有为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一份有为的工作，待遇也不错。", "explanation": "这里应该用〈有前途〉。“有为”用于形容人的作为与出息，形容工作要说“有前途”。"}, {"text": "这个方法很有为，大家都在用。", "explanation": "这里应该用〈有用〉。“有为”指人有作为，方法有效、管用要说“有用”。"}, {"text": "他有为地学习，每天都很努力。", "explanation": "这里应该用〈刻苦〉。“有为”指人有作为、有出息，不表示勤奋用功的样子，应说“刻苦地学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有为", "is_correct": true, "explanation": "有为：形容词，指年轻人有作为，与“出了几个”的语境相符。"}, {"text": "苍老", "is_correct": false, "explanation": "语义：“苍老”形容老年人的面貌，与“年轻人”的所指相冲突。"}, {"text": "佝偻", "is_correct": false, "explanation": "体貌：“佝偻”描写老人驼背的体态，不能用来形容年轻人。"}, {"text": "老弱", "is_correct": false, "explanation": "语义：“老弱”指老人和体弱者，与“年轻人”相矛盾。"}], "explanations": {"有为": "有为：形容词，指年轻人有作为，与“出了几个”的语境相符。", "苍老": "语义：“苍老”形容老年人的面貌，与“年轻人”的所指相冲突。", "佝偻": "体貌：“佝偻”描写老人驼背的体态，不能用来形容年轻人。", "老弱": "语义：“老弱”指老人和体弱者，与“年轻人”相矛盾。"}, "sentence_index": 6, "correct_answer": "有为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗很有为，每天都帮我看家。", "explanation": "“有为”只用于形容人有作为，不能用来说动物，描写动物可以说“很能干”。"}, {"text": "他的成绩很有为，老师很满意。", "explanation": "“有为”形容人的作为与出息，不能用来修饰“成绩”，应说“成绩很好”。"}, {"text": "这次聚会很有为，大家玩得很开心。", "explanation": "“有为”不用于形容活动或事件，形容聚会应说“热闹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年轻有为她，已经开了自己的公司。", "corrected_sentence": "年轻有为的她，已经开了自己的公司。", "error_description": "错误：“有为”修饰“她”时，中间要加“的”，漏掉“的”说“年轻有为她”不通。正确说法是“年轻有为的她”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个有为地年轻人，已经买了一辆车。", "corrected_sentence": "这个有为的年轻人，已经买了一辆车。", "error_description": "错误：“有为”修饰名词“年轻人”时应用“的”，写成了“地”。“地”用于修饰动词，名词前应用“的”，应说“这个有为的年轻人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
