INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86212, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，指性质相反的物质或作用互相抵消，使其平和。", "primary_collocate": null, "pronunciation": "zhōng hé", "ipa": "tʂʊŋ˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "酸和碱放在一起，可以互相中和。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，碱可以中和胃里太多的酸。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用石灰中和污水里的酸。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这杯酸水倒进碱水里，两种水就中和了。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石灰能中和土壤里的酸性。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验里，我们用碱中和了一杯酸。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正电和负电放在一起，会互相中和。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上中和过一杯盐酸。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碱放多了，要加点酸来中和。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸性太强的水，可以加碱来中和。", "target_word": "中和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中和了", "label": "体标（了）"}, {"form": "中和过", "label": "体标（过）"}, {"form": "中和反应", "label": "复合词"}], "register": "中性", "sense_fingerprint": "酸碱等性质相反的物质或作用互相抵消", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 酸性 (Zipf 3.57), 太强 (Zipf 3.17), 碱 (Zipf 3.56)']::text[], '6f1e2897-790e-4544-bd7b-399254c42829') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中和", "is_correct": true, "explanation": "正确：酸和碱互相抵消，使性质变得平和，与「互相」搭配，符合句意。"}, {"text": "加热", "is_correct": false, "explanation": "语义：加热是使温度升高，酸和碱放在一起是性质互相抵消，不是互相升温，句意不符。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：燃烧是物质与氧气发生的剧烈反应，不是酸碱之间的相互抵消，句子说不通。"}, {"text": "结晶", "is_correct": false, "explanation": "语义：结晶是物质形成晶体的过程，不能用来描述酸和碱互相作用。"}], "explanations": {"中和": "正确：酸和碱互相抵消，使性质变得平和，与「互相」搭配，符合句意。", "加热": "语义：加热是使温度升高，酸和碱放在一起是性质互相抵消，不是互相升温，句意不符。", "燃烧": "语义：燃烧是物质与氧气发生的剧烈反应，不是酸碱之间的相互抵消，句子说不通。", "结晶": "语义：结晶是物质形成晶体的过程，不能用来描述酸和碱互相作用。"}, "sentence_index": 0, "correct_answer": "中和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水通电后会中和成氢和氧。", "explanation": "这里应该用〈分解〉。中和是性质相反的物质互相抵消，一种物质分成几种成分要说「分解」，不能说「中和」。"}, {"text": "冰块放进热水里，很快就中和了。", "explanation": "这里应该用〈融化〉。冰遇热只是由固体变成液体，不是两种性质相反的物质互相抵消，不能用「中和」。"}, {"text": "糖放进水里，很快就中和了。", "explanation": "这里应该用〈溶解〉。糖溶于水是物质分散开来，不是性质相反的物质互相抵消。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中和", "is_correct": true, "explanation": "正确：正电和负电互相抵消，符合「中和」的意思，与「互相」搭配。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：发酵是微生物分解有机物的过程，不会发生在两种电荷之间，「互相发酵」说不通。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：「切割」是单方面的动作，不能和「互相」搭配。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干是用热量使物体变干，不能用来描述两种电荷的作用。"}], "explanations": {"中和": "正确：正电和负电互相抵消，符合「中和」的意思，与「互相」搭配。", "发酵": "语义：发酵是微生物分解有机物的过程，不会发生在两种电荷之间，「互相发酵」说不通。", "切割": "搭配：「切割」是单方面的动作，不能和「互相」搭配。", "烘干": "语义：烘干是用热量使物体变干，不能用来描述两种电荷的作用。"}, "sentence_index": 6, "correct_answer": "中和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁在潮湿空气里慢慢中和了。", "explanation": "这里应该用〈生锈〉。中和是性质相反的物质互相抵消，铁在潮湿空气里与氧反应变红要说「生锈」，不能说「中和」。"}, {"text": "热汤放了一会儿，慢慢中和了。", "explanation": "这里应该用〈冷却〉。温度降低是冷却，不是两种性质相反的物质互相抵消。"}, {"text": "溶液里的杂质慢慢中和了。", "explanation": "这里应该用〈沉淀〉。中和是性质相反的物质互相抵消，杂质沉到容器底部要说「沉淀」，不能说「中和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "加一点碱，就可以把中和这杯酸。", "corrected_sentence": "加一点碱，就可以中和这杯酸。", "error_description": "“把”字句中，“把”后应先接宾语再接动词，不能直接接“中和”；应说“就可以中和这杯酸”或“就可以把这杯酸中和”，错误在于多加了“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在中和了这杯碱水。", "corrected_sentence": "我正在中和这杯碱水。", "error_description": "体标错误：「正在」表示动作进行，不能与「了」同用，应说「正在中和这杯碱水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69824c23-08c6-45a1-b3b1-994f5110f6a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "正：与“副”相对，指居首位的正职，词典列为反义词。"}, {"text": "高", "is_correct": false, "explanation": "高：与“副”没有反义关系，句中不构成对应。"}, {"text": "新", "is_correct": false, "explanation": "新：与“副”没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "远：与“副”没有对立关系。"}], "correct_answer": "正", "explanations": {"正": "正：与“副”相对，指居首位的正职，词典列为反义词。", "高": "高：与“副”没有反义关系，句中不构成对应。", "新": "新：与“副”没有反义关系。", "远": "远：与“副”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正", "is_correct": true, "explanation": "正：与“副”相对，指居首位的正职，词典列为反义词。"}, {"text": "旧", "is_correct": false, "explanation": "旧：与“副”没有反义关系，句中不构成对应。"}, {"text": "深", "is_correct": false, "explanation": "深：与“副”没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "慢：与“副”没有对立关系。"}], "correct_answer": "正", "explanations": {"正": "正：与“副”相对，指居首位的正职，词典列为反义词。", "旧": "旧：与“副”没有反义关系，句中不构成对应。", "深": "深：与“副”没有反义关系。", "慢": "慢：与“副”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“副”是说排在第二位，帮着最大的人做事。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "学校的领导有一正一副。", "target_word": "副", "complexity_tier": "T3", "furigana": "xué xiào de lǐng dǎo yǒu yí zhèng yí fù", "sentence_source": "generated"}, {"text": "班里有一正一副，我是副的。", "target_word": "副", "complexity_tier": "T3", "furigana": "bān lǐ yǒu yí zhèng yí fù, wǒ shì fù de", "sentence_source": "generated"}, {"text": "正的不在，副的来开会。", "target_word": "副", "complexity_tier": "T3", "furigana": "zhèng de bú zài, fù de lái kāi huì", "sentence_source": "generated"}, {"text": "他是正的，我是副的。", "target_word": "副", "complexity_tier": "T3", "furigana": "tā shì zhèng de, wǒ shì fù de", "sentence_source": "generated"}, {"text": "正校长出差了，副校长来了。", "target_word": "副", "complexity_tier": "T3", "furigana": "zhèng xiào zhǎng chū chāi le, fù xiào zhǎng lái le", "sentence_source": "generated"}, {"text": "这所学校有一位正校长和两位副校长。", "target_word": "副", "complexity_tier": "T3", "furigana": "zhè suǒ xué xiào yǒu yí wèi zhèng xiào zhǎng hé liǎng wèi fù xiào zhǎng", "sentence_source": "generated"}, {"text": "他先当副的，后来才当正的。", "target_word": "副", "complexity_tier": "T3", "furigana": "tā xiān dāng fù de, hòu lái cái dāng zhèng de", "sentence_source": "generated"}, {"text": "我只是副的，大事要问正的。", "target_word": "副", "complexity_tier": "T3", "furigana": "wǒ zhǐ shì fù de, dà shì yào wèn zhèng de", "sentence_source": "generated"}, {"text": "那两位一正一副，昨天去了中国。", "target_word": "副", "complexity_tier": "T3", "furigana": "nà liǎng wèi yí zhèng yí fù, zuó tiān qù le zhōng guó", "sentence_source": "generated"}, {"text": "正的管事，副的帮忙。", "target_word": "副", "complexity_tier": "T3", "furigana": "zhèng de guǎn shì, fù de bāng máng", "sentence_source": "generated"}], "morphological_forms": [{"form": "副手", "label": "复合"}, {"form": "副职", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：职位居第二、协助正职的（副校长、副经理）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2434161a-3956-4714-972b-e41f185ec812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "副", "is_correct": true, "explanation": "副：形容词，指职位居第二、协助正职的（fù）。"}, {"text": "夫", "is_correct": false, "explanation": "夫 fū（第一声）与 fù（第四声）声调不同，意思是丈夫。"}, {"text": "府", "is_correct": false, "explanation": "府 fǔ（第三声）与 fù（第四声）声调不同，意思是官府、府邸。"}, {"text": "互", "is_correct": false, "explanation": "互 hù 与 fù 声母不同（h 与 f），意思是互相。"}, {"text": "部", "is_correct": false, "explanation": "部 bù 与 fù 声母不同（b 与 f），意思是部门。"}, {"text": "服", "is_correct": false, "explanation": "服 fú（第二声）与 fù（第四声）声调不同，意思是服装、服从。"}], "explanations": {"副": "副：形容词，指职位居第二、协助正职的（fù）。", "夫": "夫 fū（第一声）与 fù（第四声）声调不同，意思是丈夫。", "府": "府 fǔ（第三声）与 fù（第四声）声调不同，意思是官府、府邸。", "互": "互 hù 与 fù 声母不同（h 与 f），意思是互相。", "部": "部 bù 与 fù 声母不同（b 与 f），意思是部门。", "服": "服 fú（第二声）与 fù（第四声）声调不同，意思是服装、服从。"}, "sentence_index": null, "correct_answer": "副"}, "level_3": {"options": [{"text": "副", "is_correct": true, "explanation": "副：指与“正”相对的副职，“一正一副”正好对应。"}, {"text": "人", "is_correct": false, "explanation": "语义：“人”不是职务名称，“一正一人”不成对，句子说的是职位。"}, {"text": "局", "is_correct": false, "explanation": "搭配：“局”指机构，“正”与“局”不成对，不能说“一正一局”。"}, {"text": "手", "is_correct": false, "explanation": "语义：“手”不表示职位次序，“一正一手”说不通。"}], "explanations": {"副": "副：指与“正”相对的副职，“一正一副”正好对应。", "人": "语义：“人”不是职务名称，“一正一人”不成对，句子说的是职位。", "局": "搭配：“局”指机构，“正”与“局”不成对，不能说“一正一局”。", "手": "语义：“手”不表示职位次序，“一正一手”说不通。"}, "sentence_index": 0, "correct_answer": "副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事是副的，别放在心上。", "explanation": "这里应该用〈次要〉。“副”指职位居第二或辅助的人，不用来说事情的轻重。"}, {"text": "他跑步很快，是全班的副名。", "explanation": "这里应该用〈第二〉。“副”指协助正职的职位，不表示比赛或排名的名次，要说“第二名”。"}, {"text": "这个苹果很副，不好吃。", "explanation": "这里应该用〈差〉。“副”只指职位居第二、协助正职，不能用来说东西质量不好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "副", "is_correct": true, "explanation": "副：形容词，指职位居第二、协助正职的（fù）。"}, {"text": "辅", "is_correct": false, "explanation": "辅 fǔ（第三声）与 fù（第四声）声调不同，意思是辅助。"}, {"text": "路", "is_correct": false, "explanation": "路 lù 与 fù 声母不同（l 与 f），意思是道路。"}, {"text": "户", "is_correct": false, "explanation": "户 hù 与 fù 声母不同（h 与 f），意思是门户、住户。"}, {"text": "布", "is_correct": false, "explanation": "布 bù 与 fù 声母不同（b 与 f），意思是布料。"}, {"text": "福", "is_correct": false, "explanation": "福 fú（第二声）与 fù（第四声）声调不同，意思是幸福。"}], "explanations": {"副": "副：形容词，指职位居第二、协助正职的（fù）。", "辅": "辅 fǔ（第三声）与 fù（第四声）声调不同，意思是辅助。", "路": "路 lù 与 fù 声母不同（l 与 f），意思是道路。", "户": "户 hù 与 fù 声母不同（h 与 f），意思是门户、住户。", "布": "布 bù 与 fù 声母不同（b 与 f），意思是布料。", "福": "福 fú（第二声）与 fù（第四声）声调不同，意思是幸福。"}, "sentence_index": null, "correct_answer": "副"}, "level_3": {"options": [{"text": "副", "is_correct": true, "explanation": "副：指与“正”相对的副职，与后文“当正的”形成对比。"}, {"text": "正", "is_correct": false, "explanation": "语义：“正”与后一分句“后来才当正的”重复，句子的对比关系不成立。"}, {"text": "客", "is_correct": false, "explanation": "搭配：“客”不是职务称谓，不能与“当”构成职务的对比。"}, {"text": "生", "is_correct": false, "explanation": "搭配：“生”不指职位，不能说“当生的”。"}], "explanations": {"副": "副：指与“正”相对的副职，与后文“当正的”形成对比。", "正": "语义：“正”与后一分句“后来才当正的”重复，句子的对比关系不成立。", "客": "搭配：“客”不是职务称谓，不能与“当”构成职务的对比。", "生": "搭配：“生”不指职位，不能说“当生的”。"}, "sentence_index": 6, "correct_answer": "副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑得很副，总是最后一个。", "explanation": "这里应该用〈慢〉。“副”只指协助正职的职位，不能形容速度。"}, {"text": "这本书很副，没什么意思。", "explanation": "这里应该用〈一般〉。“副”只指职位居第二，不能用来评价东西好坏。"}, {"text": "这件衣服太副了，我不想买。", "explanation": "这里应该用〈差〉。“副”只指职位居第二、协助正职，不形容衣服的质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是学校的校副长。", "corrected_sentence": "他是学校的副校长。", "error_description": "“副”要放在职务名称前面，应说“副校长”；“校副长”把“副”放在了中间，是错误语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他担任的是一副校长。", "corrected_sentence": "他担任的是副校长。", "error_description": "“副”在这里是修饰“校长”的形容词，应直接说“副校长”。前面加“一”后，“副”被当作成对事物的量词，“一副校长”说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de9415f9-6ee2-4376-9d7a-240147c1ba90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
