INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86216, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问数量。", "primary_collocate": null, "pronunciation": "duō shao", "ipa": "tuɔ˥ ʂɑʊ", "syllable_count": 2, "sentences": [{"text": "教室里有多少把椅子？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市有多少所大学？", "target_word": "多少", "complexity_tier": "T3", "furigana": "zhè zuò chéngshì yǒu duōshao suǒ dàxué？", "sentence_source": "generated"}, {"text": "你们学校有多少老师？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天喝多少水？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件衣服多少钱？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京有多少人？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天睡了多少小时？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有多少个苹果？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认识多少个汉字？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一共带了多少钱？", "target_word": "多少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "疑问代词，询问数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c09091-d658-4b2c-8dad-66ea54b6e5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多少", "is_correct": true, "explanation": "正确：「多少把椅子」用来询问椅子的数量。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：「什么」不能直接与量词「把」搭配来问数量，应说「多少把」。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」问人，椅子不能用「谁」来问数量。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：「怎样」问性质，不问数量，不能与量词「把」搭配。"}], "explanations": {"多少": "正确：「多少把椅子」用来询问椅子的数量。", "什么": "搭配：「什么」不能直接与量词「把」搭配来问数量，应说「多少把」。", "谁": "语义：「谁」问人，椅子不能用「谁」来问数量。", "怎样": "搭配：「怎样」问性质，不问数量，不能与量词「把」搭配。"}, "sentence_index": 0, "correct_answer": "多少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你星期多少有空？", "explanation": "这里应该用〈几〉。问星期要说「星期几」，「多少」不用于询问星期。"}, {"text": "我们多少点吃饭？", "explanation": "这里应该用〈几〉。问钟点要说「几点」，「多少」不用于询问时刻。"}, {"text": "这学期你是多少年级？", "explanation": "这里应该用〈几〉。问年级要说「几年级」，「多少」不用于询问年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多少", "is_correct": true, "explanation": "正确：「睡了多少小时」用来询问睡眠的时长。"}, {"text": "多久", "is_correct": false, "explanation": "语义：「多久」问时长，但「小时」已经指明单位，不能再与「多久」连用。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：「哪些」表示从几个中挑选，这里问的是睡眠时长，不是选择。"}, {"text": "怎么", "is_correct": false, "explanation": "搭配：「怎么」不能修饰「小时」来问睡眠时长。"}], "explanations": {"多少": "正确：「睡了多少小时」用来询问睡眠的时长。", "多久": "语义：「多久」问时长，但「小时」已经指明单位，不能再与「多久」连用。", "哪些": "语义：「哪些」表示从几个中挑选，这里问的是睡眠时长，不是选择。", "怎么": "搭配：「怎么」不能修饰「小时」来问睡眠时长。"}, "sentence_index": 6, "correct_answer": "多少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们多少月去旅行？", "explanation": "这里应该用〈几〉。问月份要说「几月」，「多少」不用于询问月份。"}, {"text": "我们班多少点下课？", "explanation": "这里应该用〈几〉。问钟点要说「几点」，「多少」不用于询问时刻。"}, {"text": "现在多少点了？", "explanation": "这里应该用〈几〉。问钟点要说「几点」，「多少」不用于询问时刻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
