INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆自行车多多少钱？", "corrected_sentence": "这辆自行车多少钱？", "error_description": "拆词错误：「多少」是疑问词，不能拆开重复写成「多多少」，问价钱应说「多少钱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df381f64-996e-4af7-994f-7762088bac64') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
