INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“举行”是说大家聚在一起，做一件重要的事。", "primary_collocate": null, "pronunciation": "jǔ xíng", "ipa": "tɕy˨˩˦ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学校明天上午举行开学典礼。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在家里举行了一个生日晚会。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们下个月要举行婚礼。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在教室里举行欢送会。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上，公司举行了新年晚会。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业典礼将在九点举行。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们为他举行了一个欢迎会。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，我们班要在公园举行一次聚会。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶八十岁那天，全家举行了庆祝活动。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼在海边举行，天气很好。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举行了", "label": "体标"}, {"form": "举行过", "label": "体标"}, {"form": "正在举行", "label": "体标"}], "register": "正式", "sense_fingerprint": "大家聚在一起办典礼、晚会、聚会等重要活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举行", "is_correct": true, "explanation": "“举行”表示有组织地办一场典礼，与“开学典礼”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“开学典礼”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”一般不带“典礼”这样的宾语，句子不通。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指回想过去，与“明天上午”的将来时间不合。"}], "explanations": {"举行": "“举行”表示有组织地办一场典礼，与“开学典礼”搭配，句意通顺。", "吃": "搭配：“吃”不能带“开学典礼”作宾语。", "唱": "搭配：“唱”一般不带“典礼”这样的宾语，句子不通。", "怀念": "语义：“怀念”指回想过去，与“明天上午”的将来时间不合。"}, "sentence_index": 0, "correct_answer": "举行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师正在举行实验。", "explanation": "这里应该用〈进行〉。“举行”多用于会议、典礼、比赛等有组织的活动，做实验要用“进行”。"}, {"text": "学校举行了一个补习班。", "explanation": "这里应该用〈开办〉。“举行”用于一次性的活动，补习班这类机构要用“开办”。"}, {"text": "他举行了一把伞。", "explanation": "这里应该用〈举起〉。“举行”指组织活动，拿起东西要用“举起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举行", "is_correct": true, "explanation": "“举行”表示为他办一个欢迎会，与“欢迎会”搭配，句意通顺。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能带“欢迎会”作宾语，句子不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能带“欢迎会”作宾语，句子不通。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，后面不能直接带宾语“欢迎会”。"}], "explanations": {"举行": "“举行”表示为他办一个欢迎会，与“欢迎会”搭配，句意通顺。", "煮": "搭配：“煮”不能带“欢迎会”作宾语，句子不通。", "咬": "搭配：“咬”不能带“欢迎会”作宾语，句子不通。", "毕业": "配价：“毕业”是不及物动词，后面不能直接带宾语“欢迎会”。"}, "sentence_index": 6, "correct_answer": "举行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场事故在路口举行了。", "explanation": "这里应该用〈发生〉。“举行”指有人组织的活动，事故是意外发生的，要用“发生”。"}, {"text": "这场大雨举行了很久。", "explanation": "这里应该用〈持续〉。“举行”用于有组织的活动，下雨这样的自然现象要用“持续”。"}, {"text": "班长举行了一个决定。", "explanation": "这里应该用〈作出〉。“举行”用于活动，决定要用“作出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下个月举行了运动会。", "corrected_sentence": "学校下个月举行运动会。", "error_description": "错误：“举行了”。“了”表示动作已经完成，而“下个月”还没有到，应去掉“了”，说“举行运动会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末，公司要在广场举行过一次活动。", "corrected_sentence": "周末，公司要在广场举行一次活动。", "error_description": "错误：“举行过”。“过”表示曾经发生过，与“要”表示的将来矛盾，应去掉“过”，说“要在广场举行一次活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
