INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，指进行会议、比赛、仪式等活动。", "primary_collocate": null, "pronunciation": "jǔ xíng", "ipa": "tɕy˨˩˦ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这次比赛在北京举行。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校举行了一场足球比赛。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议下午三点在大楼里举行。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开幕式什么时候举行？", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会每年秋天举行一次。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人将举行会谈。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司明天上午举行重要的会议。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里正在举行一场音乐比赛。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下周要举行英语演讲比赛。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奥运会曾经在这座城市举行过。", "target_word": "举行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "举行了", "label": "体标"}, {"form": "举行过", "label": "体标"}, {"form": "正在举行", "label": "体标"}], "register": "正式", "sense_fingerprint": "进行会议、比赛、仪式等有组织的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "举行", "is_correct": true, "explanation": "“举行”表示在北京办一场比赛，与“比赛”搭配，句意通顺。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：比赛不能“毕业”，“毕业”只能用于人。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“比赛”搭配，句子不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能与“比赛”搭配，句子不通。"}], "explanations": {"举行": "“举行”表示在北京办一场比赛，与“比赛”搭配，句意通顺。", "毕业": "语义：比赛不能“毕业”，“毕业”只能用于人。", "吃": "搭配：“吃”不能与“比赛”搭配，句子不通。", "煮": "搭配：“煮”不能与“比赛”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "举行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们正在举行一项研究。", "explanation": "这里应该用〈进行〉。“举行”多用于会议、比赛、仪式等有组织的活动，研究要用“进行”。"}, {"text": "她举行了一把椅子。", "explanation": "这里应该用〈举起〉。“举行”指组织活动，拿起椅子要用“举起”。"}, {"text": "学校举行了一所新的幼儿园。", "explanation": "这里应该用〈开办〉。“举行”用于一次性的活动，幼儿园这类机构要用“开办”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "举行", "is_correct": true, "explanation": "“举行”表示公司明天上午开一个重要的会议，与“会议”搭配，句意通顺。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指回想过去，与“明天上午”的将来时间不合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“会议”作宾语，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“会议”作宾语，句子不通。"}], "explanations": {"举行": "“举行”表示公司明天上午开一个重要的会议，与“会议”搭配，句意通顺。", "怀念": "语义：“怀念”指回想过去，与“明天上午”的将来时间不合。", "洗": "搭配：“洗”不能带“会议”作宾语，句子不通。", "唱": "搭配：“唱”不能带“会议”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "举行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次洪水在河边举行了。", "explanation": "这里应该用〈发生〉。“举行”指有人组织的活动，洪水是自然发生的，要用“发生”。"}, {"text": "这场雨举行了好几天。", "explanation": "这里应该用〈持续〉。“举行”用于有组织的活动，下雨要用“持续”。"}, {"text": "老板举行了一个决定。", "explanation": "这里应该用〈作出〉。“举行”用于活动，决定要用“作出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
