INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "艺术是用画画、唱歌、跳舞等办法表现出美的东西。", "primary_collocate": null, "pronunciation": "yì shù", "ipa": "i˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "画画是艺术，唱歌也是艺术。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳舞是一种很美的艺术。", "target_word": "艺术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我女儿在学校学艺术，每天都画画。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有人唱歌，有人跳舞，大家都爱艺术。", "target_word": "艺术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术能让我们看到美。", "target_word": "艺术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小朋友们学艺术，能学到很多美的东西。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人一生都爱艺术，画了很多画。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "歌声和舞蹈都能表现出艺术的美。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不懂艺术，可是觉得这幅画很美。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈带着我去学艺术，我最喜欢跳舞。", "target_word": "艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "藝術", "label": "繁体"}, {"form": "门", "label": "量词"}, {"form": "艺术家", "label": "复合"}, {"form": "艺术品", "label": "复合"}], "register": "中性", "sense_fingerprint": "艺术：用画画、唱歌、跳舞等办法表现美", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：艺术，指用画画、唱歌、跳舞等办法表现美。"}, {"text": "医术", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是医疗技术。"}, {"text": "益鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是对农业有益的鼠类。"}, {"text": "系数", "is_correct": false, "explanation": "xì（第四声）与 yì（第四声）声母不同，意思是数学中的系数。"}], "explanations": {"艺术": "正确：艺术，指用画画、唱歌、跳舞等办法表现美。", "医术": "yī（第一声）与 yì（第四声）声调不同，意思是医疗技术。", "益鼠": "shǔ（第三声）与 shù（第四声）声调不同，意思是对农业有益的鼠类。", "系数": "xì（第四声）与 yì（第四声）声母不同，意思是数学中的系数。"}, "sentence_index": null, "correct_answer": "艺术"}, "level_3": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：画画和唱歌都属于艺术，句中指这一类文化活动。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是体育运动，不是画画、唱歌那样表现美的活动。"}, {"text": "地理", "is_correct": false, "explanation": "语义：地理是学科，与画画、唱歌不属于同一类。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字指数码或数目，画画和唱歌都不是数字，句意不通。"}], "explanations": {"艺术": "正确：画画和唱歌都属于艺术，句中指这一类文化活动。", "游泳": "语义：游泳是体育运动，不是画画、唱歌那样表现美的活动。", "地理": "语义：地理是学科，与画画、唱歌不属于同一类。", "数字": "语义：数字指数码或数目，画画和唱歌都不是数字，句意不通。"}, "sentence_index": 0, "correct_answer": "艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的艺术很先进，效率很高。", "explanation": "这里应该用〈技术〉。机器的先进程度属于技术，“艺术”指表现美的文化活动。"}, {"text": "她的艺术很熟练，每天能缝十件衣服。", "explanation": "这里应该用〈技能〉。“艺术”指表现美的文化活动，缝纫的本领要说“技能”。"}, {"text": "这个零件的艺术很复杂，需要三个工人配合才能完成。", "explanation": "这里应该用〈工序〉。“艺术”指表现美的文化活动，生产中的加工步骤要用“工序”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86219, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：艺术，指用画画、唱歌、跳舞等办法表现美。"}, {"text": "医书", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，shū 与 shù 声调不同，意思是医学书籍。"}, {"text": "技术", "is_correct": false, "explanation": "jì（第四声）与 yì（第四声）声母不同，意思是技术、技能。"}, {"text": "一束", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，shù 相同，意思是一捆、一把。"}], "explanations": {"艺术": "正确：艺术，指用画画、唱歌、跳舞等办法表现美。", "医书": "yī（第一声）与 yì（第四声）声调不同，shū 与 shù 声调不同，意思是医学书籍。", "技术": "jì（第四声）与 yì（第四声）声母不同，意思是技术、技能。", "一束": "yī（第一声）与 yì（第四声）声调不同，shù 相同，意思是一捆、一把。"}, "sentence_index": null, "correct_answer": "艺术"}, "level_3": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：句中指老人一生所爱的艺术活动，与后面画画的内容相符。"}, {"text": "烦恼", "is_correct": false, "explanation": "搭配：“爱”一般不接“烦恼”这类负面状态的名词。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，人不会一生热爱它，与“爱”搭配不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，人不会一生热爱它，与“爱”搭配不通。"}], "explanations": {"艺术": "正确：句中指老人一生所爱的艺术活动，与后面画画的内容相符。", "烦恼": "搭配：“爱”一般不接“烦恼”这类负面状态的名词。", "感冒": "语义：感冒是疾病，人不会一生热爱它，与“爱”搭配不通。", "地震": "语义：地震是自然灾害，人不会一生热爱它，与“爱”搭配不通。"}, "sentence_index": 6, "correct_answer": "艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套焊接设备的艺术很落后，常常断电。", "explanation": "这里应该用〈技术〉。“艺术”指表现美的文化活动，设备的先进程度属于技术。"}, {"text": "这家纺织厂的艺术很落后，布料质量很差。", "explanation": "这里应该用〈工艺〉。“艺术”指表现美的文化活动，工厂的加工方法和水平要用“工艺”。"}, {"text": "这座桥的艺术很结实，几十年都没坏。", "explanation": "这里应该用〈结构〉。“艺术”指表现美的文化活动，桥的构造是否结实要用“结构”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXC