INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用形象、声音、动作等手段反映生活、表达情感的文化活动，如绘画、音乐、舞蹈。", "primary_collocate": null, "pronunciation": "yì shù", "ipa": "i˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "画画、唱歌和跳舞都是艺术。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐是一种艺术。", "target_word": "艺术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所大学教绘画、音乐和舞蹈等艺术。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学了十年舞蹈，对这门艺术很有感情。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "艺术可以让人表达自己的感情。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画很美，是真正的艺术。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在他看来，艺术来自生活。", "target_word": "艺术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电影也是一种艺术，能让人看到生活。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在艺术中学会了表达自己。", "target_word": "艺术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师把中国画介绍给学生，说这是一门古老的艺术。", "target_word": "艺术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "藝術", "label": "繁体"}, {"form": "门", "label": "量词"}, {"form": "艺术家", "label": "复合"}, {"form": "艺术品", "label": "复合"}], "register": "中性", "sense_fingerprint": "艺术：用形象、声音、动作反映生活、表达情感的文化活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0962041-b86f-4f5b-b465-232c20626925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86220, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：艺术，指用画画、唱歌、跳舞等形式表现美的活动。"}, {"text": "技术", "is_correct": false, "explanation": "jì（第四声）与 yì（第四声）声母不同，意思是技术、技能。"}, {"text": "医术", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是医疗技术。"}, {"text": "益鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是对农业有益的鼠类。"}, {"text": "系数", "is_correct": false, "explanation": "xì（第四声）与 yì（第四声）声母不同，意思是数学中的系数。"}], "explanations": {"艺术": "正确：艺术，指用画画、唱歌、跳舞等形式表现美的活动。", "技术": "jì（第四声）与 yì（第四声）声母不同，意思是技术、技能。", "医术": "yī（第一声）与 yì（第四声）声调不同，意思是医疗技术。", "益鼠": "shǔ（第三声）与 shù（第四声）声调不同，意思是对农业有益的鼠类。", "系数": "xì（第四声）与 yì（第四声）声母不同，意思是数学中的系数。"}, "sentence_index": null, "correct_answer": "艺术"}, "level_3": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：画画、唱歌、跳舞都属于艺术，句中指这一类文化活动。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是体育运动，不属于画画、唱歌、跳舞这类文艺活动。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是画画、唱歌、跳舞那样的活动。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是画画、唱歌、跳舞那样的文化活动。"}], "explanations": {"艺术": "正确：画画、唱歌、跳舞都属于艺术，句中指这一类文化活动。", "游泳": "语义：游泳是体育运动，不属于画画、唱歌、跳舞这类文艺活动。", "数学": "语义：数学是学科，不是画画、唱歌、跳舞那样的活动。", "地震": "语义：地震是自然灾害，不是画画、唱歌、跳舞那样的文化活动。"}, "sentence_index": 0, "correct_answer": "艺术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂引进了新艺术，生产效率提高了很多。", "explanation": "这里应该用〈技术〉。“艺术”指表现美的文化活动，生产工艺和机器方法要用“技术”。"}, {"text": "他的艺术很熟练，三天就能做好一把椅子。", "explanation": "这里应该用〈手艺〉。“艺术”指表现美的文化活动，木工的技艺要说“手艺”。"}, {"text": "这个学徒的艺术进步很快，半年就能独立修车。", "explanation": "这里应该用〈技能〉。“艺术”指表现美的文化活动，修车的本领要说“技能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86220, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：艺术，指用画画、唱歌、跳舞等形式表现美的活动。"}, {"text": "医书", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，shū（第一声）与 shù（第四声）声调也不同，意思是医学书籍。"}, {"text": "一束", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，shù 相同，意思是一捆、一把。"}, {"text": "记述", "is_correct": false, "explanation": "jì（第四声）与 yì（第四声）声母不同，意思是记录并叙述。"}], "explanations": {"艺术": "正确：艺术，指用画画、唱歌、跳舞等形式表现美的活动。", "医书": "yī（第一声）与 yì（第四声）声调不同，shū（第一声）与 shù（第四声）声调也不同，意思是医学书籍。", "一束": "yī（第一声）与 yì（第四声）声调不同，shù 相同，意思是一捆、一把。", "记述": "jì（第四声）与 yì（第四声）声母不同，意思是记录并叙述。"}, "sentence_index": null, "correct_answer": "艺术"}, "level_3": {"options": [{"text": "艺术", "is_correct": true, "explanation": "正确：句中指艺术这一类活动，是“来自生活”的主语。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球是天体，不是从生活中产生的文化活动。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能说“来自生活”这种抽象的理解。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日常用品，不是反映生活的文化活动，说“雨伞来自生活”不通。"}], "explanations": {"艺术": "正确：句中指艺术这一类活动，是“来自生活”的主语。", "地球": "语义：地球是天体，不是从生活中产生的文化活动。", "汽车": "语义：汽车是交通工具，不能说“来自生活”这种抽象的理解。", "雨伞": "语义：雨伞是日常用品，不是反映生活的文化活动，说“雨伞来自生活”不通。"}, "sentence_index": 6, "correct_answer": "艺术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间工厂的艺术很落后，产品质量很差。", "explanation": "这里应该用〈工艺〉。“艺术”指表现美的文化活动，生产中的加工方法和水平要用“工艺”。"}, {"text": "这套房子的艺术很大，光卧室就有五间。", "explanation": "这里应该用〈面积〉。“艺术”指表现美的文化活动，房子的大小要用“面积”。"}, {"text": "这个零件的艺术很复杂，需要三个工人配合才能完成。", "explanation": "这里应该用〈工序〉。“艺术”指表现美的文化活动，生产中的加工步骤要用“工序”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只艺术很美，我每天都练习。", "corrected_sentence": "这门艺术很美，我每天都练习。", "error_description": "量词错误：“艺术”的量词应为“门”，“只”用于动物等。错误形式是“这只艺术”，正确形式是“这门艺术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只艺术很难学，但他学得很认真。", "corrected_sentence": "这门艺术很难学，但他学得很认真。", "error_description": "量词错误：“艺术”的量词应为“门”，错误形式是“这只艺术”，正确形式是“这门艺术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98b5a4cf-7669-4ed4-b455-fc83b20db20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
