INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电话是可以让我们和很远的人说话的东西。", "primary_collocate": null, "pronunciation": "diàn huà", "ipa": "tjɛn˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "家里的电话坏了，我听不到声音。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一部电话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶不会用手机，她只用家里的电话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电话很旧，但是还能用。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以用电话告诉远方的朋友这个好消息。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在北京，我们用电话跟他说话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话放在床边，晚上也能听到。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拿起电话，想跟奶奶说话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话是红色的，我很喜欢。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前没有手机，大家都用电话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "电话卡", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以和远方的人说话的东西，指机器本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话", "is_correct": true, "explanation": "“电话”指机器，坏了会影响通话，与“听不到声音”相符，可以填入空格。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”坏了与“听不到声音”没有关系。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：“电灯”本身不发声，坏了不会影响“听”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：一般不说“书坏了”，也与“听不到声音”无关。"}], "explanations": {"电话": "“电话”指机器，坏了会影响通话，与“听不到声音”相符，可以填入空格。", "椅子": "语义：“椅子”坏了与“听不到声音”没有关系。", "电灯": "语义：“电灯”本身不发声，坏了不会影响“听”。", "书": "搭配：一般不说“书坏了”，也与“听不到声音”无关。"}, "sentence_index": 0, "correct_answer": "电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张电话很旧，但是还能用。", "explanation": "这里应该用〈部〉。“张”多用于平面的东西，电话机要用“部”。"}, {"text": "桌子上放着一封电话。", "explanation": "这里应该用〈部〉。“封”用于信件，电话机要用“部”。"}, {"text": "他买了一只电话。", "explanation": "这里应该用〈部〉。“只”多用于动物，电话机要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电话", "is_correct": true, "explanation": "“电话”放在床边，晚上能听到铃声，与句子相符，可以填入空格。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不会在晚上发出可以听到的声音。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”不会发出声音，晚上听不到。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“听到”的对象应是声音，“鞋子”不能与“听到”搭配。"}], "explanations": {"电话": "“电话”放在床边，晚上能听到铃声，与句子相符，可以填入空格。", "桌子": "语义：“桌子”不会在晚上发出可以听到的声音。", "沙发": "语义：“沙发”不会发出声音，晚上听不到。", "鞋子": "搭配：“听到”的对象应是声音，“鞋子”不能与“听到”搭配。"}, "sentence_index": 6, "correct_answer": "电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的电话很大，全家都爱看。", "explanation": "这里应该用〈电视〉。“看”的对象是节目，要说“电视”，电话不能用来看。"}, {"text": "我用电话写作业，写得很快。", "explanation": "这里应该用〈电脑〉。写作业要用“电脑”，电话不能用来写字。"}, {"text": "我用电话洗衣服，很省力。", "explanation": "这里应该用〈洗衣机〉。洗衣服要用“洗衣机”，电话不能用来洗衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上挂着一张电话。", "corrected_sentence": "墙上挂着一部电话。", "error_description": "量词错误：电话机应用“部”，“张”多用于平面的东西，不能用于电话机。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床边放着一条电话。", "corrected_sentence": "床边放着一部电话。", "error_description": "量词错误：电话机应用“部”，“条”多用于细长的东西，不能用于电话机。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
