INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "通过电信号传送声音，使两地的人能够通话的设备或通话本身。", "primary_collocate": null, "pronunciation": "diàn huà", "ipa": "tjɛn˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈给我打了一个电话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在接电话，请你等一下。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上你为什么不接我的电话？", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我家打电话，说我生病了。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把电话给我，我想跟他说话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话响了，我马上跑过去接。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在跟朋友讲电话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里有一部电话，可以打到外地。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在开会，不方便接电话。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，刚才电话里的声音不太清楚。", "target_word": "电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "电话卡", "label": "复合"}], "register": "中性", "sense_fingerprint": "通话设备或通话本身，可接、可打", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话", "is_correct": true, "explanation": "“打电话”是固定搭配，“电话”可以填入空格，表示一次通话。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“打”不能和“电视”搭配，应说“看电视”。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“打”不能和“电影”搭配，应说“看电影”。"}, {"text": "电灯", "is_correct": false, "explanation": "语义：“电灯”不是通讯工具，不能用来“打”给别人。"}], "explanations": {"电话": "“打电话”是固定搭配，“电话”可以填入空格，表示一次通话。", "电视": "搭配：“打”不能和“电视”搭配，应说“看电视”。", "电影": "搭配：“打”不能和“电影”搭配，应说“看电影”。", "电灯": "语义：“电灯”不是通讯工具，不能用来“打”给别人。"}, "sentence_index": 0, "correct_answer": "电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给我打了一部电话。", "explanation": "这里应该用〈通〉或〈个〉。“打电话”的一次通话可用“通”或“个”，“部”用于电话机，不能用于通话。"}, {"text": "我家买了一只电话。", "explanation": "这里应该用〈部〉。“只”多用于动物，电话机要用“部”。"}, {"text": "桌子上摆着一封电话。", "explanation": "这里应该用〈部〉。“封”用于信件，电话机要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电话", "is_correct": true, "explanation": "“讲电话”是常见说法，“电话”可以填入空格，表示通话。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“讲”不能和“电脑”搭配，电脑不是用来“讲”的。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：“电梯”是升降设备，不能成为“讲”的对象。"}, {"text": "电池", "is_correct": false, "explanation": "语义：“电池”是供电装置，不能成为“讲”的内容。"}], "explanations": {"电话": "“讲电话”是常见说法，“电话”可以填入空格，表示通话。", "电脑": "搭配：“讲”不能和“电脑”搭配，电脑不是用来“讲”的。", "电梯": "语义：“电梯”是升降设备，不能成为“讲”的对象。", "电池": "语义：“电池”是供电装置，不能成为“讲”的内容。"}, "sentence_index": 6, "correct_answer": "电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上收听电话的新闻节目。", "explanation": "这里应该用〈电台〉。收听的是广播，要说“电台”，“电话”只用于通话。"}, {"text": "我们全家每天晚上都看电话。", "explanation": "这里应该用〈电视〉。看的是节目，要说“电视”，“电话”不能用来看。"}, {"text": "我每天给妈妈发电话，告诉她我的情况。", "explanation": "这里应该用〈短信〉。“电话”是通话，不能用“发”，“发”接的是“短信”这类信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天晚上给我打了一只电话。", "corrected_sentence": "他昨天晚上给我打了一个电话。", "error_description": "量词错误：“打电话”的“电话”是一次通话，可说“一通电话”或“一个电话”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天给我打了三封电话。", "corrected_sentence": "他昨天给我打了三个电话。", "error_description": "量词错误：一次通话可说“一个电话”或“一通电话”，“封”用于信件，不能用于电话。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
