INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "日常生活中使用的。", "primary_collocate": null, "pronunciation": "rì yòng", "ipa": "ɻ̩˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "牙刷和毛巾都是日用的东西。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里卖很多日用的东西。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店专门卖日用的物品。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家时，我先买了一些日用的东西。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西都是日用的，不贵。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈周末去市场买日用的东西。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友寄了一箱日用的东西。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些日用的东西，家里不能少。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗发水、肥皂都是日用的。", "target_word": "日用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行时，只带日用的东西就够了。", "target_word": "日用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日用品", "label": "复合"}, {"form": "日用百货", "label": "复合"}], "register": "通用", "sense_fingerprint": "日常生活中使用的（修饰物品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfe20271-9b49-478a-a8e6-68fb9be44438') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日用", "is_correct": true, "explanation": "正确：牙刷和毛巾都是日常生活中使用的物品，与“日用”的含义相符。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：牙刷和毛巾价格低廉，说它们“昂贵”与常识相反。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：牙刷和毛巾不是易碎品，说它们“易碎”与其材质和用途不符。"}, {"text": "珍奇", "is_correct": false, "explanation": "语域：“珍奇”偏书面，指稀罕之物，与平常的牙刷、毛巾不相称。"}], "explanations": {"日用": "正确：牙刷和毛巾都是日常生活中使用的物品，与“日用”的含义相符。", "昂贵": "语义：牙刷和毛巾价格低廉，说它们“昂贵”与常识相反。", "易碎": "语义：牙刷和毛巾不是易碎品，说它们“易碎”与其材质和用途不符。", "珍奇": "语域：“珍奇”偏书面，指稀罕之物，与平常的牙刷、毛巾不相称。"}, "sentence_index": 0, "correct_answer": "日用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坚持日用锻炼，身体很好。", "explanation": "这里应该用〈日常〉。日用只修饰日常使用的物品，“锻炼”要用“日常”。"}, {"text": "这是一个日用的理论。", "explanation": "这里应该用〈实用〉。日用指物品在日常生活中使用，“理论”不是物品，要用“实用”。"}, {"text": "这是一项日用的检查。", "explanation": "这里应该用〈常规〉。日用指物品在日常生活中使用，“检查”要用“常规”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日用", "is_correct": true, "explanation": "正确：“日用”修饰日常使用的物品，与“寄一箱东西”的语境相符。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：滚烫的东西不能装箱寄送，与“寄一箱”的语境矛盾。"}, {"text": "无形", "is_correct": false, "explanation": "语义：无形的东西无法装进箱子，与“一箱”的具体数量矛盾。"}, {"text": "年迈", "is_correct": false, "explanation": "搭配：“年迈”多形容人或动物，不用来修饰“东西”。"}], "explanations": {"日用": "正确：“日用”修饰日常使用的物品，与“寄一箱东西”的语境相符。", "滚烫": "语义：滚烫的东西不能装箱寄送，与“寄一箱”的语境矛盾。", "无形": "语义：无形的东西无法装进箱子，与“一箱”的具体数量矛盾。", "年迈": "搭配：“年迈”多形容人或动物，不用来修饰“东西”。"}, "sentence_index": 6, "correct_answer": "日用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个日用的周末。", "explanation": "这里应该用〈平常〉。日用只修饰日常使用的物品，“周末”要用“平常”。"}, {"text": "他是一个日用的学生。", "explanation": "这里应该用〈普通〉。日用只修饰日常使用的物品，不能用来修饰人。"}, {"text": "我日用的工作很多。", "explanation": "这里应该用〈每日〉。日用修饰物品，“工作”要用“每日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了几件很日用的东西。", "corrected_sentence": "我买了几件日用的东西。", "error_description": "区别词误用：“日用”修饰名词时不能受“很”修饰，应说“日用的东西”，不说“很日用的东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行时，我们只带日用的品就够了。", "corrected_sentence": "旅行时，我们只带日用品就够了。", "error_description": "结构错误：“日用品”是固定复合词，“品”不能单独与“日用的”组合，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba4155ca-be3b-4518-8830-7044e11b5664') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "依赖", "is_correct": true, "explanation": "正确：“依赖”与“独立”意思相反，指需要靠别人，不能自己做事。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与“独立”没有反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”形容事务多，与“独立”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人亲切主动，与“独立”没有反义关系。"}], "correct_answer": "依赖", "explanations": {"依赖": "正确：“依赖”与“独立”意思相反，指需要靠别人，不能自己做事。", "迟钝": "“迟钝”形容反应慢，与“独立”没有反义关系。", "繁忙": "“繁忙”形容事务多，与“独立”没有反义关系。", "热情": "“热情”形容待人亲切主动，与“独立”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "依赖", "is_correct": true, "explanation": "正确：“依赖”与“独立”意思相反，指需要靠别人，不能自己做事。"}, {"text": "混乱", "is_correct": false, "explanation": "“混乱”形容秩序无章，与“独立”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或态度平和，与“独立”没有反义关系。"}, {"text": "坚定", "is_correct": false, "explanation": "“坚定”形容意志或立场不动摇，与“独立”没有反义关系。"}], "correct_answer": "依赖", "explanations": {"依赖": "正确：“依赖”与“独立”意思相反，指需要靠别人，不能自己做事。", "混乱": "“混乱”形容秩序无章，与“独立”没有反义关系。", "温和": "“温和”形容性情或态度平和，与“独立”没有反义关系。", "坚定": "“坚定”形容意志或立场不动摇，与“独立”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“独立”是自己能做自己的事，不用别人帮忙。", "primary_collocate": null, "pronunciation": "dú lì", "ipa": "tu˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我儿子才六岁，已经很独立了。", "target_word": "独立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很独立，自己洗衣服，自己做饭。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要学会独立，不能什么都靠爸妈。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上大学以后，我变得越来越独立。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十八岁就搬出去住，生活很独立。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "独立的孩子会自己整理书包。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，女孩子也要独立生活。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不太独立，出门还要妈妈陪着。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就独立，十岁就会自己坐车上学。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人希望孩子们都能独立，不用他担心。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獨立", "label": "繁体"}, {"form": "独立生活", "label": "复合"}], "register": "中性", "sense_fingerprint": "独立：能自己照顾自己，不用别人帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "独立", "is_correct": true, "explanation": "正确：独立 dú lì，指能自己做事，不靠别人。"}, {"text": "图利", "is_correct": false, "explanation": "tú（第二声）与 dú（第二声）声母不同，图利意思是谋取利益，不是独立。"}, {"text": "图例", "is_correct": false, "explanation": "tú 与 dú 只差送气（t 与 d），图例指地图或图表上的说明符号，不是独立。"}, {"text": "毒理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，毒理指毒物对机体的作用原理。"}], "explanations": {"独立": "正确：独立 dú lì，指能自己做事，不靠别人。", "图利": "tú（第二声）与 dú（第二声）声母不同，图利意思是谋取利益，不是独立。", "图例": "tú 与 dú 只差送气（t 与 d），图例指地图或图表上的说明符号，不是独立。", "毒理": "lǐ（第三声）与 lì（第四声）声调不同，毒理指毒物对机体的作用原理。"}, "sentence_index": null, "correct_answer": "独立"}, "level_3": {"options": [{"text": "独立", "is_correct": true, "explanation": "正确：“已经很独立了”说孩子能自己做事，与“才六岁”的语境相符。"}, {"text": "年迈", "is_correct": false, "explanation": "语义：“年迈”指年纪很大，与“才六岁”矛盾。"}, {"text": "富裕", "is_correct": false, "explanation": "搭配：“富裕”说家境或物质条件，不用来形容孩子的能力。"}, {"text": "衰老", "is_correct": false, "explanation": "体貌：“衰老”指身体机能退化，与六岁孩子的状态不符。"}], "explanations": {"独立": "正确：“已经很独立了”说孩子能自己做事，与“才六岁”的语境相符。", "年迈": "语义：“年迈”指年纪很大，与“才六岁”矛盾。", "富裕": "搭配：“富裕”说家境或物质条件，不用来形容孩子的能力。", "衰老": "体貌：“衰老”指身体机能退化，与六岁孩子的状态不符。"}, "sentence_index": 0, "correct_answer": "独立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他独立一人把三个孩子养大了。", "explanation": "这里应该用〈独自〉。“独立”表示不靠别人、自己做事，不表示只有一个人；“独自一人”才表示只有一个人。"}, {"text": "他靠独立更生，走出了困境，从不肯求人。", "explanation": "这里应该用〈自力〉。“自力更生”是固定说法，“独立更生”不成词。"}, {"text": "他靠独立修好了屋顶，不用找人帮忙。", "explanation": "这里应该用〈自己〉。“靠自己”表示凭自己的力量，“独立”是形容人的性格和能力，不能放在“靠”后面这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立生活”指不靠父母、自己过日子，与“女孩子也要”的劝导相符。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：“懒散”指做事松懈，与妈妈劝勉的语境相反。"}, {"text": "奢侈", "is_correct": false, "explanation": "语义：“奢侈”指花费过度，与“也要……生活”的劝导不符。"}, {"text": "孤僻", "is_correct": false, "explanation": "语义：“孤僻”形容性格不合群，与“也要……生活”所劝勉的自立相反。"}], "explanations": {"独立": "正确：“独立生活”指不靠父母、自己过日子，与“女孩子也要”的劝导相符。", "懒散": "语义：“懒散”指做事松懈，与妈妈劝勉的语境相反。", "奢侈": "语义：“奢侈”指花费过度，与“也要……生活”的劝导不符。", "孤僻": "语义：“孤僻”形容性格不合群，与“也要……生活”所劝勉的自立相反。"}, "sentence_index": 6, "correct_answer": "独立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生有独立权，可以自己决定选什么课。", "explanation": "这里应该用〈自主〉。“自主权”是常用说法，“独立权”不这样说。“独立”表示不靠别人、自己做事，不表示自己做主。"}, {"text": "我想独立跟老师谈谈，请给我一点时间。", "explanation": "这里应该用〈单独〉。“独立”表示不靠别人、自己做事，不能像“单独”那样直接修饰“跟老师谈”。"}, {"text": "他很独立，每天都要父母陪着才肯出门。", "explanation": "这里应该用〈依赖〉。“独立”表示不靠别人，“依赖”才表示靠别人；句子说要父母陪着，应该用“依赖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹很独立，能照顾自己的生活独立。", "corrected_sentence": "我妹妹很独立，能照顾自己的生活。", "error_description": "错误：句末多出一个“独立”，与前面的“很独立”重复，成了多余的成分。去掉句末的“独立”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈想孩子独立，不要事事都帮忙。", "corrected_sentence": "妈妈想让孩子独立，不要事事都帮忙。", "error_description": "错误：“想”后接“孩子独立”这类兼语结构时，需要用“让”引出，漏掉“让”说“想孩子独立”不通。正确说法是“想让孩子独立”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
