INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86226, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，指不依靠别人，自己站立或自主处事。", "primary_collocate": null, "pronunciation": "dú lì", "ipa": "tu˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个宝宝已经能独立站着了。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做作业时，请你独立思考。", "target_word": "独立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他独立完成了这项工作。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要有独立的想法，不要只听别人的。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人扶着墙慢慢站起来，想独立走几步。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们独立做出了这个决定，没有问别人。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想独立做完这道题，请不要告诉我答案。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官要独立判断，不能听别人的话。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看书时喜欢独立想问题。", "target_word": "独立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有独立的看法，不会别人说什么就信什么。", "target_word": "独立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "獨立", "label": "繁体"}, {"form": "独立思考", "label": "复合"}], "register": "中性", "sense_fingerprint": "独立：不靠别人，自己站立或自主做事、思考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '770dabe8-fdf1-4187-a580-c627c38b0951') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "独立", "is_correct": true, "explanation": "正确：独立 dú lì，指不靠别人，自己站立或做事、思考。"}, {"text": "图利", "is_correct": false, "explanation": "tú（第二声）与 dú（第二声）声母不同，图利意思是谋取利益，不是独立。"}, {"text": "逐利", "is_correct": false, "explanation": "zhú 与 dú 声母不同（zh 与 d），逐利意思是追逐利益。"}, {"text": "毒理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，毒理指毒物对机体的作用原理。"}], "explanations": {"独立": "正确：独立 dú lì，指不靠别人，自己站立或做事、思考。", "图利": "tú（第二声）与 dú（第二声）声母不同，图利意思是谋取利益，不是独立。", "逐利": "zhú 与 dú 声母不同（zh 与 d），逐利意思是追逐利益。", "毒理": "lǐ（第三声）与 lì（第四声）声调不同，毒理指毒物对机体的作用原理。"}, "sentence_index": null, "correct_answer": "独立"}, "level_3": {"options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立站着”指不借助他人支撑自己站立，符合宝宝刚学会站的情况。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，宝宝不说高大。"}, {"text": "端庄", "is_correct": false, "explanation": "语义：“端庄”形容仪态庄重，与宝宝站立的情境不符。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容神情或态度，与宝宝站着的情境不符。"}], "explanations": {"独立": "正确：“独立站着”指不借助他人支撑自己站立，符合宝宝刚学会站的情况。", "高大": "体貌：“高大”形容身材，宝宝不说高大。", "端庄": "语义：“端庄”形容仪态庄重，与宝宝站立的情境不符。", "严肃": "语义：“严肃”形容神情或态度，与宝宝站着的情境不符。"}, "sentence_index": 0, "correct_answer": "独立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他独立一人去了山里，很久没有回来。", "explanation": "这里应该用〈独自〉。“独立”表示不靠别人、自己做事，不表示只有一个人；“独自一人”才表示只有一个人。"}, {"text": "她独立在家，不敢开门。", "explanation": "这里应该用〈独自〉。“独立”表示不靠别人、自己做事，不表示一个人待着；“独自在家”才表示只有一个人。"}, {"text": "他独立地哭了一个晚上。", "explanation": "这里应该用〈独自〉。“独立”表示不靠别人、自己做事；“独自”才表示一个人。哭不存在靠不靠别人的问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独立", "is_correct": true, "explanation": "正确：“独立做完”指自己完成，与“请不要告诉我答案”的语境相符。"}, {"text": "分工", "is_correct": false, "explanation": "语法：“分工”是动词，不能直接修饰“做完”，且意思是各人分担，与想自己完成的语境相反。"}, {"text": "草草", "is_correct": false, "explanation": "语义：“草草”指敷衍了事，与认真完成题目的语境相反。"}, {"text": "轮流", "is_correct": false, "explanation": "搭配：“轮流”强调交替进行，不能用来修饰一人完成一道题的“做完”。"}], "explanations": {"独立": "正确：“独立做完”指自己完成，与“请不要告诉我答案”的语境相符。", "分工": "语法：“分工”是动词，不能直接修饰“做完”，且意思是各人分担，与想自己完成的语境相反。", "草草": "语义：“草草”指敷衍了事，与认真完成题目的语境相反。", "轮流": "搭配：“轮流”强调交替进行，不能用来修饰一人完成一道题的“做完”。"}, "sentence_index": 6, "correct_answer": "独立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想独立找老师谈谈，请给我一点时间。", "explanation": "这里应该用〈单独〉。“独立”表示不靠别人、自己做事，不表示一个人去找老师面谈。"}, {"text": "他独立坐在角落里，一句话也不说。", "explanation": "这里应该用〈独自〉。“独立”表示不靠别人、自己做事；“独自”才表示只有一个人待着。"}, {"text": "下雨了，她独立撑着伞走回了家。", "explanation": "这里应该用〈独自〉。句子说的是她一个人回家，不是不靠别人，所以应该用“独自”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末他独立一人在家看书。", "corrected_sentence": "周末他独自一人在家看书。", "error_description": "错误：“独立”表示不靠别人、自主做事，不表示只有一个人；“一个人在家”应该用“独自”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想独立着做完作业，不用你帮我。", "corrected_sentence": "我想独立做完作业，不用你帮我。", "error_description": "错误：“独立”直接放在动词前作状语，后面不能加“着”。删去“着”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbac179c-a0fd-4457-b983-a8bdf26d2864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慢", "is_correct": false, "explanation": "不是反义词：“慢”指速度低，与“美”没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, {"text": "长", "is_correct": false, "explanation": "不是反义词：“长”指距离或时间大，与“美”没有相对关系。"}, {"text": "厚", "is_correct": false, "explanation": "不是反义词：“厚”指厚度大，与“美”没有相对关系。"}], "correct_answer": "丑", "explanations": {"慢": "不是反义词：“慢”指速度低，与“美”没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。", "长": "不是反义词：“长”指距离或时间大，与“美”没有相对关系。", "厚": "不是反义词：“厚”指厚度大，与“美”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "硬", "is_correct": false, "explanation": "不是反义词：“硬”指不软，与“美”没有相对关系。"}, {"text": "轻", "is_correct": false, "explanation": "不是反义词：“轻”指重量小，与“美”没有相对关系。"}, {"text": "远", "is_correct": false, "explanation": "不是反义词：“远”指距离长，与“美”没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}], "correct_answer": "丑", "explanations": {"硬": "不是反义词：“硬”指不软，与“美”没有相对关系。", "轻": "不是反义词：“轻”指重量小，与“美”没有相对关系。", "远": "不是反义词：“远”指距离长，与“美”没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“美”是说看起来很好看，让人高兴。", "primary_collocate": null, "pronunciation": "měi", "ipa": "meɪ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这条裙子真美，我想买下来。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她穿红色的衣服很美。", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这朵花开得很美，我拍了一张照片。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上的那幅画真美。", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新娘今天太美了，大家都看着她。", "target_word": "美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的字写得很美，老师常常夸她。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "院子里的花那么美，我每天都去看。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小鸟的羽毛真美，红红绿绿的。", "target_word": "美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，她的眼睛多美啊！", "target_word": "美", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件旗袍很美，她穿着更好看。", "target_word": "美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美丽", "label": "复合"}, {"form": "美美", "label": "重叠"}], "register": "中性", "sense_fingerprint": "单用作谓语，形容人、衣物、花、画等外表看起来漂亮好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c7e51ce-19b3-4ce8-8dfa-fa8a07b5b200') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "正确：“美”（měi，第三声）是本词，意思是外表好看。"}, {"text": "妹", "is_correct": false, "explanation": "mèi（第四声）与 měi（第三声）声调不同，意思是妹妹。"}, {"text": "没", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是不、没有。"}, {"text": "煤", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是煤。"}], "explanations": {"美": "正确：“美”（měi，第三声）是本词，意思是外表好看。", "妹": "mèi（第四声）与 měi（第三声）声调不同，意思是妹妹。", "没": "méi（第二声）与 měi（第三声）声调不同，意思是不、没有。", "煤": "méi（第二声）与 měi（第三声）声调不同，意思是煤。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "脏", "is_correct": false, "explanation": "语义：“脏”表示不干净，与“我想买下来”的喜爱相反。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不能用来形容裙子，这里不成立。"}, {"text": "美", "is_correct": true, "explanation": "正确：“美”形容裙子好看，与“我想买下来”的喜欢相合。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不能用来形容裙子，这里不成立。"}], "explanations": {"脏": "语义：“脏”表示不干净，与“我想买下来”的喜爱相反。", "矮": "搭配：“矮”说高度，不能用来形容裙子，这里不成立。", "美": "正确：“美”形容裙子好看，与“我想买下来”的喜欢相合。", "高": "搭配：“高”说高度，不能用来形容裙子，这里不成立。"}, "sentence_index": 0, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的结果很美。", "explanation": "这里应该用〈好〉。“美”形容外观，不用于考试结果，结果好要说“好”。"}, {"text": "这次考试的分数很美，我考了满分。", "explanation": "这里应该用〈高〉。“美”形容外观，不用于分数，分数高要说“高”。"}, {"text": "我的牙很美，今天不能吃东西。", "explanation": "这里应该用〈疼〉。“美”不用于身体的疼痛，牙疼要说“疼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "美", "is_correct": true, "explanation": "正确：“美”（měi，第三声）是本词，意思是外表好看。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 měi（第三声）声母不同（b 与 m），意思是北方。"}, {"text": "眉", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是眉毛。"}, {"text": "梅", "is_correct": false, "explanation": "méi（第二声）与 měi（第三声）声调不同，意思是梅花。"}, {"text": "买", "is_correct": false, "explanation": "mǎi 与 měi 韵母不同（ǎi 与 ěi），声调相同，意思是买。"}], "explanations": {"美": "正确：“美”（měi，第三声）是本词，意思是外表好看。", "北": "běi（第三声）与 měi（第三声）声母不同（b 与 m），意思是北方。", "眉": "méi（第二声）与 měi（第三声）声调不同，意思是眉毛。", "梅": "méi（第二声）与 měi（第三声）声调不同，意思是梅花。", "买": "mǎi 与 měi 韵母不同（ǎi 与 ěi），声调相同，意思是买。"}, "sentence_index": null, "correct_answer": "美"}, "level_3": {"options": [{"text": "吵", "is_correct": false, "explanation": "搭配：“吵”形容声音，不能用来形容花的样子，“花那么吵”不成立。"}, {"text": "美", "is_correct": true, "explanation": "正确：“美”形容花好看，与“我每天都去看”的喜爱相合。"}, {"text": "旧", "is_correct": false, "explanation": "搭配：“旧”说物品新旧，不能用来形容花的外貌，这里不成立。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”说温度，不能用来形容花的外貌，这里不成立。"}], "explanations": {"吵": "搭配：“吵”形容声音，不能用来形容花的样子，“花那么吵”不成立。", "美": "正确：“美”形容花好看，与“我每天都去看”的喜爱相合。", "旧": "搭配：“旧”说物品新旧，不能用来形容花的外貌，这里不成立。", "冷": "搭配：“冷”说温度，不能用来形容花的外貌，这里不成立。"}, "sentence_index": 6, "correct_answer": "美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次出差的开销很美，我们付不起。", "explanation": "这里应该用〈贵〉。“美”不用于开销，开销高要说“贵”。"}, {"text": "这次作业的难度很美，我做不完。", "explanation": "这里应该用〈难〉。“美”形容外观，不用于难度，难度大要说“难”。"}, {"text": "我很美，想吃饭了。", "explanation": "这里应该用〈饿〉。“美”形容外貌，不能表示饥饿的感觉，饿了要说“饿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗前的花真很美。", "corrected_sentence": "窗前的花真美。", "error_description": "“真”和“很”不能同时修饰“美”，应删去“很”，写作“真美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小鸟美真。", "corrected_sentence": "那只小鸟真美。", "error_description": "“真”是程度副词，要放在“美”前面，应为“真美”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86228, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": false, "explanation": "不是反义词：“冷”指温度低，与“美”的意思没有相对关系。"}, {"text": "丑", "is_correct": true, "explanation": "正确：“丑”与“美”意思相反，指外貌难看、不好看。"}, {"text": "快", "is_correct": false, "explanation": "不是反义词：“快”指速度高，与“美”没有相对关系。"}, {"text": "硬", "is_correct": false, "explanation": "不是反义词：“硬”指不软，与“美”没有相对关系。"}], "correct_answer": "丑", "explanations": {"冷": "不是反义词：“冷”指温度低，与“美”的意思没有相对关系。", "丑": "正确：“丑”与“美”意思相反，指外貌难看、不好看。", "快": "不是反义词：“快”指速度高，与“美”没有相对关系。", "硬": "不是反义词：“硬”指不软，与“美”没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
