INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86233, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“连”是把两个东西接在一起。", "primary_collocate": null, "pronunciation": "lián", "ipa": "ljɛn˧˥", "syllable_count": 1, "sentences": [{"text": "这座桥连着两个小岛。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两根线连起来。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机连不上网。", "target_word": "连", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条路连着学校和车站。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电脑和电视连在一起。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把电源连好，再打开机器。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车一节连着一节，真长。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管没连好，地上都是水。", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个房间是连着的，中间开了一扇门。", "target_word": "连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的电脑连上网了吗？", "target_word": "连", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "連", "label": "繁体"}, {"form": "连着", "label": "体标"}, {"form": "连接", "label": "复合"}, {"form": "连起来", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "连：把两样东西接在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c7e51ce-19b3-4ce8-8dfa-fa8a07b5b200') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86233, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "连", "is_correct": true, "explanation": "连（lián，第二声）：把两样东西接在一起，是本题的词。"}, {"text": "年", "is_correct": false, "explanation": "年（nián）声母 n 与 l 不同，声调相同，意思是年份。"}, {"text": "脸", "is_correct": false, "explanation": "脸（liǎn，第三声）与连声调不同，意思是脸面。"}, {"text": "练", "is_correct": false, "explanation": "练（liàn，第四声）与连声调不同，意思是练习。"}], "explanations": {"连": "连（lián，第二声）：把两样东西接在一起，是本题的词。", "年": "年（nián）声母 n 与 l 不同，声调相同，意思是年份。", "脸": "脸（liǎn，第三声）与连声调不同，意思是脸面。", "练": "练（liàn，第四声）与连声调不同，意思是练习。"}, "sentence_index": null, "correct_answer": "连"}, "level_3": {"options": [{"text": "连", "is_correct": true, "explanation": "连：把两个东西接在一起，正是“这座桥连着两个小岛”的意思。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”用于人或动物的居所，不能用来说桥与小岛。"}, {"text": "放", "is_correct": false, "explanation": "语义：“放”表示搁置，不能说桥与小岛相接。"}, {"text": "装", "is_correct": false, "explanation": "语义：“装”表示盛放东西，与桥连接两岛的意思不合。"}], "explanations": {"连": "连：把两个东西接在一起，正是“这座桥连着两个小岛”的意思。", "住": "搭配：“住”用于人或动物的居所，不能用来说桥与小岛。", "放": "语义：“放”表示搁置，不能说桥与小岛相接。", "装": "语义：“装”表示盛放东西，与桥连接两岛的意思不合。"}, "sentence_index": 0, "correct_answer": "连"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "连他妈妈都不知道这件事。", "explanation": "这里的“连”是“甚至”的意思（连……都），与“把两样东西接在一起”无关。"}, {"text": "他连一句话都没说。", "explanation": "这里的“连”是“甚至”的意思（连……都），与“接在一起”无关。"}, {"text": "连着下了五天雨，路都淹了。", "explanation": "这里的“连着”表示接连不断，是另一个义项，与“接在一起”不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86233, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "连", "is_correct": true, "explanation": "连（lián，第二声）：把两样东西接在一起，是本题的词。"}, {"text": "林", "is_correct": false, "explanation": "林（lín）韵母比连的 ian 少了 a，声调相同，意思是树林。"}, {"text": "兰", "is_correct": false, "explanation": "兰（lán）韵母 ian 变成 an，声调相同，意思是兰花。"}, {"text": "凉", "is_correct": false, "explanation": "凉（liáng）韵尾 n 换成 ng，声调相同，意思是凉爽。"}], "explanations": {"连": "连（lián，第二声）：把两样东西接在一起，是本题的词。", "林": "林（lín）韵母比连的 ian 少了 a，声调相同，意思是树林。", "兰": "兰（lán）韵母 ian 变成 an，声调相同，意思是兰花。", "凉": "凉（liáng）韵尾 n 换成 ng，声调相同，意思是凉爽。"}, "sentence_index": null, "correct_answer": "连"}, "level_3": {"options": [{"text": "连", "is_correct": true, "explanation": "连：一节接一节地相接，符合“火车一节连着一节”的意思。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”表示移动，不能描述车厢相连的状态。"}, {"text": "站", "is_correct": false, "explanation": "语义：“站”表示静止，与“一节接一节”的相接不合。"}, {"text": "躺", "is_correct": false, "explanation": "体貌：“躺”说人的姿势，不能用于火车车厢。"}], "explanations": {"连": "连：一节接一节地相接，符合“火车一节连着一节”的意思。", "跑": "语义：“跑”表示移动，不能描述车厢相连的状态。", "站": "语义：“站”表示静止，与“一节接一节”的相接不合。", "躺": "体貌：“躺”说人的姿势，不能用于火车车厢。"}, "sentence_index": 6, "correct_answer": "连"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他连一个字都不认识。", "explanation": "这里的“连”是“甚至”的意思，与“把两样东西接在一起”无关。"}, {"text": "我们连着工作了十个小时。", "explanation": "这里的“连着”表示接连不断，是另一个义项，不表示接在一起。"}, {"text": "连我妈妈都夸他。", "explanation": "这里的“连”是“甚至”的意思，与“接在一起”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的手机连了上网，你看看吧。", "corrected_sentence": "我的手机连上了网，你看看吧。", "error_description": "错误：“了”应放在补语“上”之后，说“连上了网”；写成“连了上网”语序不对。正确应为“连上了网”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥连了着两岸，车很多。", "corrected_sentence": "这座桥连着两岸，车很多。", "error_description": "错误：“连着”表示状态，后面不需要“了”，“了”多加在“连”和“着”之间。正确应为“连着两岸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b268d74d-6786-4d74-8f85-b1d48d0279b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
