INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86235, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "片是用来数薄薄的东西的词。", "primary_collocate": null, "pronunciation": "piàn", "ipa": "pʰjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "我吃了一片面包。", "target_word": "片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有一片叶子。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他给我两片药。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈切了几片肉。", "target_word": "片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一片饼干放进嘴里。", "target_word": "片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一片碎玻璃。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在汤里放了三片姜。", "target_word": "片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在面包上放了一片奶酪。", "target_word": "片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿着一片西瓜走过来。", "target_word": "片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药一次吃一片。", "target_word": "片", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "照片", "label": "复合"}, {"form": "药片", "label": "复合"}, {"form": "一片片", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词，用来数面包、肉、药、叶子等薄片状的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39686117-ff5b-4662-b33e-7c30377afa02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86235, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "片", "is_correct": true, "explanation": "片：量词，用于数薄片状的东西，如一片面包。"}, {"text": "篇", "is_correct": false, "explanation": "篇 piān（第一声）与 piàn（第四声）声调不同，意思是篇（文章的量词）。"}, {"text": "偏", "is_correct": false, "explanation": "偏 piān（第一声）与 piàn（第四声）声调不同，意思是不正、歪。"}, {"text": "变", "is_correct": false, "explanation": "变 biàn 与 piàn 声母不同（b 与 p），意思是变化。"}, {"text": "面", "is_correct": false, "explanation": "面 miàn 与 piàn 声母不同（m 与 p），意思是面粉、面条等。"}], "explanations": {"片": "片：量词，用于数薄片状的东西，如一片面包。", "篇": "篇 piān（第一声）与 piàn（第四声）声调不同，意思是篇（文章的量词）。", "偏": "偏 piān（第一声）与 piàn（第四声）声调不同，意思是不正、歪。", "变": "变 biàn 与 piàn 声母不同（b 与 p），意思是变化。", "面": "面 miàn 与 piàn 声母不同（m 与 p），意思是面粉、面条等。"}, "sentence_index": null, "correct_answer": "片"}, "level_3": {"options": [{"text": "片", "is_correct": true, "explanation": "正确：“片”用于薄片状的东西，“一片面包”自然。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对物件中的一个，不用于数面包。"}, {"text": "朵", "is_correct": false, "explanation": "语义：“朵”用于花、云等，不能用来数面包。"}, {"text": "滴", "is_correct": false, "explanation": "语义：“滴”用于液体，不能用来数面包。"}], "explanations": {"片": "正确：“片”用于薄片状的东西，“一片面包”自然。", "只": "搭配：“只”多用于动物或成对物件中的一个，不用于数面包。", "朵": "语义：“朵”用于花、云等，不能用来数面包。", "滴": "语义：“滴”用于液体，不能用来数面包。"}, "sentence_index": 0, "correct_answer": "片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一片书。", "explanation": "这里应该用〈本〉。“片”用于薄片状的东西，书要用“本”来数。"}, {"text": "院子里有一片马。", "explanation": "这里应该用〈匹〉。“片”用于薄片状的东西，马要用“匹”来数。"}, {"text": "我喝了一片果汁。", "explanation": "这里通常用〈杯〉。果汁是液体，可用“杯”或“瓶”计量，不能用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片", "is_correct": true, "explanation": "正确：“片”用于薄片状的姜，“三片姜”自然。"}, {"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”指装东西的容器，不能用来数姜片。"}, {"text": "杯", "is_correct": false, "explanation": "搭配：“杯”用于计量饮品，姜片不能用“杯”来数。"}, {"text": "缸", "is_correct": false, "explanation": "语义：“缸”是大型容器，不能用来数姜片。"}], "explanations": {"片": "正确：“片”用于薄片状的姜，“三片姜”自然。", "瓶": "语义：“瓶”指装东西的容器，不能用来数姜片。", "杯": "搭配：“杯”用于计量饮品，姜片不能用“杯”来数。", "缸": "语义：“缸”是大型容器，不能用来数姜片。"}, "sentence_index": 6, "correct_answer": "片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一片电脑。", "explanation": "这里应该用〈台〉。电脑是机器，要用量词“台”，“片”用于薄片状的东西。"}, {"text": "妈妈穿了一片衣服。", "explanation": "这里通常用〈件〉。衣服用“件”来数，“片”不能用于衣服。"}, {"text": "妈妈买了一片鞋。", "explanation": "这里应该用〈双〉。“片”用于平而薄的东西，鞋要成双计数，用“双”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他撕下了一片的纸。", "corrected_sentence": "他撕下了一片纸。", "error_description": "错误形式：一片的纸。正确形式：一片纸。原因：“一片”后直接接“的”再接光杆名词（无修饰语）不自然，应说“一片纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
