INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "片", "is_correct": true, "explanation": "正确：“一片绿色”指成片的绿色景象，句意自然。"}, {"text": "滴", "is_correct": false, "explanation": "语义：“滴”用于液体，不能用来数绿色的景象。"}, {"text": "股", "is_correct": false, "explanation": "语义：“股”用于气流、水流等，不能用来数绿色。"}, {"text": "根", "is_correct": false, "explanation": "搭配：“根”用于细长的东西，不能用来数绿色的景象。"}], "explanations": {"片": "正确：“一片绿色”指成片的绿色景象，句意自然。", "滴": "语义：“滴”用于液体，不能用来数绿色的景象。", "股": "语义：“股”用于气流、水流等，不能用来数绿色。", "根": "搭配：“根”用于细长的东西，不能用来数绿色的景象。"}, "sentence_index": 6, "correct_answer": "片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上放着一片电话。", "explanation": "这里应该用〈部〉。电话要用“部”来数，“片”用于成片的地方或景物。"}, {"text": "他买了一片汽车。", "explanation": "这里应该用〈辆〉。汽车要用“辆”来数，“片”不能用于汽车。"}, {"text": "他戴着一片手表。", "explanation": "这里应该用〈块〉。手表要用“块”来数，“片”用于成片的地方或景物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上有大一片松树林。", "corrected_sentence": "山坡上有一大片松树林。", "error_description": "语序错误：“大”应放在“一”之后、“片”之前，说“一大片”，不能说“大一片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e65b8434-e0fe-4d9e-83e1-4929ab504216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
