INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：“单一”指只有一种，与“各种”的多样相对。"}, {"text": "亲自", "is_correct": false, "explanation": "“亲自”指本人动手，与“各种”没有反义关系。"}, {"text": "某", "is_correct": false, "explanation": "“某”指不确定的一个，与“各种”没有反义关系。"}, {"text": "每", "is_correct": false, "explanation": "“每”指全体中的每一个，与“各种”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：“单一”指只有一种，与“各种”的多样相对。", "亲自": "“亲自”指本人动手，与“各种”没有反义关系。", "某": "“某”指不确定的一个，与“各种”没有反义关系。", "每": "“每”指全体中的每一个，与“各种”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：“单一”指只有一种，与“各种”的多样相对。"}, {"text": "独自", "is_correct": false, "explanation": "“独自”指一个人，与“各种”没有反义关系。"}, {"text": "整个", "is_correct": false, "explanation": "“整个”指全部、完整，与“各种”没有反义关系。"}, {"text": "本", "is_correct": false, "explanation": "“本”指这个，与“各种”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：“单一”指只有一种，与“各种”的多样相对。", "独自": "“独自”指一个人，与“各种”没有反义关系。", "整个": "“整个”指全部、完整，与“各种”没有反义关系。", "本": "“本”指这个，与“各种”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "“各种”是说有很多不同的样子和种类。", "primary_collocate": null, "pronunciation": "gè zhǒng", "ipa": "kɤ˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "商店里有各种水果。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着各种书。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃各种好吃的菜。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上买了各种东西。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有各种颜色的花。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有各种运动。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在这里买到各种衣服。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱玩各种游戏。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的各种东西都很便宜。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书店看了各种杂志。", "target_word": "各种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各种各样", "label": "复合"}], "register": "中性", "sense_fingerprint": "很多不同样子、不同种类的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d31e622-4b28-4b23-8714-313fa02ff361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各种", "is_correct": true, "explanation": "正确：“各种”表示多种多样，与“水果”搭配，符合句意。"}, {"text": "某", "is_correct": false, "explanation": "搭配：“某”后需接“种”或量词，不能直接说“某水果”。"}, {"text": "同一", "is_correct": false, "explanation": "语义：“同一”指相同的一个，与商店里有多种水果的意思不符。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与商店里种类多样的水果不符。"}], "explanations": {"各种": "正确：“各种”表示多种多样，与“水果”搭配，符合句意。", "某": "搭配：“某”后需接“种”或量词，不能直接说“某水果”。", "同一": "语义：“同一”指相同的一个，与商店里有多种水果的意思不符。", "单一": "语义：“单一”指只有一种，与商店里种类多样的水果不符。"}, "sentence_index": 0, "correct_answer": "各种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "除了小明，各种同学都来了。", "explanation": "这里应该用〈其他〉。“各种”强调种类多样，不能表示除某人外的其余同学，那里应该用“其他”。"}, {"text": "全班同学只有小王一个人及格，各种同学都没及格。", "explanation": "这里应该用〈所有〉。“各种”指多种不同的，不能用来指全部同学，那里要说“所有同学”。"}, {"text": "他各种星期都去游泳。", "explanation": "这里应该用〈每个〉。“各种”说的是种类多样，不能修饰“星期”这类时间单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各种", "is_correct": true, "explanation": "正确：“各种”表示多种多样，可以修饰“衣服”，符合句意。"}, {"text": "每", "is_correct": false, "explanation": "搭配：“每”后要接量词，应说“每件衣服”，不能说“每衣服”。"}, {"text": "唯一", "is_correct": false, "explanation": "语义：“唯一”指只有一个，与“可以买到各种衣服”的语境不符。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”不能修饰“衣服”，不能说“本衣服”。"}], "explanations": {"各种": "正确：“各种”表示多种多样，可以修饰“衣服”，符合句意。", "每": "搭配：“每”后要接量词，应说“每件衣服”，不能说“每衣服”。", "唯一": "语义：“唯一”指只有一个，与“可以买到各种衣服”的语境不符。", "本": "搭配：“本”不能修饰“衣服”，不能说“本衣服”。"}, "sentence_index": 6, "correct_answer": "各种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的各种老师只有一位，就是李老师。", "explanation": "这里应该用〈唯一〉。“各种”指多种不同的，老师有各种就不可能只有一位，不能用来限定唯一的人。"}, {"text": "这件衣服只有各种颜色，就是红色。", "explanation": "这里应该用〈一种〉。“只有……就是红色”说的是一种颜色，“各种”指很多种类，两者矛盾。"}, {"text": "这家店只卖各种面包，就是白面包。", "explanation": "这里应该用〈一种〉。“只卖”限定为一类，“各种”指很多种类，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "超市里有很各种饮料。", "corrected_sentence": "超市里有各种饮料。", "error_description": "错误：“各种”是区别词，不能受“很”修饰。应说“各种饮料”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校有一各种社团。", "corrected_sentence": "我们学校有各种社团。", "error_description": "错误：“各种”前面不能加数词“一”，应直接说“各种社团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '675948d2-e057-4fcf-905b-f920fec33edd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
