INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86239, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“它们”是说好几只小动物或好几样东西。", "primary_collocate": null, "pronunciation": "tā men", "ipa": "tʰa˥ mən", "syllable_count": 2, "sentences": [{"text": "院子里有三只小鸟，它们在唱歌。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有两只小猫，它们很可爱。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有几本书，它们都是新的。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这些小鱼，每天都给它们喂吃的。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上有很多蚂蚁，它们在搬东西。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果很甜，你可以尝尝它们。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两只小狗饿了，快给它们一点吃的。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的花开了，它们红红的，很好看。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鞋子脏了，我要把它们洗干净。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几只小兔子很怕冷，它们都躲在笼子里。", "target_word": "它们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "它", "label": "单数形式"}, {"form": "它們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指代前面提到的几只小动物或几样东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 院子 (Zipf 3.93), 三只 (Zipf 3.5), 小鸟 (Zipf 3.85)','sentence 9 above tier T1: 3 words above tier T1 (max 2): 几只 (Zipf 3.53), 小兔子 (Zipf 3.09), 笼子 (Zipf 3.78)']::text[], 'b149f1bb-a04c-4874-9c02-4b65b2bbfa14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86239, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "它们", "is_correct": true, "explanation": "“它们”指前面提到的三只小鸟，指代正确，句意通顺。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，小鸟不是人，不能用来指代“三只小鸟”。"}, {"text": "它", "is_correct": false, "explanation": "搭配：“它”是单数，不能指代“三只小鸟”这样的复数名词。"}, {"text": "她们", "is_correct": false, "explanation": "语义：“她们”指女性人群，小鸟不是人，不能这样指代。"}], "explanations": {"它们": "“它们”指前面提到的三只小鸟，指代正确，句意通顺。", "他们": "语义：“他们”指人，小鸟不是人，不能用来指代“三只小鸟”。", "它": "搭配：“它”是单数，不能指代“三只小鸟”这样的复数名词。", "她们": "语义：“她们”指女性人群，小鸟不是人，不能这样指代。"}, "sentence_index": 0, "correct_answer": "它们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友都很热情，它们每次都来帮我。", "explanation": "这里应该用〈他们〉。“它们”指人以外的事物或动物，指人要用“他们”。"}, {"text": "这群老人每天都去公园，它们很开心。", "explanation": "这里应该用〈他们〉。“它们”不指人，指这群老人要用“他们”。"}, {"text": "我妈妈和姐姐很忙，它们每天都很早出门。", "explanation": "这里应该用〈她们〉。“它们”不指人，指女性人群要用“她们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "它们", "is_correct": true, "explanation": "“它们”指前面提到的两只小狗，指代正确，句意通顺。"}, {"text": "她", "is_correct": false, "explanation": "搭配：“她”是单数，且指女性，不能指“两只小狗”。"}, {"text": "她们", "is_correct": false, "explanation": "语义：“她们”指女性人群，小狗不是人，不能这样指代。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指说话对象，句中的“小狗”不是说话对象。"}], "explanations": {"它们": "“它们”指前面提到的两只小狗，指代正确，句意通顺。", "她": "搭配：“她”是单数，且指女性，不能指“两只小狗”。", "她们": "语义：“她们”指女性人群，小狗不是人，不能这样指代。", "你们": "语义：“你们”指说话对象，句中的“小狗”不是说话对象。"}, "sentence_index": 6, "correct_answer": "它们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板和经理都很忙，它们每天都开会。", "explanation": "这里应该用〈他们〉。“它们”不指人，指老板和经理这些人要用“他们”。"}, {"text": "我们班的同学都很努力，它们每天都学习。", "explanation": "这里应该用〈他们〉。“它们”不指人，指班里的同学这些人要用“他们”。"}, {"text": "女孩子们很喜欢画画，它们每天都在教室里练习。", "explanation": "这里应该用〈她们〉。“它们”不指人，指这些女孩子要用“她们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草地上有两只兔子，它在吃草。", "corrected_sentence": "草地上有两只兔子，它们在吃草。", "error_description": "错误：“它”。“两只兔子”是复数，指代时要用复数形式“它们”，“它”是单数形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个碗脏了，我要把它们洗干净。", "corrected_sentence": "这个碗脏了，我要把它洗干净。", "error_description": "错误：“它们”。“这个碗”只有一个，是单数，指代时要用“它”，“它们”指好几样东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3659f44-0e5b-4b49-8d81-33fe4dd6c525') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
